\label{th:Diff}
As $t\to\infty$,
\begin{equ} \label{e:Diff}
D(t) = D_0 + \big(d^{\lim} + o(1)\big) \, \log(t)^{2/3}\, \mathfrak{e} \mathfrak{e}^T \, ,
\end{equ}
where
\begin{equ} \label{e:dlim}
d^{\lim} \stackrel{\mbox{\tiny\rm def}}{=} \Big(\frac{3}{2\pi}\Big)^{2/3}\frac{\lambda^{4/3} \, \varrho^{2/3} (1 - \varrho)^{2/3}}{D_0[\mathfrak{f},\mathfrak{f}]^{1/3}} \, .
\end{equ}

\label{th:CLT2ndClass}
Under $\mathbf P_{\nu_\varrho}^{\mathrm{II}}$,
\begin{equ} \label{e:CLT2ndClass}
(\Sigma^t)^{-1}(X_t-tv) \xrightarrow[t\to\infty]{\mathrm{law}} \mathcal N(0,D^{\lim}) \, ,
\end{equ}
where $\mathcal N(0,D^{\lim})$ denotes the centred Gaussian law on $\mathbb{R}^2$ with covariance matrix
\begin{equ} \label{e:Dlim}
D^{\lim} \stackrel{\mbox{\tiny\rm def}}{=} d^{\lim} \, \mathfrak{e} \mathfrak{e}^T + D_0[\mathfrak{f},\mathfrak{f}] \, \mathfrak{f} \mathfrak{f}^T \, .
\end{equ}

\label{th:CLT}
As $\tau \to \infty$, the law of $(Y_t^\tau)_{t \geq 0}$ under $\mathbf P_{\nu_\varrho}$ converges weakly to the law of $(Y_t^{\lim})_{t \geq 0}$ under $\mathbf P_{\mathbb P}^{\lim}$, in the Skorokhod topology of $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. Equivalently, for every bounded continuous functional $F \colon D(\mathbb{R}_+,\mathcal{S}'(\mathbb{R}^2)) \to \mathbb{R}$,
\begin{equ} \label{e:CLTFunctional}
\mathbf E_{\nu_\varrho}[F(Y_\cdot^\tau)] \xrightarrow[\tau\to\infty]{} \mathbf E_{\mathbb P}^{\lim}[F(Y_\cdot^{\lim})] \, .
\end{equ}

Furthermore, the convergence holds conditionally on the microscopic initial configuration $\eta$ with high probability under $\nu_\varrho(\mathrm{d} \eta)$, in the following sense. For every bounded continuous functional $F$ as above,
\begin{equ} \label{e:CLTFunctionalQuenched}
\int_{\Omega} \nu_\varrho(\mathrm{d} \eta) \, \big|\mathbf E_\eta[F(Y_\cdot^\tau)]-\mathbf E_{Z_0^\tau[\eta]}^{\lim}[F(Y_\cdot^{\lim})]\big| \xrightarrow[\tau\to\infty]{} 0 \, .
\end{equ}

\label{rmk:Unidirectional}
We briefly discuss the role of Assumption~\ref{ass:Unidirectional}. In fact, this assumption is only important here to determine the precise prefactor of the diffusivity asymptotics and the precise scaling limit of the fluctuation process. Indeed, with little extra effort, the techniques developed in this paper can be adapted to show that, without Assumption~\ref{ass:Unidirectional}, there still exists $C \in (0, \infty)$ such that for sufficiently large time $t$
\begin{equ}
C^{-1} \log(t)^{2/3} \leq D_{\parallel}(t) \leq C \log(t)^{2/3} \, ,
\end{equ}
and the laws of the rescaled fluctuation process $(Y_t^\tau)_{t \geq 0}$ under $\mathbf P_{\nu_\varrho}$ are still tight in $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. For more details, see Remark~\ref{rmk:wRemoval}.

\label{def:N}

Let $\mathcal{N}$ be the operator which maps $f = (f_n)_{n \geq 0} \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$ to $\mathcal{N} f := (n f_n)_{n \geq 0}$ ; similarly, let $\mathcal{N}_*$ be the operator which maps $f = (f_n)_{n \geq 0} \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$ to $\mathcal{N}_* f := (n_* f_n)_{n \geq 0}$ where $n_* := 1 \vee n$. We denote by $N$ (and $N_*$) the restriction of $\mathcal{N}$ (and $\mathcal{N}_*$) to $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
$. 

Let $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
$ be the subspace consisting of $f = (f_n)_{n \geq 0} \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$ such that $\|\mathcal{N}_*^k f\|$ is finite for every $k \geq 0$. We denote $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
 = 
    \def#2{}
    \ifx#2\empty
