    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
$. We equip $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
$ with its natural Fréchet metric.

\label{lem:Gen}
The generator $L$ equals $S + A \stackrel{\mbox{\tiny\rm def}}{=} S + A_+ + A_- + A_0$ on $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
{}$ (which is a core for $L$), where the operators $S, A_+, A_-, A_0$ act (continuously) from $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
{}$ to itself as follows, for $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
{}$,
\begin{equs}
\label{e:S}
S f (x_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} \sum_{i=1}^n \sum_{z \in \mathbb{Z}^2} \1_{HC}(x_{1:n}, x_i + z) \, s(z) \, \big(f(x_i + z, x_{1:n \setminus i}) - f(x_{1:n})\big) \, , \\
\label{e:A+}
A_+ f (x_{1:n+1}) &\stackrel{\mbox{\tiny\rm def}}{=} \frac{2 \sqrt{\varrho (1-\varrho)}}{n+1} \sum_{1 \leq i < j \leq n+1} \1_{HC}(x_{1:n+1}) \, a(x_j - x_i) \, \big(f(x_{1:n+1 \setminus i}) - f(x_{1:n+1 \setminus j})\big) \, , \\
\label{e:A-}
A_- f(x_{1:n-1}) &\stackrel{\mbox{\tiny\rm def}}{=} - 2 \sqrt{\varrho(1-\varrho)} \, n \sum_{i=1}^{n-1} \sum_{z \in \mathbb{Z}^2} \1_{HC}(x_{1:n-1}, x_i+z) \, a(z) \, f(x_i + z, x_{1:n-1}) \, , \\
\label{e:A0}
A_0 f(x_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} (1 - 2 \varrho) \sum_{i=1}^n \sum_{z \in \mathbb{Z}^2} \1_{HC}(x_{1:n}, x_i+z) \, a(z) \, \big(f(x_i + z, x_{1:n \setminus i}) - f(x_{1:n})\big) \, .
\end{equs}
On $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
$, the operator $S$ is essentially self-adjoint while $A$ is skew-symmetric as we have $(A_+)^* = - A_-$ and $(A_0)^* = - A_0$. Observe that, for any $n \geq 0$, the operators $S$, $A_+$, $A_-$, $A_0$ map $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$ respectively to $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n+1}
    \else
        \Gamma_0 h^{}_{n+1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n-1}
    \else
        \Gamma_0 h^{}_{n-1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$.

