    \fi
{}}$}
              {S\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}}}$ can be seen as the $s$-weighted discrete Laplacian on $\mathbb{Z}^{2n} \setminus DI$ with Neumann boundary condition. In particular, the following integration by parts formula holds: if we define for any $z \in \mathbb{Z}^2$ the operator $\nabla_z^0$ acting from $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
{}$ to $F \ell^2$ as
\begin{equ} \label{e:nablaz0}
\nabla_z^0 f(x_{1:n}) = \1_{HC}(x_1 + z, x_{1:n}) \, (f(x_1 + z, x_{2:n}) - f(x_{1:n})) \, ,
\end{equ}
then, for any $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$, we have
\begin{equ} \label{e:NeumannBC}
\|(- S)^{1/2} f\|^2 = \langle (-S) f, f\rangle = \frac{n}{2} \sum_{z \in \mathbb{Z}^2} s(z) \, \|\nabla_z^0 f\|^2 \, .
\end{equ}

\label{rmk:A0}
The operator $A_0$ can be heuristically interpreted as a discrete transport operator with corresponding velocity $v = (1 - 2 \varrho) \mathfrak{w}$ (in particular, observe that $A_0 = 0$ when $\varrho = 1/2$). Indeed, after omitting the hard-core constraint and expanding $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
$ at first order around $x_{1:n}$, we formally obtain $A_0 f \approx v \cdot (\nabla_{x_1} + \cdots + \nabla_{x_n}) f$. Therefore, the Galilean change of variables $x \to x + t v$ performed in the definition~\eqref{e:Ztau} of $Y_t^\tau$ is designed to cancel the action of $A_0$.

\label{rmk:noGSC}
An important difficulty here is that, contrary to systems at the supercritical dimension or in the weak coupling regime, no graded sector condition holds: the generator is not bounded from $H^1$ to $H^{-1}$, even if it is restricted to a finite number of chaoses. For example, it can be checked that
\begin{equ} \label{e:noGSC}
\sup_{f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
, \, f \not \equiv 0} \frac{\|(\mu - S)^{-1/2} \, A_+ f\|}{\|(\mu - S)^{1/2} f\|} \asymp \log_*(1/\mu)^{1/2} \, .
\end{equ}

\label{def:SoftCore}
Let us define the operators $\mathcal{L} \stackrel{\mbox{\tiny\rm def}}{=} \mathcal{S} + \mathcal{A} \stackrel{\mbox{\tiny\rm def}}{=} \mathcal{S} + \mathcal{A}_+ + \mathcal{A}_- + \mathcal{A}_0$ acting (continuously) from $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
{}$ to itself, by the corresponding formulas~\eqref{e:S},~\eqref{e:A+},~\eqref{e:A-},~\eqref{e:A0} with the indicators $\1_{HC}(...)$ removed. In terms of the Fourier transform, they act on $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
$ as follows
\begin{equs}
\label{e:FcS}
\mathcal{F} (\mathcal{S} f) \, (k_{1:n}) &= - \frac{1}{2} \, d_0(k_{1:n}) \, \mathcal{F} f (k_{1:n}) \, , \\
\label{e:FcA+}
\mathcal{F} (\mathcal{A}_+ f) \, (k_{1:n+1}) &= \frac{\sqrt{\varrho(1-\varrho)}}{\pi (n+1)} \sum_{1 \leq i < j \leq n+1} \iota \, (w(k_i) + w(k_j)) \, \ \mathcal{F} f (k_i + k_j, k_{1:n+1 \setminus i,j}) \, , \\
\label{e:FcA-}
\mathcal{F} (\mathcal{A}_- f) \, (k_{1:n-1}) &= \frac{\sqrt{\varrho(1-\varrho)} \, n}{2 \pi} \sum_{i=1}^{n-1} \int_{\mathbb{T}^2} \mathrm{d} \ell \, \iota \, (w(\ell) + w(k_i - \ell)) \, \mathcal{F} f(\ell,k_i-\ell, k_{1:n-1 \setminus i}) \, , \\
\label{e:FcA0}
\mathcal{F} (\mathcal{A}_0 f) \, (k_{1:n}) &= (1 - 2 \varrho) \ \iota \, \Big(\sum_{i=1}^n w(k_i)\Big) \, \mathcal{F} f (k_{1:n}) \, ,
\end{equs}
where we have used the shorthand notation, for $k \in \mathbb{R}^2$,
\begin{equ} \label{e:defd0w}
d_0(k) \stackrel{\mbox{\tiny\rm def}}{=} 2 \sum_{z \in \mathbb{Z}^2} s(z) \, (1-\cos(z \cdot k)) \, , \quad w(k) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{z \in \mathbb{Z}^2} a(z) \, \sin(z \cdot k) \, ,
\end{equ}
and $d_0(k_{1:n}) \stackrel{\mbox{\tiny\rm def}}{=} d_0(k_1) + \dots + d_0(k_n)$ for $k_{1:n} \in \mathbb{R}^{2n}$.
Similarly to Lemma~\ref{lem:Gen}, on $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$ the operator $\mathcal{S}$ is essentially self-adjoint while $(\mathcal{A}_+)^* = - \mathcal{A}_-$ and $(\mathcal{A}_0)^* = - \mathcal{A}_0$; for any $n \geq 0$, the operators $\mathcal{S}$, $\mathcal{A}_+$, $\mathcal{A}_-$, $\mathcal{A}_0$ map $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
{}$ respectively to $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n+1}
    \else
        \Gamma h^{}_{n+1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n-1}
    \else
        \Gamma h^{}_{n-1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
{}$.

