    \fi
}$}
              {\mathcal{S}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
}}$ can be seen as the $s$-weighted discrete Laplacian on $\mathbb{Z}^{2n}$. It satisfies an integration by parts formula similar to that for $S$ (cf. Remark~\ref{rmk:IPPS}). Indeed, for $z \in \mathbb{Z}^2$, let us define the operator $\nabla_z$ acting from $
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
{}$ to $F \ell^2$ as
\begin{equ} \label{e:nablaz}
\nabla_z f(x_{1:n}) = f(x_1 + z, x_{2:n}) - f(x_{1:n}) \, .
\end{equ}
Then the soft-core counterpart of~\eqref{e:NeumannBC} is, for $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
{}$,
\begin{equ} \label{e:noBC}
\|(- \mathcal{S})^{1/2} f\|^2 = \frac{n}{2} \sum_{z \in \mathbb{Z}^2} s(z) \, \|\nabla_z f\|^2 \, .
\end{equ}

\label{rmk:NonSymmetricFock}
Because the operator $\nabla_z$ produces non-symmetric functions, we may need to work with the non-symmetric Fock space $F \ell^2$. To this end, we need to generalise a few definitions. First, we extend the counting operator $\mathcal{N}$ to $F \ell^2$ and define the space $F \ell^2_{{\mathrm{rap}}}$ in the obvious way (as in Definition~\ref{def:N}). Then, we extend the operator $\mathcal{S}$ to $F_* \ell^2 \subset F \ell^2$ as follows
\begin{equ} \label{e:NonSymmetricLapl}
\mathcal{S} f(x_{1:n}) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{i=1}^n \sum_{z \in \mathbb{Z}^2} s(z) \, \big(f(x_1, \dots, x_{i-1}, x_i + z, x_{i+1}, \dots, x_n) - f(x_{1:n})\big) \, , 
\end{equ}
which, in terms of the Fourier transform, corresponds to the same formula as~\eqref{e:FcS}. Of course, this extended operator $\mathcal{S}$ is still essentially self-adjoint. With this extension of $\mathcal{S}$ in mind, we can for instance state that, for any $\gamma \geq 0$ and $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
$, it holds
\begin{equ} \label{e:FracLaplNabla}
\|(- \mathcal{S})^{(1+\gamma)/2} f\|^2 = \frac{n}{2} \, \sum_{z \in \mathbb{Z}^2} \|(-\mathcal{S})^{\gamma/2} \, \nabla_z f\|^2 \, .
\end{equ}
Indeed, this follows from the integration by parts formula~\eqref{e:noBC} applied to $(- \mathcal{S})^{\gamma/2} f$, and the observation that $\nabla_z$ and $(- \mathcal{S})^{\gamma/2}$ commute.

\label{def:CoreFock}
Let $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ be the subspace consisting of $f = (f_n)_{n \geq 0}$ such that for every $a, b \geq 0$ it holds
\begin{equ} \label{e:defCoreFock}
\sup_{n \geq 0} n! \, (1 + n^a) \int_{\mathbb{R}^{2n}} (1+|k_{1:n}|^2)^{b} \, |{\mathfrak F} f_n(k_{1:n})|^2 \, \mathrm{d} k_{1:n} < \infty \, .
\end{equ}
We equip $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ with its natural Fréchet metric. For $n \geq 0$, we denote $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
 \stackrel{\mbox{\tiny\rm def}}{=} 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \cap 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$.

\label{def:GenSBE}
Let us define the operators ${\mathfrak L} \stackrel{\mbox{\tiny\rm def}}{=} {\mathfrak S} + {\mathfrak A} \stackrel{\mbox{\tiny\rm def}}{=} {\mathfrak S} + {\mathfrak A}_+ + {\mathfrak A}_- + {\mathfrak A}_0$ which act (continuously) from $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ to itself as follows, for $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$,
\begin{equs}
\label{e:fS}
{\mathfrak F} ({\mathfrak S} f) \, (k_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} - \frac{1}{2} D_0(k_{1:n}) \,{\mathfrak F} f(k_{1:n}) \, , \\
\label{e:fA+}
{\mathfrak F} ({\mathfrak A}_+ f) \, (k_{1:n+1}) &\stackrel{\mbox{\tiny\rm def}}{=} \frac{\sqrt{\varrho(1-\varrho)}}{\pi (n+1)} \sum_{1 \leq i < j \leq n+1} \iota \, \mathfrak{w} \cdot (k_i+k_j) \, \Pi_{k_i, k_j} \, {\mathfrak F} f (k_i + k_j, k_{1:n+1 \setminus i,j}) \, , \\
\label{e:fA-}
{\mathfrak F} ({\mathfrak A}_- f) \, (k_{1:n-1}) &\stackrel{\mbox{\tiny\rm def}}{=} \frac{\sqrt{\varrho(1-\varrho)} \, n}{2 \pi} \sum_{i=1}^{n-1} \iota \, \mathfrak{w} \cdot k_i \, \int_{\mathbb{R}^2} \mathrm{d} \ell \, \Pi_{\ell, k_i-\ell} \, {\mathfrak F} f (\ell, k_i-\ell, k_{1:n-1 \setminus i}) \, , \\
\label{e:fA0}
{\mathfrak F}({\mathfrak A}_0 f) \, (k_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} \iota \, \Big(v \cdot \sum_{i=1}^n k_i\Big) \, {\mathfrak F} f(k_{1:n}) \, ,
\end{equs}
where $\mathfrak{w}$ and $D_0$ were defined in~\eqref{e:D0&drift}, $v = (1 - 2 \varrho) \, \mathfrak{w}$, and where we have used the shorthand notation, for $k_{1:n} \in \mathbb{R}^{2n}$ and $p, q \in \mathbb{R}^2$,
\begin{equ} \label{e:CutOff}
D_0(k_{1:n}) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{i=1}^n k_i^T D_0 \,  k_i \, , \quad  \Pi_{p,q} \stackrel{\mbox{\tiny\rm def}}{=} \1_{|p|_\infty < \pi} \, \1_{|q|_\infty < \pi} \, \1_{|p+q|_\infty < \pi} \, .
\end{equ}
Similarly to Lemma~\ref{lem:Gen}, on $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
