        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$, $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n+1}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n+1}
