$, the generator ${\mathfrak L}^{\lim}$ is given by $d^{\lim} \, {\mathfrak L}_0^\mathfrak{e} +  D_0[\mathfrak{f}, \mathfrak{f}] \, {\mathfrak L}_0^{\mathfrak{f}}$.

\label{def:Utau}
For any $z \in \mathbb{R}^2$, $\tau \geq 1$, $t \geq 0$, we define the isometries ${\mathfrak T}_{z}, {\mathfrak U}_t^\tau \colon 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
 \to 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ that act on $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ as follows
\begin{equs}
{\mathfrak T}_z f (x_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} f(x_1 + z, \dots, x_n + z) \label{e:T} \\
{\mathfrak U}_0^\tau f (x_{1:n}) &\stackrel{\mbox{\tiny\rm def}}{=} \det(\Sigma^\tau)^{-n/2} \, f((\Sigma^\tau)^{-1} \, x_{1:n}) \, , \\
{\mathfrak U}^\tau_t f &\stackrel{\mbox{\tiny\rm def}}{=} {\mathfrak T}_{- \tau t v} \, {\mathfrak U}^\tau_0 \, f \, , \label{e:Utau}
\end{equs}
where the matrix $\Sigma^\tau$ is given by~\eqref{e:ScalingMatrix} and $v = (1 - 2 \varrho) \mathfrak{w}$. In Fourier space, the action of ${\mathfrak T}_{z}$ and ${\mathfrak U}_0^\tau$ can be written as
\begin{equ}
{\mathfrak F}({\mathfrak T}_z f) \, (k_{1:n}) = \exp\big(\iota \, z \cdot (k_1 + \dots + k_n)\big) \, {\mathfrak F} f(k_{1:n}) \, , \quad {\mathfrak F}({\mathfrak U}_0^\tau f) \, (k_{1:n}) = \det(\Sigma^\tau)^{n/2} \, {\mathfrak F} f(\Sigma^\tau k_{1:n}) \, . \label{e:UtauF}
\end{equ}

\label{rmk:Utau}
