              {({\mathfrak U}_t^\tau \varphi)\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\mathbb{Z}^2}}
              {\setbox1\hbox{${\scriptstyle ({\mathfrak U}_t^\tau \varphi)}_{\scriptscriptstyle \mathbb{Z}^2}$}
              {({\mathfrak U}_t^\tau \varphi)\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\mathbb{Z}^2}}
