              {({\mathfrak U}_t^\tau \varphi)\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\mathbb{Z}^2}})$.

\label{lem:BoundP}
For every $\kappa \in \mathbb{R}$, $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
$, and $\mu \geq 0$, we have
\begin{equ} \label{e:BoundP}
\|(\mu - \mathcal{S})^{\kappa} \, \mathsf{P} f\| \lesssim_\kappa \|(\mu - {\mathfrak L}_0)^{\kappa} f\| \, , \quad \|(\mu - {\mathfrak L}_0)^{\kappa} \, \mathsf{P}^* g\| \lesssim_\kappa \|(\mu - \mathcal{S})^{\kappa} \, g\| \, . 
\end{equ}

The second bound in~\eqref{e:BoundP} can be deduced from the first one (with $- \kappa$ instead of $\kappa$) by using a simple duality argument: thus we focus on the first bound. By using the elementary estimate~\eqref{e:d0D0equivalence} from Lemma~\ref{lem:SoftcoreRemoval} below, we deduce
\begin{equs}
\|(\mu - \mathcal{S})^\kappa \, \mathsf{P} f\|^2 &= \sum_{n \geq 0} n! \int_{[- \pi, \pi]^{2n}} (\mu + d_0(k_{1:n})/2)^{2 \kappa} \, |{\mathfrak F} f(k_{1:n})|^2 \, \mathrm{d} k_{1:n} \\
&\lesssim_\kappa \sum_{n \geq 0} n! \int_{[- \pi, \pi]^{2n}} (\mu + |k_{1:n}|^2/2)^{2 \kappa} \, |{\mathfrak F} f(k_{1:n})|^2 \, \mathrm{d} k_{1:n} \leq \|(\mu - {\mathfrak L}_0)^\kappa f\|^2 \, ,
\end{equs}
which shows the desired bound.

\label{lem:BoundR}
For every $\mu \geq 0$ and $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$, we have
\begin{equ} \label{e:BoundR}
\|\mathsf{R} f\| \leq \|f\| \, , \quad \|(\mu - S)^{1/2} \, \mathsf{R} f\| \leq\|(\mu - \mathcal{S})^{1/2} f\| \, .
\end{equ}

On the contrary, the corresponding bound on $\mathsf{R}$ for the $H^{-1}$ norm would be (ignoring possible extra polynomial cost in the number operator $\mathcal{N}$)
\begin{equ} \label{e:BoundRBad}
\|(\mu - S)^{-1/2} \, \mathsf{R} f\| \lesssim \log_{*}(1/\mu)^{1/2} \, \|(\mu - \mathcal{S})^{-1/2} f\| \, ,
\end{equ}
where the diverging logarithmic factor $\log_{*}(1/\mu)^{1/2}$ is optimal (in fact, it comes from the logarithmic divergence at the origin of the two-dimensional Green's function).

\label{def:B+}
We define the operator $B_+ \colon 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
 \to 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{2}
    \else
        \Gamma_0 h^{}_{2}
    \fi
$ that acts on $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
$ as follows
\begin{equ} \label{e:B+}
B_+ f \, (x,y) \stackrel{\mbox{\tiny\rm def}}{=} \sqrt{\varrho (1 - \varrho)} \, a(y-x) \, (\mathfrak{e} \cdot (y-x)) \, \frac{f(x) + f(y)}{2} \, .
\end{equ}
We also define the operator ${\mathfrak B}_+ \colon 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},1}
    \else
        \Gamma H^{}_{{\mathrm{rap}},1}
    \fi
 \to 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},2}
    \else
        \Gamma H^{}_{{\mathrm{rap}},2}
    \fi
$ that acts on $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},1}
    \else
        \Gamma H^{}_{{\mathrm{rap}},1}
    \fi
$ as follows
\begin{equ} \label{e:fB+}
{\mathfrak F}({\mathfrak B}_+ f) \, (p,q) \stackrel{\mbox{\tiny\rm def}}{=}  \frac{\lambda \, \sqrt{\varrho(1-\varrho)}}{2 \pi} \, \Pi_{p,q} \, {\mathfrak F} f(p+q) \, ,
\end{equ}
where $\Pi_{p,q}$ is the cut-off function given by~\eqref{e:CutOff}.

Compare the formula~\eqref{e:B+} of $B_+$ with the action of $A_+$ on the first chaos
\begin{equ}
A_+ f(x,y) = \sqrt{\varrho (1-\varrho)} \, a(y-x) \, (f(y) - f(x)) \, .
\end{equ}
Hence, we morally have $A_+ f \approx B_+ \, \partial_\mathfrak{e} f$. In fact, this is an exact identity at the level of the continuum operators: ${\mathfrak A}_+ f = {\mathfrak B}_+ \, \partial_\mathfrak{e} f$.

\label{def:V}
Let $\mathcal{V} \in \mathcal{S}(\mathbb{R}^2)$ be a Schwartz function that is even-symmetric, with $L^2(\mathbb{R}^2)$-norm equal to $1$, and with Fourier transform supported on $(- \pi, \pi)^2$; we fix such $\mathcal{V}$ for the rest of the paper. Then, for any $\delta \in (0,1]$, we define $\mathcal{V}^\delta \in \mathcal{S}(\mathbb{R}^2)$ as
\begin{equ} \label{e:SqrtDirac}
\mathcal{V}^\delta(x) = \delta \, \mathcal{V}(\delta x) \ \mbox{, or equivalently, } \ {\mathfrak F}(\mathcal{V}^\delta) \, (p) = \delta^{-1} \, {\mathfrak F} \mathcal{V}(\delta^{-1} p) \, .
\end{equ}
We also denote by $\mathcal{V}^\delta_{|\mathbb{Z}^2}$ the restriction of $\mathcal{V}^\delta$ to $\mathbb{Z}^2$. Note that $\mathcal{V}^\delta$ and $\mathcal{V}^\delta_{|\mathbb{Z}^2}$ can be seen as elements of, respectively, $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{1}
    \else
        \Gamma H^{}_{1}
    \fi
$ and $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
$.

\label{lem:GKneat}
For every $t > 0$, we have
\begin{equ}
d(t) = \lim_{\delta \to 0} \frac{1}{t} \, \mathbf E_{\nu_\varrho}\Big[\Big(\int_0^t B_+ \mathcal{V}^\delta_{|\mathbb{Z}^2} (\eta_s) \, \mathrm{d} s\Big)^2\Big] \, . \label{e:GKneat}
\end{equ}

By writing $B_+ \mathcal{V}^\delta = \sum_{x \in \mathbb{Z}^2} \mathcal{V}^\delta(x) \, B_+(\1_{x})$, expanding the square, using the translation invariance of the ASEP, and recalling the even-symmetry of $\mathcal{V}^\delta$, we obtain
\begin{equs}
d&(t) - \frac{1}{t} \, \mathbf E_{\nu_\varrho}\Big[\Big(\int_0^t B_+ \mathcal{V}^\delta_{|\mathbb{Z}^2} (\eta_s) \, \mathrm{d} s\Big)^2\Big] \\
&= \frac{1}{t} \, \sum_{x \in \mathbb{Z}^2} \big(1 - \mathcal{V}^\delta *_{\mathbb{Z}^2} \mathcal{V}^\delta(x)\big) \, \mathbf E_{\nu_\varrho}\Big[\Big(\int_0^t B_+(\1_{\{0\}})[\eta_s] \, \mathrm{d} s\Big) \Big(\int_0^t B_+(\1_{\{x\}})[\eta_s] \, \mathrm{d} s\Big)\Big] \, , \label{e:GKneatProof}
\end{equs}
where $*_{\mathbb{Z}^2}$ stands for the $\mathbb{Z}^2$-convolution, defined as: $f *_{\mathbb{Z}^2} g := \sum_{y \in \mathbb{Z}^2} f(\cdot-y) \, g(y)$. Now, we claim that, for every $\delta \in (0,1]$ and $x \in \mathbb{Z}^2$, we have
\begin{equ} \label{e:SquareRootUnity}
|(\mathcal{V}^\delta *_{\mathbb{Z}^2} \mathcal{V}^\delta)(x) - 1| \lesssim \delta \, (1 + |x|) \, .
\end{equ}
Then, we deduce the desired convergence~\eqref{e:GKneat} because the space-time correlations of the ASEP decay exponentially fast in space on any finite time window. As for the claim~\eqref{e:SquareRootUnity}, it easily follows by first writing
\begin{equs}
\Big|(\mathcal{V}^\delta *_{\mathbb{Z}^2} \mathcal{V}^\delta)(x) - \delta^2 \sum_{y \in \mathbb{Z}^2} \mathcal{V}(\delta y)^2\Big| &= \Big|\delta^2 \sum_{y \in \mathbb{Z}^2} \mathcal{V}(\delta y - \delta x) \mathcal{V}(\delta y) - \delta^2 \sum_{y \in \mathbb{Z}^2} \mathcal{V}(\delta y)^2\Big| \\
&\leq \|\mathcal{V}\|_{\mathrm{Lip}} \ \delta |x| \ \delta^2 \sum_{y \in \mathbb{Z}^2} |\mathcal{V}(\delta y)| \, ,
\end{equs}
and then estimating the appearing Riemann sums, as follows,
\begin{equ}
\delta^2 \sum_{y \in \mathbb{Z}^2} \mathcal{V}(\delta y)^2 = \|\mathcal{V}\|_{L^2(\mathbb{R}^2)}^2 + O(\delta) = 1 + O(\delta) \, , \quad \delta^2 \sum_{y \in \mathbb{Z}^2} |\mathcal{V}(\delta y)| = O(1) \, .
\end{equ}

\label{th:ComparisonGen}
Let $\gamma \in [0,1)$. Then, for every $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ}
\|(- S)^{-1/2} \, (L \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} {\mathfrak L}) \, \phi\| \lesssim_\gamma \|{\mathfrak N}^{6} (- {\mathfrak L}_0)^{(1+\gamma)/2} \phi\| + \|{\mathfrak N}^{6} (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, . \label{e:ComparisonGen}
\end{equ}
Further, the bound remains valid if $(L, {\mathfrak L})$ is replaced by any of $(S, {\mathfrak S})$, $(A_+, {\mathfrak A}_+)$, $(A_-, {\mathfrak A}_-)$, or $(A_0, {\mathfrak A}_0)$; and the second summand on the right hand side is only needed for $(A_+, {\mathfrak A}_+)$.

\label{p:HardcoreRemoval}
Let $\gamma \in [0, 1)$. Then, for every $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
{}$, we have
\begin{equ}
\|(- S)^{-1/2} \, (L \mathsf{R} - \mathsf{Q}^* \mathcal{L}) f\| \lesssim_\gamma \, \|\mathcal{N}^{6} \, (- \mathcal{S})^{(1 + \gamma)/2} f\| \, . \label{e:HardcoreRemoval}
\end{equ}
Further, the bound remains valid if $(L, \mathcal{L})$ is replaced by any of $(S, \mathcal{S})$, $(A_+, \mathcal{A}_+)$, $(A_-, \mathcal{A}_-)$, or $(A_0, \mathcal{A}_0)$.

\label{lem:BoundQ}
For every $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
{}$, $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma h^{}_{{\mathrm{rap}}}
    \fi
{}$, and $\mu \geq 0$, we have
\begin{equs}
\|\mathsf{Q} g\| \lesssim \|g\| \, , \quad \|(\mu - &\mathcal{S})^{1/2} \, \mathsf{Q} g\| \lesssim \|N^3 \, (\mu - S)^{1/2} g\| \, , \label{e:BoundQ} \\
\|\mathsf{Q}^* f\| \lesssim \|f\| \, , \quad \|(\mu - &S)^{-1/2} \, \mathsf{Q}^* f\| \lesssim \|\mathcal{N}^3 \, (\mu - \mathcal{S})^{-1/2} f\| \, , \label{e:BoundQ*} \,
\end{equs}
and, provided that $\mu > 0$,
\begin{equ}
\|(\mu - S)^{-1/2} \, (\mathsf{Q}^* - \mathsf{R}) f\| \lesssim \log_{*}(1/\mu) \, \|\mathcal{N}^2 \, (\mu - \mathcal{S})^{1/2} f\| \, . \label{e:RemovalQ*R}
\end{equ}

\label{lem:ZiBound}
Let $\gamma \in [0,1)$. Then, for every $f \in F \ell_*^2$, $l \geq 1$, and $\mu > 0$, we have
\begin{equs}
\|\1_{\mathcal{Z}_{\geq 1}(l)} \, f\| &\lesssim_\gamma \min\big\{l \, \|\mathcal{N} \, (-\mathcal{S})^{\gamma/2} f\| \, , \ l \, \sqrt{\log_{*}(1/\mu)} \, \|\mathcal{N} \, (\mu-\mathcal{S})^{1/2} f\|\big\} \, , \label{e:Z1Bound} \\
\|\1_{\mathcal{Z}_{\geq 2}(l)} \, f\| &\lesssim_\gamma l^2 \, \|\mathcal{N}^2 \, (-\mathcal{S})^{(1+\gamma)/2} f\| \, , \label{e:Z2Bound}
\end{equs}

\label{lem:ZiBoundHC}
For every $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
$, $\ell \geq 1$, and $\mu > 0$, we have
\begin{equs}
\|\1_{\mathcal{Z}_{\geq 1}(l)} \, g\| &\lesssim l \, \sqrt{\log_{*}(1/\mu)} \, \|\mathcal{N} \, (\mu-S)^{1/2} g\| \, , \label{e:Z1BoundHC} \\
\|\1_{\mathcal{Z}_{\geq 2}(l)} \, g\| &\lesssim l^2 \, \|\mathcal{N}^2 \, (-S)^{1/2} g\| \, . \label{e:Z2BoundHC}
\end{equs}

First, we claim that for any $d \geq 1$, $\nu \in [0,d/2]$, $\mu > 0$, $F \in \ell^2(\mathbb{Z}^{2d})$, and $y_{1:d} \in \mathbb{Z}^{2d}$, we have
\begin{equ} \label{e:ZiBoundClaim}
|F(y_{1:d})|^2 \lesssim_{d, \nu} \log_{*}(1/\mu)^{\1_{\nu = d/2}} \, \|(\mu - \mathcal{S})^\nu F\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, .
\end{equ}
In particular, for any $l \geq 1$, we deduce
\begin{equ} \label{e:ZiBoundClaimCorollary}
\|1_{|x_{1:d}|_\infty \leq l} \, F\|^2 \lesssim_{d, \nu} l^{2d} \, \log_{*}(1/\mu)^{\1_{\nu = d/2}} \, \|(\mu - \mathcal{S})^\nu F\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, .
\end{equ}
To prove the claim~\eqref{e:ZiBoundClaim}, we write the Fourier inversion formula 
\begin{equ}
F(y_{1:d}) = (2 \pi)^{-d} \int_{[- \pi, \pi]^{2d}} \mathcal{F} F (k_{1:d}) \, \exp(\iota \, y_{1:d} \cdot k_{1:d}) \, \mathrm{d} k_{1:d} \, ,
\end{equ}
and we apply the Cauchy-Schwarz inequality to deduce that $|F(y_{1:d})|^2$ is bounded by 
\begin{equs}
(2 &\pi)^{-2d} \, \Big(\int_{[- \pi, \pi]^{2d}} (\mu + d_0(k_{1:d})/2)^{- 2 \nu} \, \mathrm{d} k_{1:d}\Big) \Big(\int_{[- \pi, \pi]^{2d}} (\mu + d_0(k_{1:d})/2)^{2 \nu} \, |\mathcal{F} F(k_{1:d})|^2 \, \mathrm{d} k_{1:d}\Big) \\
&\lesssim_{d, \nu} \log_{*}(1/\mu)^{\1_{\nu = d/2}} \, \|(\mu - \mathcal{S})^\nu F\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, ,
\end{equs}
where, in order to bound the first integral by $C(d, \nu) \log_{*}(1/\mu)^{\1_{\nu = d/2}}$, we used the estimate $d_0(k_{1:d}) \asymp |k_{1:d}|^2$ for $k_{1:d} \in [- \pi, \pi]^{2d}$ (see~\eqref{e:d0D0equivalence} from Lemma~\ref{lem:SoftcoreRemoval} below).
\smallskip

Now, we turn to the proof of~\eqref{e:Z1Bound} and~\eqref{e:Z2Bound}. By orthogonality of chaoses, it is sufficient to prove these bounds for any $f \in F \ell^2_n$ and $n \geq 1$. Then notice that
\begin{equs}
\|\1_{\mathcal{Z}_{\geq 1}(l)} f\|_{\ell^2(\mathbb{Z}^{2n})}^2 &\leq \sum_{x_{1:n} \in \mathbb{Z}^{2n}} \sum_{i \in \{1, \dots, n\} \, ; \, j \in \{1, \dots, n\} \setminus \{i\}} \1_{|x_i - x_j|_\infty \leq l} \, f(x_{1:n})^2 \, , \\
\|\1_{\mathcal{Z}_{\geq 2}(l)} f\|_{\ell^2(\mathbb{Z}^{2n})}^2 &\leq \sum_{x_{1:n} \in \mathbb{Z}^{2n}} \sum_{i_1 \ne i_2 \in \{1, \dots, n\} \, ; \, j_1, j_2 \in \{1, \dots, n\} \setminus \{i_1, i_2\}} \1_{|x_{i_1} - x_{j_1}|_\infty \vee |x_{i_2} - x_{j_2}|_\infty \leq l} \, f(x_{1:n})^2 \, .
\end{equs}
Hence, to obtain~\eqref{e:Z1Bound} and~\eqref{e:Z2Bound}, it is sufficient to show that for any $d \in \{1,2\}$, $\nu \in [0,d/2]$, $\mu > 0$, $j_1, \dots, j_d \in \{d+1, \dots, n\}$ and $f \in F \ell^2_n$ we have
\begin{equ} \label{e:ZiBoundReductionBis}
\|\1_{|x_1 - x_{j_1}|_\infty \vee \dots \vee |x_d - x_{j_d}|_\infty \leq l} \, f\|_{\ell^2(\mathbb{Z}^{2n})}^2 \lesssim_\nu l^{2d} \, \log_{*}(1/\mu)^{\1_{\nu = d/2}} \, \|(\mu - \mathcal{S})^{\nu} f\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, .
\end{equ}
(In particular, if $\nu < d/2$, then we can let $\mu \to 0$ and extend the statement to $\mu = 0$.)
To show~\eqref{e:ZiBoundReductionBis}, we first write
\begin{equ}
\|\1_{|x_1 - x_{j_d}|_\infty \vee \dots \vee |x_d - x_{j_d}|_\infty \leq l} \, f\|_{\ell^2(\mathbb{Z}^{2n})}^2 = \sum_{x_{d+1:n} \in \mathbb{Z}^{2(n-d)}} \sum_{z_{1:d}\in \mathbb{Z}^{2d}} \1_{|z_{1:d}|_\infty \leq l} \, f(z_1 + x_{j_1}, \dots, z_d + x_{j_d}, x_{d+1:n})^2 \, ,
\end{equ}
and then notice that the second sum corresponds to the left hand side of~\eqref{e:ZiBoundClaimCorollary} with the function $F$ that maps $z_{1:d} \in \mathbb{Z}^{2d}$ to $f(z_1 + x_{j_1}, \dots, z_d + x_{j_d}, x_{d+1:n})$. As a consequence, this second sum is bounded, up to a multiplicative constant $C(d, \nu) \, l^{2 d} \, \log_{*}(1/\mu)^{\1_{\nu = d / 2}}$, by
\begin{equs}
\int_{[-\pi, \pi]^{2 d}} &\mathrm{d} k_{1:d} \, (\mu + d_0(k_{1:d})/2)^{2 \nu} \, |e^{\iota (k_1 \cdot x_{j_1} + \dots + k_d \cdot x_{j_d})} \, \mathcal{F}_{1 : d} f(k_{1:d}, x_{d+1 : n})|^2 \\
&= \int_{[-\pi, \pi]^{2d}} \mathrm{d} k_{1:d} \, (\mu + d_0(k_{1:d})/2)^{2 \nu} \, |\mathcal{F}_{1 : d} f(k_{1:d}, x_{d+1 : n})|^2 \, ,
\end{equs}
where $\mathcal{F}_{1 : d}$ stands for the Fourier transform applied to the first $d$ coordinates. Then we take the sum over $x_{d+1:n} \in \mathbb{Z}^{2(n-d)}$ and deduce that $\|\1_{|x_1 - x_{j_d}|_\infty \vee \dots \vee |x_d - x_{j_d}|_\infty \leq l} \, f\|_{\ell^2(\mathbb{Z}^{2n})}^2$ is bounded, up to a multiplicative constant $C(d,\nu) \, l^{2d} \, \log_{*}(1/\mu)^{\1_{\nu = d / 2}}$, by
\begin{equs}
\int_{[-\pi, \pi]^{2 n}} &\mathrm{d} k_{1:n} \, (\mu + d_0(k_{1:d})/2)^{2 \nu} \, |\mathcal{F} f(k_{1:n})|^2 \leq \|(\mu - \mathcal{S})^{\nu} f\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, ,
\end{equs}
which shows~\eqref{e:ZiBoundReductionBis} and concludes the proof.

First, note that it is sufficient to show each bound for every $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{n}
    \else
        \Gamma h^{}_{n}
    \fi
{}$ and $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$, for any $n \geq 1$. We start with the first bound of~\eqref{e:BoundQ}. From the definition~\eqref{e:defQ} of $\mathsf{Q}$, we immediately deduce
\begin{equs}
\|\mathsf{Q} g\|_{\ell^2(\mathbb{Z}^{2n})}^2 &= \|g\|_{\ell^2(\mathbb{Z}^{2n})}^2 + \sum_{y_{1:n} \in \mathbb{Z}^{2n}} g(y_{1:n})^2 \, \#\{1 \leq i \ne j \leq n \, : \, y_j - y_i = z_0 \, \mbox{ and } y_{1:n \setminus j} \in \mathcal{Z}_0\} \\
&\leq 2 \, \|g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, , \label{e:BoundL2QProof}
\end{equs}
where in the last bound we noticed that, for any $y_{1:n} \in \mathbb{Z}^{2n}$, there can exist at most one pair $(i,j)$ satisfying the desired condition: indeed, such a pair must satisfy $|y_i - y_j|_\infty < l_0$ while $|y_k - y_\ell|_\infty \geq (2 l_0 + 1) - l_0 > l_0$ for every $\{k, \ell\} \ne \{i,j\}$, which determines $\{i,j\}$ (and then $(i,j)$ is determined by the relation $y_j = y_i + z_0$).

Now we turn to the second bound of~\eqref{e:BoundQ}. Since $\|(\mu - \mathcal{S})^{1/2} \cdot\|^2 = \mu \, \|\cdot\|^2 + \|(-\mathcal{S})^{1/2} \cdot\|^2$ (and similarly for $S$), it only remains to show
\begin{equ} \label{e:BoundQH1dot}
\|(- \mathcal{S})^{1/2} \, \mathsf{Q} g\|^2_{\ell^2(\mathbb{Z}^{2n})} \lesssim n^6 \, \|(- S)^{1/2} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, .
\end{equ}
The latter can be proved by adapting, mutatis mutandis, the proof of~\cite[Lemma 4.3]{LQSY04} (and using, in particular,~\eqref{e:Z2BoundHC}). For the reader's convenience, and because our operator $\mathsf{Q}$ differs slightly from its counterpart therein (in particular, here $\mathsf{Q} g(x_{1:n})$ vanishes as soon as $x_{1:n}$ contains multiple isolated double sites), we give a sketch of the proof in Appendix~\ref{app:HCSC}.
\smallskip

As for the bounds in~\eqref{e:BoundQ*}, observe that they readily follow from those in~\eqref{e:BoundQ} by using a simple duality argument.
\smallskip

Finally, we tackle~\eqref{e:RemovalQ*R}. Let $h \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$. By the definition~\eqref{e:defQ} of $\mathsf{Q}$, we have
\begin{equ}
\langle (\mathsf{Q}^* - \mathsf{R}) f, h \rangle = \langle f, (\mathsf{Q} - \mathsf{R}^*) h \rangle = \langle f, \1_{DI \cap \mathcal{Z}_1} \mathsf{Q} h \rangle = \langle \1_{DI \cap \mathcal{Z}_1} f, \mathsf{Q} \, \1_{\mathcal{Z}_1(3 l_0 + 1)} \, h \rangle \, ,
\end{equ}
where in the last equality we were able to add the indicator $\1_{\mathcal{Z}_1(3 l_0 + 1)}$ in front of $h$ by using~\eqref{e:defQ} and observing that, if $x_{1:n} \in DI \cap \mathcal{Z}_1 = DI \cap \mathcal{Z}_1(2 l_0 + 1)$, then $(x_i, x_j + z_0, x_{1:n \setminus i,j}) \in \mathcal{Z}_1(3 l_0 + 1)$.
Now, by first using the Cauchy Schwarz inequality and~\eqref{e:BoundQ}, and then~\eqref{e:Z1Bound} applied with $f$ and~\eqref{e:Z1BoundHC} applied with $h$, we deduce
\begin{equ}
|\langle \mathsf{Q}^* f - \mathsf{R} f, h \rangle| \lesssim \|\1_{\mathcal{Z}_1} f\| \, \|\1_{\mathcal{Z}_1(3 l_0 + 1)} h\| \lesssim \log_{*}(1/\mu) \, n^2 \, \|(\mu - \mathcal{S})^{1/2} f\| \, \|(\mu - S)^{1/2} h\| \, .
\end{equ}
By taking the supremum over $h$ such that $\|(\mu - S)^{1/2} h\| = 1$, we deduce the desired estimate~\eqref{e:RemovalQ*R} and conclude the proof.

We show that, for any $(O, \mathcal{O}) \in \{(S, \mathcal{S}), (A_+, \mathcal{A}_+), (A_-, \mathcal{A}_-), (A_0, \mathcal{A}_0)\}$ and for every $f \in 
