$, it holds
\begin{equ} \label{e:HCremovalOclaim}
\big|\langle O \, \mathsf{R} f, \mathsf{R} g \rangle - \langle \mathcal{O} f, g\rangle\big| \lesssim_{\gamma} n^3 \, \|(- \mathcal{S})^{(1+\gamma)/2} f\| \, \|(- \mathcal{S})^{1/2} g\| \, , 
\end{equ}
Then, by noticing that $\mathsf{Q}^* \mathsf{R}^* = \mathrm{Id}$ and using~\eqref{e:BoundQ*}, we deduce
\begin{equs}
\|(- S)^{-1/2} \, (O \mathsf{R} - \mathsf{Q}^* \mathcal{O}) f\| &= \|(- S)^{-1/2} \, \mathsf{Q}^* (\mathsf{R}^* O \mathsf{R} - \mathcal{O}) f\| \\
&\lesssim n^3 \, \|(- \mathcal{S})^{-1/2} \, (\mathsf{R}^* O \mathsf{R} - \mathcal{O}) f\| \\
&\lesssim_\gamma n^6 \, \|(- \mathcal{S})^{(1+\gamma)/2} f\| \, ,
\end{equs}
where in the last bound we used~\eqref{e:HCremovalOclaim}. Finally, by using orthogonality of chaoses, we can extend this bound to any $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$ up to replacing the factor $n^6$ by $\mathcal{N}^6$, which results in the desired estimate~\eqref{e:HardcoreRemoval} and would conclude the proof.
\smallskip

Now, we prove~\eqref{e:HCremovalOclaim}. Obviously, we can assume that $g$ belongs respectively to $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n+1}
    \else
        \Gamma_0 h^{}_{n+1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n-1}
    \else
        \Gamma_0 h^{}_{n-1}
    \fi
{}$, $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
{}$ when we prove the statement for $O = S, A_+, A_-, A_0$.
\smallskip

We tackle the case $(O, \mathcal{O}) = (S, \mathcal{S})$. We write
\begin{equs}
\langle (-\mathcal{S}) f, g\rangle - \langle (- S) \mathsf{R} f, \mathsf{R} g\rangle = n! \times n \sum_{z \in \mathbb{Z}^2} &s(z) \sum_{x_{1:n} \in \mathbb{Z}^{2n}} \big(1 -  \1_{HC}(x_{1:n}) \1_{HC}(x_1 + z, x_{2:n})\big) \\
&\times (f(x_1 + z, x_{2:n}) - f(x_{1:n})) \, (g(x_1 + z, x_{2:n}) - g(x_{1:n})) \, .
\end{equs}
Now, observe that if either $x_{1:n}$ or $(x_1 + z, x_{2:n})$ belongs to the diagonal $DI$ (with $z \in \mathrm{Supp}(s)$ so that $|z|_\infty \leq l_0$), then they both belong to $\mathcal{Z}_{\geq 1}$. Thus we deduce, by the Cauchy-Schwarz inequality,
\begin{equs}
|\langle (-\mathcal{S}) f, g\rangle - \langle (- S) \mathsf{R} f, \mathsf{R} g\rangle| &\lesssim n \sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\| \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z g\|\ \\
&\lesssim n \, \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\|^2\Big)^{1/2} \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z g\|^2\Big)^{1/2} \, .
\end{equs}
By using~\eqref{e:Z1Bound} and~\eqref{e:FracLaplNabla}, we deduce
\begin{equ} \label{e:HCremovalS}
|\langle (-\mathcal{S}) f, g\rangle - \langle (- S) \mathsf{R} f, \mathsf{R} g\rangle|
\lesssim_{\gamma} n \, \|(- \mathcal{S})^{(1+\gamma)/2} f\| \|(- \mathcal{S})^{(1+\gamma)/2} g\| \, ,
\end{equ}
which proves~\eqref{e:HCremovalOclaim} for $(O, \mathcal{O}) = (S, \mathcal{S})$ (note that we can use the crude bound $-\mathcal{S} \lesssim \mathcal{N}$ to drop a factor $(-\mathcal{S})^\gamma$ in the second norm).
\smallskip

We tackle the case $(O, \mathcal{O}) = (A_+, \mathcal{A}_+)$. We write
\begin{equs}
\langle &\mathcal{A}_+ f, g\rangle - \langle A_+ \mathsf{R} f, \mathsf{R} g\rangle \\
&= (n+1)! \times (-1) \, \sqrt{\varrho(1-\varrho)} \, n \sum_{z \in \mathbb{Z}^2} a(z) \sum_{x_{1:n} \in \mathbb{Z}^{2n}} \big(1 - \1_{HC}(x_{1:n}) \1_{HC}(x_1 + z, x_{2:n})\big) \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times (f(x_1 + z, x_{2:n}) - f(x_{1:n})) \, g(x_1 + z, x_{1:n}) \, .
\end{equs}
Now, observe that if either $x_{1:n}$ or $(x_1 + z, x_{2:n})$ belongs to the diagonal $DI$ (with $z \in \mathrm{Supp}(a)$), then not only do they belong to $\mathcal{Z}_{\geq 1}$ (as noticed previously), but also $(x_1+z, x_{1:n})$ belongs to $\mathcal{Z}_{\geq 2}$. Thus we deduce, by the Cauchy-Schwarz inequality and the bound $|a(z)| \leq s(z)$,
\begin{equs}
|\langle \mathcal{A}_+ f, g\rangle - \langle A_+ \mathsf{R} f, \mathsf{R} g\rangle| &\lesssim n^{1/2} \times n \sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\| \|\1_{\mathcal{Z}_{\geq 2}} g\| \\
&\lesssim n^{3/2} \, \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\|^2\Big)^{1/2} \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 2}} g\|^2\Big)^{1/2} \, .
\end{equs}
By using~\eqref{e:Z1Bound},~\eqref{e:FracLaplNabla}, and~\eqref{e:Z2Bound}, we deduce 
\begin{equ} \label{e:HCremovalA+}
|\langle \mathcal{A}_+ f, g\rangle - \langle A_+ \mathsf{R} f, \mathsf{R} g\rangle|
\lesssim_{\gamma} n^{5/2} \, \|(- \mathcal{S})^{(1+\gamma)/2} f\| \|(-\mathcal{S})^{(1+\gamma)/2} g\| \, ,
\end{equ}
which proves~\eqref{e:HCremovalOclaim} for $(O, \mathcal{O}) = (A_+, \mathcal{A}_+)$ (once again, we can use the crude bound $-\mathcal{S} \lesssim \mathcal{N}$ to drop a factor $(-\mathcal{S})^\gamma$ in the second norm).
\smallskip

We tackle the case $(O, \mathcal{O}) = (A_-, \mathcal{A}_-)$. By starting from~\eqref{e:HCremovalA+} applied with $(g, f)$ instead of $(f,g)$ (hence, applied with $n-1$ instead of $n$) and using that $(A_+)^* = - A_-$ and $(\mathcal{A}_+)^* = - \mathcal{A}_-$, we obtain
\begin{equ}
|\langle \mathcal{A}_- f, g\rangle - \langle A_- \mathsf{R} f, \mathsf{R} g\rangle|
\lesssim_{\gamma} n^{5/2} \, \|(- \mathcal{S})^{(1+\gamma)/2} f\| \|(-\mathcal{S})^{(1+\gamma)/2} g\| \, ,
\end{equ}
which proves~\eqref{e:HCremovalOclaim} for $(O, \mathcal{O}) = (A_-, \mathcal{A}_-)$ (once again, we can use the crude bound $-\mathcal{S} \lesssim \mathcal{N}$ to drop a factor $(-\mathcal{S})^\gamma$ in the second norm).
\smallskip

Finally, we tackle the case $(O, \mathcal{O}) = (A_0, \mathcal{A}_0)$. We write
\begin{equs}
\langle \mathcal{A}_0 f, g\rangle - \langle A_0 \mathsf{R} f, \mathsf{R} g \rangle = n! \times (1 - 2 \varrho) \, n \sum_{z \in \mathbb{Z}^2} a(z) &\sum_{x_{1:n} \in \mathbb{Z}^{2n}} \big(1 - \1_{HC}(x_{1:n}) \1_{HC}(x_1 + z, x_{2:n})\big) \\
&\quad \times \big(f(x_1 + z, x_{2:n}) - f(x_{1:n})\big) \, g(x_{1:n}) \, .
\end{equs}
Observe that, as previously noticed, if either $x_{1:n}$ or $(x_1+z,x_{2:n})$ belongs to the diagonal $DI$ (with $z \in \mathrm{Supp}(a)$), then they both belong to $\mathcal{Z}_{\geq 1}$. Thus we deduce, by the Cauchy-Schwarz inequality and the bound $|a(z)| \leq s(z)$,
\begin{equs}
|\langle \mathcal{A}_0 f, g\rangle - \langle A_0 \mathsf{R} f, \mathsf{R} g \rangle| &\lesssim n \sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\| \, \|\1_{\mathcal{Z}_{\geq 1}} g\| \, \\
&\lesssim n \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} \nabla_z f\|^2\Big)^{1/2} \Big(\sum_{z \in \mathbb{Z}^2} s(z) \, \|\1_{\mathcal{Z}_{\geq 1}} g\|^2\Big)^{1/2} \, .
\end{equs}
By using~\eqref{e:Z1Bound} and~\eqref{e:FracLaplNabla}, we deduce
\begin{equ}
|\langle \mathcal{A}_0 f, g\rangle - \langle A_0 \mathsf{R} f, \mathsf{R} g \rangle| \lesssim_{\gamma} n \, \|(-\mathcal{S})^{(1+\gamma)/2} f\| \,  \|(- \mathcal{S})^{\gamma/2} g\|\, .
\end{equ}
Now, by exchanging $f$ and $g$ and using that $(A_0)^* = - A_0$ and $(\mathcal{A}_0)^* = - \mathcal{A}_0$, we also obtain
\begin{equ}
|\langle \mathcal{A}_0 f, g\rangle - \langle A_0 \mathsf{R} f, \mathsf{R} g \rangle| \lesssim_{\gamma} n \, \|(-\mathcal{S})^{\gamma/2} f\| \,  \|(- \mathcal{S})^{(1+\gamma)/2} g\|\, .
\end{equ}
Hence, we can apply Lemma~\ref{lem:Interpolation} (by taking $\mathscr S$ therein as $\mathchoice
