\label{p:SoftcoreRemoval}
Let $\gamma \in [0,1]$. For every $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:SoftcoreRemoval}
\|(- \mathcal{S})^{-1/2} \, (\mathcal{L} \mathsf{P} - \mathsf{P} {\mathfrak L}) f\| \lesssim \|{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} f\| + \|{\mathfrak N} \, (-{\mathfrak L}_0^\mathfrak{e})^{1/2} f\| \, .
\end{equ}
Further, the bound remains valid if $(\mathcal{L}, {\mathfrak L})$ is replaced by any of $(\mathcal{S}, {\mathfrak S})$, $(\mathcal{A}_+, {\mathfrak A}_+)$, $(\mathcal{A}_-, {\mathfrak A}_-)$, or $(\mathcal{A}_0, {\mathfrak A}_0)$; the second summand on the right hand side is only needed for $(\mathcal{A}_+, {\mathfrak A}_+)$.

\label{lem:SoftcoreRemoval}
For every $k_{1:n} \in [- \pi, \pi]^{2n}$, $n \geq 0$, we have
\begin{equ} \label{e:d0D0equivalence}
d_0(k_{1:n}) \asymp |k_{1:n}|^2 \, .
\end{equ}
For every $k_{1:n} \in \mathbb{R}^{2n}$, $n \geq 0$, and $p, q \in \mathbb{R}^2$ we have
\begin{equs}
|d_0(k_{1:n}) - D_0(k_{1:n})| &\lesssim |k_{1:n}|^4 \, , \label{e:d0Removal}  \\
\Big|\sum_{i=1}^n w(k_i) - \mathfrak{w} \cdot \sum_{i=1}^n k_i\Big| &\lesssim |k_{1:n}|^3 \, , \label{e:wRemoval} \\ 
|w(p) + w(q) - \mathfrak{w} \cdot (p+q)| &\lesssim |\mathfrak{e} \cdot (p+q)| \, (|p|^2 + |q|^2) \, . \label{e:wpqRemoval}
\end{equs}

\label{rmk:wRemoval}
The bound~\eqref{e:wpqRemoval} is the only place in the paper where we directly use Assumption~\ref{ass:Unidirectional}. Without this assumption, we could not say much more than
\begin{equ} \label{e:wRemovalWeak}
|w(p) + w(q) - \mathfrak{w} \cdot (p+q)| \lesssim |p+q| \, (|p|^2 + |q|^2) \, .
\end{equ}
It is easily checked from the proof of Proposition~\ref{p:SoftcoreRemoval} below that, if we use~\eqref{e:wRemovalWeak} instead of~\eqref{e:wpqRemoval}, then the error term $\|{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} f\|$ appearing in~\eqref{e:SoftcoreRemoval} when comparing $\mathcal{A}_+$ and ${\mathfrak A}_+$ would now become $\|{\mathfrak N} \, (- {\mathfrak L}_0)^{1/2} f\|$ (in particular, it would make the choice $\gamma > 0$ useless). Consequently, we would eventually end up with the weaker estimate~\eqref{e:ComparisonGenEasy} instead of~\eqref{e:ComparisonGen} in Theorem~\ref{th:ComparisonGen}.

First,~\eqref{e:d0D0equivalence} is a consequence of the irreducibility assumption on the jump rates. Indeed, on the one hand $d_0(k) \sim D_0(k) \asymp |k|^2$ as $k \to 0$ by the Taylor expansion of $\cos$ at $0$, and on the other hand the function $d_0$ on $\mathbb{R}^2$ is continuous, non-negative and only vanishes on $2 \pi \mathbb{Z}^2$ by the irreducibility assumption. Thus $d_0(k) \asymp |k|^2$ on $[- \pi, \pi]^2$, which gives~\eqref{e:d0D0equivalence}.
\smallskip

Now we prove~\eqref{e:d0Removal} and~\eqref{e:wRemoval}. We use the Taylor estimates $|\cos(\theta) - (1 - \theta^2/2)| \lesssim |\theta|^4$ and $|\sin(\theta) - \theta| \lesssim |\theta|^3$, and deduce for every $k \in \mathbb{R}^2$
\begin{equs}
|d_0(k) - D_0(k)| &\leq 2 \sum_{z \in \mathbb{Z}^2} s(z) \, \Big|1 - \cos(z \cdot k) - \frac{(z \cdot k)^2}{2}\Big| \lesssim |k|^4 \, , \\
|w(k) - \mathfrak{w} \cdot k| &\leq \sum_{z \in \mathbb{Z}^2} |a(z)| \, |\sin(z \cdot k) - z \cdot k| \lesssim |k|^3 \, ,
\end{equs}
which respectively give~\eqref{e:d0Removal} and~\eqref{e:wRemoval} (by noticing that $\sum_{i=1}^n |k_i|^p \leq |k_{1:n}|^p$ for $p \geq 2$).
\smallskip

Finally, we turn to the proof of~\eqref{e:wpqRemoval}. Using the identity $\sin(x) + \sin(y) = 2 \sin(\frac{x + y}{2}) \cos(\frac{x - y}{2}) $ together with the Taylor estimates $|\sin(\theta) - \theta| \lesssim |\theta|^3$ and $|\cos(\theta) - 1| \lesssim |\theta|^2$ , we obtain for every $x, y \in \mathbb{R}$
\begin{equ}
|\sin(x) + \sin(y) - (x + y)| \lesssim |x+y|^3 + |x + y| \, |x-y|^2 \lesssim |x+y| \, (|x|^2 + |y|^2) \, .
\end{equ}
As a consequence, for every $p,q \in \mathbb{R}^2$ we have
\begin{equ}
|w(p) + w(q) - \mathfrak{w} \cdot (p+q)| \lesssim \sum_{z \in \mathbb{Z}^2} |a(z)| \, |\sin(z \cdot p) + \sin(z \cdot q) - z \cdot (p+q)| \lesssim |\mathfrak{e} \cdot (p+q)| \, (|p|^2 + |q|^2) \, ,
\end{equ}
where in the last bound we used that $\mathrm{Supp}(a) \subset \mathbb{R} \mathfrak{e}$. This shows~\eqref{e:wpqRemoval} and concludes the proof.

We show that, for any $(\mathcal{O}, {\mathfrak O}) \in \{(\mathcal{S}, {\mathfrak S}), (\mathcal{A}_+, {\mathfrak A}_+), (\mathcal{A}_-, {\mathfrak A}_-), (\mathcal{A}_0, {\mathfrak A}_0)\}$ and for every $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}, n}
    \else
        \Gamma H^{}_{{\mathrm{rap}}, n}
    \fi
$, $n \geq 0$, $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, it holds
\begin{equ} \label{e:SoftcoreRemovalO}
\big|\langle \mathcal{O} \, \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak O} f, g\rangle\big| \lesssim_{\gamma} n \, \big(1_{{\mathfrak O} \in \{{\mathfrak S}, \, {\mathfrak A}_-, \, {\mathfrak A}_0\}} \|(- {\mathfrak L}_0)^{(1+\gamma)/2} f\| + 1_{{\mathfrak O} = {\mathfrak A}_+} \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} f\|\big) \, \|(- {\mathfrak L}_0)^{1/2} g\| \, , 
\end{equ}
Then, by noticing that $\mathsf{P} \mathsf{P}^* = \mathrm{Id}$ and using~\eqref{e:BoundP}, we deduce
\begin{equs}
\|(- \mathcal{S})^{-1/2} \, (\mathcal{O} \mathsf{P} - \mathsf{P} {\mathfrak O}) f\| &= \|(- \mathcal{S})^{-1/2} \, \mathsf{P} \, (\mathsf{P}^* \mathcal{O} \mathsf{P} - {\mathfrak O}) f\| \\
&\lesssim \|(- {\mathfrak L}_0)^{-1/2} \, (\mathsf{P}^* \mathcal{O} \mathsf{P} - {\mathfrak O}) f\| \\
&\lesssim n \, \big(1_{{\mathfrak O} \in \{{\mathfrak S}, \, {\mathfrak A}_-, \, {\mathfrak A}_0\}} \|(- {\mathfrak L}_0)^{(1+\gamma)/2} f\| + 1_{{\mathfrak O} = {\mathfrak A}_+} \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} f\|\big) \, ,
\end{equs}
where in the last bound we used~\eqref{e:SoftcoreRemovalO}. Finally, by using orthogonality of chaoses, we can extend this bound to any $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ up to replacing the factor $n$ by ${\mathfrak N}$, which results in the desired estimate~\eqref{e:SoftcoreRemoval} and would conclude the proof.
\smallskip

Now, we prove~\eqref{e:SoftcoreRemovalO}. Obviously, we can further assume that $g$ belongs respectively to $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$, $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n+1}
    \else
        \Gamma H^{}_{n+1}
    \fi
$, $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n-1}
    \else
        \Gamma H^{}_{n-1}
    \fi
$, $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$ when we prove the statement for $\mathcal{O} = \mathcal{S}, \, \mathcal{A}_+, \, \mathcal{A}_-, \, \mathcal{A}_0$.
\smallskip

We start with the case $(\mathcal{O}, {\mathfrak O}) = (\mathcal{S}, {\mathfrak S})$. We have
\begin{equ}
\langle \mathcal{S} \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak S} f, g \rangle = n! \ \frac{1}{2} \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, {\mathfrak F} f(k_{1:n}) \, \overline{{\mathfrak F} g(k_{1:n})} \, (\1_{|k_{1:n}|_\infty < \pi} \, d_0(k_{1:n}) - D_0(k_{1:n})) \, .
\end{equ}
Now, we use~\eqref{e:d0Removal} and observe that
\begin{equ}
|\1_{|k_{1:n}|_\infty < \pi} \, d_0(k_{1:n}) - D_0(k_{1:n})| \lesssim \1_{|k_{1:n}|_\infty < \pi} \, |k_{1:n}|^4 + \1_{|k_{1:n}|_\infty \geq \pi} \, |k_{1:n}|^2 \lesssim n \, (|k_{1:n}|^4 \wedge |k_{1:n}|^2) \, ,
\end{equ}
where for the second bound we used that $|k_{1:n}|^2 \lesssim n$ if $|k_{1:n}|_\infty < \pi$ and that $1 \lesssim |k_{1:n}|^2$ if $|k_{1:n}|_\infty \geq \pi$. By the Cauchy-Schwarz inequality, we then deduce
\begin{equs}
|\langle &\mathcal{S} \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak S} f, g \rangle| \\
&\lesssim n! \, n \, \Big(\int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, (|k_{1:n}|^4 \wedge |k_{1:n}|^2) \, |{\mathfrak F} f(k_{1:n})|^2\Big)^{1/2} \Big(\int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, (|k_{1:n}|^4 \wedge |k_{1:n}|^2) \, |{\mathfrak F} g(k_{1:n})|^2\Big)^{1/2} \\
&\lesssim n \|((- {\mathfrak L}_0) \wedge (- {\mathfrak L}_0)^{1/2}) \, f\| \, \|((- {\mathfrak L}_0) \wedge (- {\mathfrak L}_0)^{1/2}) \, g\| \label{e:SCremovalSNeat} \\
&\leq n \, \|(- {\mathfrak L}_0)^{(1+\gamma)/2} f\| \, \|(- {\mathfrak L}_0)^{1/2} \, g\| \, , \label{e:SCremovalSFinal}
\end{equs}
which shows~\eqref{e:SoftcoreRemovalO} for $(\mathcal{O}, {\mathfrak O}) = (\mathcal{S}, {\mathfrak S})$.
\smallskip

We turn to the case $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_+, {\mathfrak A}_+)$. We have
\begin{equ} \label{e:SoftcoreRemovalA+Proof}
\langle \mathcal{A}_+ \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak A}_+ f, g \rangle = (n+1)! \, n \, \frac{\iota \, \sqrt{\varrho(1-\varrho)}}{2 \pi}  \int_{\mathbb{R}^{2(n+1)}} \mathrm{d} k_{1:n+1} \, \overline{{\mathfrak F} g(k_{1:n+1})} \, K_+^f(k_{1:n+1}) \, , \end{equ}
where $K_+^f(k_{1:n+1})$ is a shorthand notation for
\begin{equ}
\1_{|k_{1:n+1}|_\infty < \pi} \, (w(k_1) + w(k_2)) \, {\mathfrak F} f (\llbracket k_1 + k_2 \rrbracket, k_{3:n+1}) - \Pi_{k_1, k_2} \, \mathfrak{w} \cdot (k_1 + k_2) \, {\mathfrak F} f (k_1 + k_2, k_{3:n+1}) \, . \label{e:SoftCoreRemovalA+Kernel}
\end{equ}
Note that $K_+^f(k_{1:n+1})$ vanishes if $|k_{1:2}|_\infty \geq \pi$, so we can assume that $|k_{1:2}|_\infty < \pi$. Now, we estimate $K_+^f(k_{1:n+1})$ by distinguishing the following three regions
\begin{equ}
R_1 := \{|k_{1:n+1}|_\infty < \pi, \, \Pi_{k_1, k_2} = 1\}, \ R_2 := \{|k_{1:n+1}|_\infty < \pi, \,\Pi_{k_1, k_2} = 0\}, \ R_3 := \{|k_{1:n+1}|_\infty \geq \pi\} \, . \label{e:SoftCoreRemovalA+Regions}
\end{equ}

We start with the region $R_1$. We first observe that $\llbracket k_1 + k_2 \rrbracket = k_1 + k_2$ because $k_1 + k_2 \in (- \pi, \pi)^2$ since $\Pi_{k_1, k_2} = 1$ on $R_1$. Then we use~\eqref{e:wpqRemoval} and obtain
\begin{equs}
|K_+^f(k_{1:n+1})| &\lesssim |\mathfrak{e} \cdot (k_1 + k_2)| \, (|k_1|^2 + |k_2|^2) \, |{\mathfrak F} f (k_1 + k_2, k_{3:n+1})| \\
&\lesssim |\mathfrak{e} \cdot (k_1 + k_2)| \, (|k_{1:n+1}|^2 \wedge 1) \, |{\mathfrak F} f (k_1 + k_2, k_{3:n+1})| \, , \label{e:SoftcoreRemovalA+Technical1}
\end{equs}
where in the second bound we used that $|k_{1:2}|_\infty < \pi$.

We continue with the region $R_2$ (note that only the first summand of~\eqref{e:SoftCoreRemovalA+Kernel} survives here). We first observe that
\begin{equ}
|w(k_1) + w(k_2)| = |w(k_1) + w(\llbracket k_1 + k_2 \rrbracket - k_1)| \lesssim |\mathfrak{e} \cdot \llbracket k_1 + k_2 \rrbracket| \, (1 + |k_1|^2 + |\llbracket k_1 + k_2 \rrbracket - k_1|^2) \lesssim |\mathfrak{e} \cdot \llbracket k_1 + k_2 \rrbracket| \, ,
\end{equ}
where we first used the $2 \pi \mathbb{Z}^2$ periodicity of $w$, then~\eqref{e:wpqRemoval} and finally $|k_{1:2}|_\infty < \pi$. Therefore, we deduce
\begin{equs}
|K_+^f(k_{1:n+1})| &\lesssim |\mathfrak{e} \cdot \llbracket k_1 + k_2 \rrbracket| \, |{\mathfrak F} f (\llbracket k_1 + k_2 \rrbracket, k_{3:n+1})| \\
&\lesssim |\mathfrak{e} \cdot \llbracket k_1 + k_2 \rrbracket| \, (|k_{1:n+1}|^2 \wedge 1) \, |{\mathfrak F} f (\llbracket k_1 + k_2 \rrbracket, k_{3:n+1})| \, , \label{e:SoftcoreRemovalA+Technical3}
\end{equs}
where we used in the second bound that $|k_{1:2}|_\infty \geq \pi/2$ since $\Pi_{k_1, k_2} = 0$ on $R_2$.

We finish with the region $R_3$ (note that only the second summand of~\eqref{e:SoftCoreRemovalA+Kernel} survives here), as follows
\begin{equs}
|K_+^f(k_{1:n+1})| &\lesssim |\mathfrak{e} \cdot (k_1 + k_2)| \, |{\mathfrak F} f (k_1 + k_2, k_{3:n+1})| \\
&\lesssim |\mathfrak{e} \cdot (k_1 + k_2)| \, (|k_{1:n+1}|^2 \wedge 1) \, |{\mathfrak F} f (k_1 + k_2, k_{3:n+1})| \, , \label{e:SoftcoreRemovalA+Technical2}
\end{equs}
where in the second bound we used that $|k_{1:n+1}|_\infty \geq \pi$ on $R_3$.

Coming back to~\eqref{e:SoftcoreRemovalA+Proof}, recalling that we can restrict the integral to $k_{1:2} \in [- \pi, \pi]^4$, gathering~\eqref{e:SoftcoreRemovalA+Technical1},~\eqref{e:SoftcoreRemovalA+Technical2} and~\eqref{e:SoftcoreRemovalA+Technical3}, and using the Cauchy-Schwarz inequality, we deduce
\begin{equs}
|\langle &\mathcal{A}_+ \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak A}_+ f, g \rangle| \lesssim n! \, n^2 \, \Big(\int_{\mathbb{R}^{2(n+1)}} \mathrm{d} k_{1:n+1} \, (|k_{1:n+1}|^4 \wedge 1) \, |{\mathfrak F} g(k_{1:n+1})|^2\Big)^{1/2} \\
&\qquad \qquad \qquad \times \Big(\int_{[- \pi, \pi]^{4} \times \mathbb{R}^{2(n-1)}} \mathrm{d} k_{1:n+1} \, |\mathfrak{e} \cdot (k_1 + k_2)|^2 \, |{\mathfrak F} f (k_1 + k_2, k_{3:n+1})|^2 \\
&\qquad \qquad \qquad \qquad \qquad+ \int_{[- \pi, \pi]^{4} \times \mathbb{R}^{2(n-1)}} \mathrm{d} k_{1:n+1} \, |\mathfrak{e} \cdot \llbracket k_1 + k_2 \rrbracket|^2 \, |{\mathfrak F} f (\llbracket k_1 + k_2 \rrbracket, k_{3:n+1})|^2\Big)^{1/2} \\
&\lesssim n^2 \, n! \, \Big(\int_{\mathbb{R}^{2(n+1)}} \mathrm{d} k_{1:n+1} \, (|k_{1:n+1}|^4 \wedge 1) \, |{\mathfrak F} g(k_{1:n+1})|^2\Big)^{1/2} \Big(\int_{\mathbb{R}^{2n}} \mathrm{d} \ell_{1:n} \, |\mathfrak{e} \cdot \ell_1|^2 \, |{\mathfrak F} f (\ell_{1:n})|^2\Big)^{1/2} \\
&\lesssim n \, \|((- {\mathfrak L}_0) \wedge 1) \, g\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} f\| \label{e:SoftcoreRemovalA+Neat} \\
&\leq n \, \|(- {\mathfrak L}_0)^{1/2} g\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} f\| \, , \label{e:SoftcoreRemovalA+Final} 
\end{equs}
where for the second bound we made the changes of variables $\ell_{1:n} = (k_1 + k_2, k_{3:n+1})$ and $\ell_{1:n} = (\llbracket k_1 + k_2 \rrbracket, k_{3:n+1})$ in the two last integrals, respectively.
This concludes the proof of~\eqref{e:SoftcoreRemovalO} for $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_+, {\mathfrak A}_+)$.
\smallskip

We turn to the case $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_-, {\mathfrak A}_-)$. We start from~\eqref{e:SoftcoreRemovalA+Neat}, but applied with $(g,f)$ instead of $(f,g)$ (and hence $n-1$ instead of $n$), and then we use $(\mathcal{A}_+)^* = - \mathcal{A}_-$ and $({\mathfrak A}_+)^* = - {\mathfrak A}_-$, which leads to
\begin{equ}
|\langle \mathcal{A}_- \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak A}_- f, g \rangle| \lesssim n \, \|((- {\mathfrak L}_0) \wedge 1) f\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} g\| \leq n \, \|(- {\mathfrak L}_0)^{(1+\gamma)/2} \, f\| \, \|(- {\mathfrak L}_0)^{1/2} g\| \, .
\end{equ}
This shows~\eqref{e:SoftcoreRemovalO} for $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_-, {\mathfrak A}_-)$.
\smallskip

Finally, we tackle the case $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_0, {\mathfrak A}_0)$. We have
\begin{equ}
\langle \mathcal{A}_0 \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak A}_0 f, g \rangle = n! \, (1 - 2 \varrho) \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, {\mathfrak F} f(k_{1:n}) \, \overline{{\mathfrak F} g(k_{1:n})} \, \Big(\1_{|k_{1:n}|_\infty < \pi} \sum_{i=1}^n w(k_i) - \sum_{i=1}^n \mathfrak{w} \cdot k_i\Big) \, .
\end{equ}
Now, we use~\eqref{e:wRemoval} and observe that
\begin{equ}
\Big|\1_{|k_{1:n}|_\infty < \pi} \sum_{i=1}^n w(k_i) - \sum_{i=1}^n \mathfrak{w} \cdot k_i\Big| \lesssim \1_{|k_{1:n}|_\infty < \pi} \, |k_{1:n}|^3 + \1_{|k_{1:n}|_\infty \geq \pi} \, n^{1/2} \, |k_{1:n}| \lesssim n \, (|k_{1:n}|^3 \wedge |k_{1:n}|) \, ,
\end{equ}
where in the first bound we used that $\sum_{i=1}^n |k_i| \leq n^{1/2} \, |k_{1:n}|$, and in the second bound we used that $|k_{1:n}|^2 \lesssim n$ if $|k_{1:n}|_\infty < \pi$ and that $1 \lesssim |k_{1:n}|^2$ if $|k_{1:n}|_\infty \geq \pi$. By the Cauchy-Schwarz inequality, we then deduce
\begin{equs}
|\langle &\mathcal{A}_0 \mathsf{P} f, \mathsf{P} g \rangle - \langle {\mathfrak A}_0 f, g \rangle | \\
&\lesssim n! \, n\, \Big(\int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, (|k_{1:n}|^4 \wedge 1) \, |{\mathfrak F} f(k_{1:n})|^2\Big)^{1/2} \Big(\int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |k_{1:n}|^2 \, |{\mathfrak F} g(k_{1:n})|^2\Big)^{1/2} \\
&\lesssim n \, \|((- {\mathfrak L}_0) \wedge 1) \, f\| \, \|(- {\mathfrak L}_0)^{1/2} \, g\| \\
&\leq n \, \|(- {\mathfrak L}_0)^{(1+\gamma)/2} f\| \, \|(- {\mathfrak L}_0)^{1/2} g\| ,
\end{equs}
which gives~\eqref{e:SoftcoreRemovalO} for $(\mathcal{O}, {\mathfrak O}) = (\mathcal{A}_0, {\mathfrak A}_0)$, and concludes the proof.

First, we write
\begin{equ}
\|(- S)^{-1/2} \, (L \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} {\mathfrak L}) \phi\| \leq \|(- S)^{-1/2} \, (L \mathsf{R} - \mathsf{Q}^* \mathcal{L}) \mathsf{P} \phi\| + \|(- S)^{-1/2} \, \mathsf{Q}^* (\mathcal{L} \mathsf{P} - \mathsf{P} {\mathfrak L}) \phi\| \, .
\end{equ}
To bound the first summand we use Proposition~\ref{p:HardcoreRemoval} and~\eqref{e:BoundP} (the latter trivially holds with an extra factor $\mathcal{N}^{6}$ and ${\mathfrak N}^{6}$ on both sides, by orthogonality of chaoses), which gives
\begin{equ}
\|(- S)^{-1/2} \, [L \mathsf{R} - \mathsf{Q}^* \mathcal{L}] \mathsf{P} \phi\| \lesssim_\gamma \|\mathcal{N}^{6} \, (- \mathcal{S})^{(1+\gamma)/2} \, \mathsf{P} \phi\| \lesssim \|{\mathfrak N}^{6} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \phi\| \, .
\end{equ}
To bound the second summand we use~\eqref{e:BoundQ*} and Proposition~\ref{p:SoftcoreRemoval} (the latter trivially holds with an extra factor $\mathcal{N}^3$ and ${\mathfrak N}^3$ on both sides, by orthogonality of chaoses), which gives
\begin{equs}
\|(- S)^{-1/2} \, \mathsf{Q}^* (\mathcal{L} \mathsf{P} - \mathsf{P} {\mathfrak L}) \phi\| &\lesssim \|\mathcal{N}^3 \, (- \mathcal{S})^{-1/2} \, (\mathcal{L} \mathsf{P} - \mathsf{P} {\mathfrak L}) \phi\| \\
&\lesssim \|{\mathfrak N}^{4} (- {\mathfrak L}_0)^{(1+\gamma)/2} \phi\| + \|{\mathfrak N}^{4} (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, ,
\end{equs}
By gathering the previous bounds, we deduce the desired estimate~\eqref{e:ComparisonGen}. Obviously, we can proceed similarly with any of $(S, \mathcal{S}, {\mathfrak S})$, $(A_+, \mathcal{A}_+, {\mathfrak A}_+)$, $(A_-, \mathcal{A}_-, {\mathfrak A}_-)$ or $(A_0, \mathcal{A}_0, {\mathfrak A}_0)$ instead of $(L, \mathcal{L}, {\mathfrak L})$, since Propositions~\ref{p:HardcoreRemoval} and~\ref{p:SoftcoreRemoval} apply to each of them (besides, the last summand $\|{\mathfrak N}^4 (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\|$ is only required to deal with $(A_+, \mathcal{A}_+, {\mathfrak A}_+)$). This concludes the proof.

\label{lem:ComparisonH1}
For every $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $\gamma \in [0,1)$, we have
\begin{equ} \label{e:ComparisonH1}
\Big|\|(- S)^{1/2} \, \mathsf{R} \mathsf{P} \phi\|^2 - \|(- {\mathfrak S})^{1/2} \phi\|^2\Big| \lesssim_\gamma \|{\mathfrak N} \, (- {\mathfrak L}_0)^{(1 + \gamma)/2} \phi\|^2 \, .
\end{equ}

By orthogonality of chaoses, it is sufficient to prove~\eqref{e:ComparisonH1} for every $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$ and $n \geq 1$. By using~\eqref{e:HCremovalS} (together with~\eqref{e:BoundP}) and~\eqref{e:SCremovalSNeat}, we obtain
\begin{equs}
\big|\langle (- S) \mathsf{R} \mathsf{P} \phi, \mathsf{R} \mathsf{P} \phi \rangle - \langle (- \mathcal{S}) \mathsf{P} \phi, \mathsf{P} \phi \rangle\big| &\lesssim_\gamma n \, \|(- \mathcal{S})^{(1+\gamma)/2} \, \mathsf{P} \phi\|^2 \lesssim_\gamma n \, \|(- {\mathfrak L}_0)^{(1+\gamma)/2} \phi\|^2 \, , \\
\big|\langle (- \mathcal{S}) \mathsf{P} \phi, \mathsf{P} \phi \rangle - \langle (-{\mathfrak S}) \phi, \phi \rangle\big| &\lesssim n \, \|((- {\mathfrak L}_0) \wedge (- {\mathfrak L}_0)^{1/2}) \, \phi\|^2 \leq n \, \|(- {\mathfrak L}_0)^{(1+\gamma)/2} \phi\|^2 \, ,
\end{equs}
which gives, after summing the two bounds, the desired estimate~\eqref{e:ComparisonH1} and concludes the proof.

\label{def:Sharp}
We define the operators $\bar {\mathfrak A}^\sharp := {\mathfrak A}_+^\sharp + {\mathfrak A}_-^\sharp$ and $\bar {\mathfrak A}^\flat := {\mathfrak A}_+^\flat + {\mathfrak A}_-^\flat$ acting (continuously) from $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ to itself as follows. For $f \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equs}
{\mathfrak F} ({\mathfrak A}_+^{\sharp / \flat} f) \, (k_{1:n+1}) &\stackrel{\mbox{\tiny\rm def}}{=} \frac{\sqrt{\varrho(1-\varrho)}}{\pi (n+1)} \sum_{1 \leq i < j \leq n+1} \chi^{\sharp / \flat}(k_i, k_j; k_i + k_j, k_{1:n+1 \setminus i,j}) \label{e:fA+Sharp} \\
&\qquad \qquad \qquad \qquad \qquad \qquad \times \iota (\mathfrak{w} \cdot (k_i+k_j)) \, \Pi_{k_i, k_j} \, {\mathfrak F} f (k_i + k_j, k_{1:n+1 \setminus i,j}) \\
{\mathfrak F} ({\mathfrak A}_-^{\sharp / \flat} f) \, (k_{1:n-1}) &\stackrel{\mbox{\tiny\rm def}}{=} \frac{\sqrt{\varrho(1-\varrho)} \, n}{2 \pi} \sum_{i=1}^{n-1} \iota (\mathfrak{w} \cdot k_i) \, \int_{\mathbb{R}^2} \mathrm{d} \ell \ \chi^{\sharp / \flat}(\ell, k_i - \ell; k_{1:n-1}) \label{e:fA-Sharp} \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times \Pi_{\ell, k_i-\ell} \, {\mathfrak F} f (\ell, k_i-\ell, k_{1:n-1 \setminus i}) \, ,
\end{equs}
where $\Pi_{\cdot, \cdot}$ was defined in~\eqref{e:CutOff}, and for $a, b \in \mathbb{R}^2$ and $c_{1:n} \in \mathbb{R}^{2n}$ we set
\begin{equ}
\chi^\sharp(a, b ; c_{1:n}) \stackrel{\mbox{\tiny\rm def}}{=} \1_{|a| \wedge |b| \geq 3 \, |c_{1:n}|} \, , \quad \chi^\flat \stackrel{\mbox{\tiny\rm def}}{=} 1 - \chi^\sharp \, .
\end{equ}
By construction, ${\mathfrak A}_{\pm} = {\mathfrak A}_{\pm}^\sharp + {\mathfrak A}_{\pm}^\flat$ (compare~\eqref{e:fA+Sharp} and~\eqref{e:fA-Sharp} with~\eqref{e:fA+} and~\eqref{e:fA-}). Moreover, $\bar {\mathfrak A}^\sharp$ and $\bar {\mathfrak A}^\flat$ are skew-symmetric on $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$; more precisely, $({\mathfrak A}_+^\sharp)^* = - {\mathfrak A}_-^\sharp$ and $({\mathfrak A}_+^\flat)^* = - {\mathfrak A}_-^\flat$ (see~\cite[Lemma 3.2]{CMT25}).

\label{lem:SummabilityAnsatz}
For every $\mu > 0$, the series in~\eqref{e:TrueAnsatz} converges normally in $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ in the following sense: for all $a, b \geq 0$ and $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:SummabilityAnsatz}
\sum_{n = 0}^\infty \|{\mathfrak N}_*^a \, (1 - {\mathfrak L}_0)^b \ \big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \lesssim_{\mu, a, b} \|{\mathfrak N}_*^a \, (1 - {\mathfrak L}_0)^b \, \bm \varphi\| \, .
\end{equ}
Consequently,~\eqref{e:TrueAnsatz} defines a continuous operator $\mathfrak{Ans}_{\mu} \colon 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \to 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, and the sum may be interchanged with any continuous operator ${\mathfrak O} \colon 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \to 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$.

\label{rmk:AnsatzIdentity}
The recursive structure of the Ansatz can be expressed through the identity
\begin{equ} \label{e:AnsatzIdentity}
\mathfrak{Ans}_{\mu}(\bm \varphi) = (\mu - {\mathfrak L}_\mu^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp \, \mathfrak{Ans}_{\mu}(\bm \varphi) + (\mu - {\mathfrak L}_\mu^{\mathrm{eff}})^{-1} \bm \varphi \, .
\end{equ}
Indeed,~\eqref{e:AnsatzIdentity} follows directly from~\eqref{e:TrueAnsatz}, since Lemma~\ref{lem:SummabilityAnsatz} allows us to interchange the sum with the continuous operator $(\mu - {\mathfrak L}_\mu^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp$.

\label{rmk:ComparisonCMTansatz}
The Ansatz $\mathfrak{Ans}_\mu(\bm\varphi)$ differs from the construction in~\cite{CMT25} in a few technical respects, which we briefly describe.
First, we work with the ``microscopic'' SBE generator ${\mathfrak L}$, whereas that paper uses the superdiffusively rescaled generator ${\mathfrak L}^\tau = \tau \, ({\mathfrak U}_0^\tau)^{-1} \, \bar {\mathfrak L} \, {\mathfrak U}_0^\tau$. Thus, transferring its results to our setting requires an appropriate conjugation by ${\mathfrak U}^\tau$ and an adjustment of the powers of $\tau$ in the corresponding estimates.
Second, the cut-off $\Pi_{p,q}$ is defined there as $(2 \pi {\mathfrak F} \varrho(p))^2 (2 \pi {\mathfrak F} \varrho(q))^2 (2 \pi {\mathfrak F} \varrho(p+q))^2$ for a smooth compactly supported test function $\varrho$, rather than by the Fourier truncation~\eqref{e:CutOff}. Relatedly, the norm on $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$ used there contains the additional Fourier weight $\prod_{i=1}^n (2 \pi {\mathfrak F} \varrho(k_i))^2$.
Third, that paper treats only the case $D_0 = \mathrm{Id}$. Although one can always reduce to this case by appropriately rescaling space, this would be inconvenient here: for instance, it would replace $\mathrm{Log}(\mu - {\mathfrak L}_0)$ in~\eqref{e:Modulation} by $\mathrm{Log}(\mu - {\mathfrak S})$.
Finally, the auxiliary parameter $\nu_0$ (denoted by $M$ in that paper) enters the construction differently. Instead of $\Upsilon$, the earlier construction uses $\nu_0 \vee \Upsilon_0$, where $\Upsilon_0$ solves~\eqref{e:ODE} with initial condition $0$. Our choice simplifies some subsequent calculations.

\label{p:GenericAnsatz}
Let $\mu > 0$, $\theta \in (1/2,1]$, $\alpha \in [1, \sqrt{2 \theta})$, $\kappa \geq 0$ and $\gamma \in (0,1]$. For every $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ we have
\begin{equs}
\, \sqrt{\mu} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| &\lesssim_{\alpha, \kappa} \sqrt{\mu} \, K_{\alpha, \kappa}^{0}(\bm \varphi) \, , \label{e:AnsatzL2} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| &\lesssim_{\alpha, \kappa} K_{\alpha, \kappa}^{1/2}(\bm \varphi) + K_{\alpha, \kappa}^{1/2, \mathfrak{e}, 1}(\bm \varphi) \, , \label{e:AnsatzH1} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \,  \mathfrak{Ans}_{\mu}(\bm \varphi)\| &\lesssim_{\alpha, \kappa, \theta} K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}(\bm \varphi)  \, , \label{e:AnsatzH1fe} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| &\lesssim_{\alpha, \kappa, \theta, \gamma} K_{\alpha, \kappa}^{(1+\gamma)/2}(\bm \varphi) + K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}(\bm \varphi) \, , \label{e:AnsatzH1+gamma} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, \big((\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_{\mu}(\bm \varphi) - \bm \varphi &+ {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\big)\| \lesssim_{\alpha, \kappa, \theta} K_{\alpha, \kappa + 1}^{1/2, \mathfrak{e}, \theta}(\bm \varphi) \, , \quad \label{e:AnsatzGen} \\
\Big|\|(\mu - {\mathfrak S})^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\|^2 - \|(\mu &- {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1/2} \, \bm \varphi\|^2\Big| \lesssim_{\theta}
K_{1, 0}^{1/2, \mathfrak{e}, \theta}(\bm \varphi)^2 \, , \label{e:AnsatzH1precise}
\end{equs}
where we additionally assume for~\eqref{e:AnsatzH1precise} that $\bm \varphi$ belongs to a homogeneous chaos (that is, $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$ for some $n \geq 0$), and where we have written $\bar {\mathfrak L} \stackrel{\mbox{\tiny\rm def}}{=} {\mathfrak L} - {\mathfrak A}_0$ and set
\begin{equs}[e:AnsatzConstantK]
K_{\alpha, \kappa}^s(\bm \varphi) &:= \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{s} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, , \\
K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}(\bm \varphi) &:= \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, .
\end{equs}

\label{rmk:ComparisonCMTestimates}
Compared with the corresponding results in~\cite{CMT25}, Proposition~\ref{p:GenericAnsatz} provides three key refinements:
\begin{itemize}
    \par\hangindent 40\p@ The $H^{1+\gamma}$ estimate~\eqref{e:AnsatzH1+gamma} is new. As indicated by Theorem~\ref{th:ComparisonGen} and Section~\ref{sec:Roadmap} (cf.~\eqref{e:HCremovalMeso} and~\eqref{e:CorrectorH1gammaRoadmap}), the control of the $H^{1+\gamma}$-norm of the Ansatz is essential for a sharp comparison between the ASEP and SBE generators. As shown below, this estimate can be deduced from the $\mathfrak{e}$-directed $H^1$ bound~\eqref{e:AnsatzH1fe} by exploiting the recursive structure~\eqref{e:AnsatzIdentity}.

    \par\hangindent 40\p@ Our estimates allow both polynomial and exponential weights in the number operator ${\mathfrak N}_*^\kappa \, \alpha^{\mathfrak N}$. These weights are essential to compensate for two sources of losses at high chaos levels: the polynomial factor ${\mathfrak N}^6$ arising in the comparison of generators in Theorem~\ref{th:ComparisonGen}, and the exponential factor $\alpha(p)^N$ arising from hypercontractivity (see Proposition~\ref{p:TightnessBlackBox}), which enters the tightness argument. An exponentially weighted version of the $\mathfrak{e}$-directed $H^1$ estimate~\eqref{e:AnsatzH1fe} was already established in~\cite[Proposition 4.8 and Remark 4.10]{CMT25}. In fact, similar weighted estimates can be obtained for~\eqref{e:AnsatzL2} and~\eqref{e:AnsatzGen} with little additional work. However, obtaining the exponentially weighted estimate for the full $H^1$ norm~\eqref{e:AnsatzH1} requires a new argument, based on a different use of the \emph{recursive replacement lemma}~\cite[Lemma 3.9]{CMT25}.

    \par\hangindent 40\p@ The estimate corresponding to~\eqref{e:AnsatzGen} in~\cite[Proposition 4.6]{CMT25} controls the difference between the Ansatz and the resolvent $(\mu - \bar {\mathfrak L})^{-1} \bm \varphi$ in $H^1$ norm, rather than directly controlling the action of the generator in $H^{-1}$ norm as in~\eqref{e:AnsatzGen}. In fact, starting from~\eqref{e:AnsatzGen}, one recovers such a bound by moving the term ${\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_\mu^{\mathrm{eff}})^{-1} \bm \varphi$ to the right-hand side using the triangle inequality, and then applying the standard resolvent bound from $H^{-1}$ to $H^1$. However, either of these two losses would be too crude for establishing a fluctuation-dissipation relation. A small adaptation of the proof of~\cite{CMT25} avoids both losses and gives an estimate of the form~\eqref{e:AnsatzGen}.
\end{itemize}

For the reader's convenience, we give a complete proof of Proposition~\ref{p:GenericAnsatz}. Most of the details are deferred to Appendices~\ref{app:ReplLemma} and~\ref{app:GenericAnsatz}; here we present the main new argument, which yields the first two improvements discussed in Remark~\ref{rmk:ComparisonCMTestimates}. We begin by outlining the four steps of the proof. During the first two steps, the auxiliary parameter $\nu_0$ (the initial condition of $\Upsilon$, cf.~\eqref{e:ODE}) will not yet be fixed. We therefore work with a free parameter $\nu \geq 0$ in its place, and add a subscript $\nu$ to write the corresponding objects (e.g., $\Upsilon_\nu$ or ${\mathfrak L}^{\mathrm{eff}}_{\mu, \nu}$).
\smallskip

{\it Step 0. The replacement lemmas:} The main technical tools in the analysis of the SBE Ansatz are the replacement lemmas. They estimate expressions of the form $\langle {\mathfrak D} {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi\rangle$ for specific diagonal operators ${\mathfrak D}$ built from modulations of ${\mathfrak L}_0^\mathfrak{e}$. More precisely, we shall use the following two estimates, corresponding to the replacement lemma and the recursive replacement lemma of~\cite[Lemmas 3.6 and 3.9]{CMT25}.

\begin{lemma} \label{lem:ReplLemma}
1) For every $\nu \geq 0$, $\mu > 0$ and $\phi, \psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:ReplFixPt}
\big|\langle \big(- {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp + {\mathfrak L}_0^\mathfrak{e}[\Upsilon_\nu]_\mu\big) \, \phi, \psi \rangle\big| \lesssim_\nu  \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \psi\| \, ,
\end{equ}

2) There exists $\nu_1 \geq 0$, depending only on $D_0$ and $\lambda$, such that for every $\nu \geq \nu_1$, $\theta \in (0, 1]$, $\mu > 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:ReplContraction}
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon_\nu^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\|^2 \leq \frac{1}{2 \theta} \, \|(- {\mathfrak L}_0^\mathfrak{e} \big[\tilde \Upsilon_\nu^\theta\big]_\mu)^{1/2} \, \phi\|^2 \, .
\end{equ}
\end{lemma}

The first estimate shows that $- {\mathfrak L}_0^\mathfrak{e}[\Upsilon_\nu]_\mu$ approximately solves the fixed point equation~\eqref{e:FixedPointRoadmap}. The second shows that, when $\theta \in (1/2, 1]$, the operator $(\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp$ is a strict contraction in the norm $\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon_\nu^\theta\big]_\mu)^{1/2} \cdot\|$. Both statements are special cases of Lemma~\ref{lem:ReplLemmaGeneral}, proved in Appendix~\ref{app:ReplLemma}. Here, applying the recursive replacement lemma directly with the modulations $\tilde \Upsilon_\nu^\theta$, as in~\eqref{e:ReplContraction}, slightly simplifies the approach of~\cite{CMT25} and, importantly, will yield in addition the exponentially weighted $H^1$ estimate~\eqref{e:AnsatzH1}.
\smallskip

{\it Step 1. The $L^2$ estimates:} In Appendix~\ref{app:GenericAnsatz}, we prove~\eqref{e:AnsatzL2} and Lemma~\ref{lem:SummabilityAnsatz} using an $L^2$ contraction estimate for $(\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp$, following the strategy of~\cite[Proposition 4.3]{CMT25}. At this stage we also fix $\nu = \nu_0$ as in Definition~\ref{def:nu}.
\smallskip

{\it Step 2. The $H^1$-type estimates:} We then establish~\eqref{e:AnsatzH1},~\eqref{e:AnsatzH1fe} and~\eqref{e:AnsatzH1+gamma} by combining the recursive replacement lemma~\eqref{e:ReplContraction} with the recursive identity~\eqref{e:AnsatzIdentity}. Since this argument is the main new ingredient, we give it in full below.
\smallskip

{\it Step 3. The generator estimates:} Finally, we prove in Appendix~\ref{app:GenericAnsatz} the estimates~\eqref{e:AnsatzGen} and~\eqref{e:AnsatzH1precise} by combining the replacement lemma~\eqref{e:ReplFixPt} with the $\mathfrak{e}$-directed $H^1$ bound~\eqref{e:AnsatzH1fe}.
\medskip

We now carry out Step 2. The starting point is the following estimate for the Ansatz in the modulated $\mathfrak{e}$-directed $H^1$ norm $\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \cdot\|$, which follows directly from the recursive replacement lemma~\eqref{e:ReplContraction}.

\begin{lemma} \label{lem:H1feEstimate}
Let $\theta \in (1/2, 1]$, $\alpha \in [1, \sqrt{2 \theta})$ and $\kappa \geq 0$. For every $\mu > 0$ and $\bm{\varphi} \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ}  \label{e:H1feEstimate}
\|{\mathfrak N}_*^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \lesssim_{\alpha, \kappa, \theta} \|{\mathfrak N}_*^\kappa \alpha^{{\mathfrak N}} \, (-{\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| = K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}(\bm \varphi) \, .
\end{equ}
\end{lemma}

\begin{proof}[of Lemma~\ref{lem:H1feEstimate}]
Iterating~\eqref{e:ReplContraction}, we find that, for any $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$,
\begin{equ}
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, \big((\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp\big)^n (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| \leq \frac{1}{(2 \theta)^{n/2}} \, \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| \, .
\end{equ}
Since the operator $\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}$ maps $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0}
    \fi
$ into $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0 + n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0 + n}
    \fi
$ for any $n_0 \geq 0$, the orthogonality of chaoses and the bound $(n_0 + n)_*^\kappa \, \alpha^{n_0 + n} \lesssim_\kappa n_*^\kappa \alpha^n \, (n_0)_*^\kappa \alpha^{n_0}$ further give, for any $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$,
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \big((\mu - &{\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}  \bm \varphi\| \\
&\lesssim_\kappa \frac{n_*^\kappa \alpha^n}{(2 \theta)^{n/2}} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, .
\end{equs}
By summing this bound over $n \geq 0$ (recall that $\alpha < \sqrt{2 \theta}$) and recognising~\eqref{e:TrueAnsatz}, we deduce~\eqref{e:H1feEstimate}.
\end{proof}

A direct application of Lemma~\ref{lem:H1feEstimate} gives the $\mathfrak{e}$-directed $H^1$ estimate~\eqref{e:AnsatzH1fe}. Indeed, by using the trivial lower bound $\tilde \Upsilon^\theta \geq \det(D_0)^{\theta} \gtrsim 1$, we obtain
\begin{equ}
\|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \lesssim \|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \, ,
\end{equ}
which shows~\eqref{e:AnsatzH1fe} after using~\eqref{e:H1feEstimate}.
\smallskip

To prove~\eqref{e:AnsatzH1} and~\eqref{e:AnsatzH1+gamma}, the idea is to exploit the recursive identity~\eqref{e:AnsatzIdentity} which, thanks to the next lemma, makes it possible to bound the $H^1$ and $H^{1+\gamma}$ norms of the Ansatz by appropriate modulated $\mathfrak{e}$-directed $H^1$ norms.

\begin{lemma} \label{lem:ConvertionH1GA+}
For every $\gamma \in (0,1]$, $\mu > 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equs}
\|(\mu - {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \phi\| \, , \label{e:ConvertionH1feH1GA+} \\
\|(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim_\gamma \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, . \label{e:ConvertionH1feH1gammaGA+}
\end{equs}
\end{lemma}

\begin{proof}[of Lemma~\ref{lem:ConvertionH1GA+}]

We start with~\eqref{e:ConvertionH1feH1GA+}. The trivial bound $- {\mathfrak L}_0 \leq - \|D_0^{-1}\| \, {\mathfrak L}_{\mu}^{\mathrm{eff}}$ gives
\begin{equs}
\|(\mu - {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \, \phi\|^2 &\lesssim \langle (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi\rangle \\
&\lesssim \langle - {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu \, \phi, \phi\rangle + \langle - {\mathfrak L}_0^\mathfrak{e} \, \phi, \phi\rangle \\
&\lesssim \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \phi\|^2 \, ,
\end{equs}
where the second inequality follows from the first replacement lemma~\eqref{e:ReplFixPt}. This proves~\eqref{e:ConvertionH1feH1GA+}.

We turn to~\eqref{e:ConvertionH1feH1gammaGA+}. By orthogonality of chaoses, it is sufficient to prove the bound for $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$, with $n \geq 1$. We apply~\eqref{e:SharpDiag} from Lemma~\ref{lem:Diag} and use the notation~\eqref{e:XiNotation}, which leads to
\begin{equs}
\|&(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \, {\mathfrak A}_+^\sharp \phi\|^2 = \langle (\mu - {\mathfrak L}_0)^{1 + \gamma} (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-2} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi \rangle_{\mathrm{diag}} \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{(\mu + \Xi_0)^{1 + \gamma} \, \1_{|p|_\infty \leq \pi} \, \mathrm{d} p}{(\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e})^2} \, \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{\1_{|p|_\infty \leq \pi} \, \mathrm{d} p}{|p|^{2 - 2 \gamma}} \, , \\
&\lesssim_\gamma \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\|^2 \, ,
\end{equs}
where in the third line we used $(\mu + \Xi_0)^{1 + \gamma} \lesssim (\mu + \Xi)^{1 + \gamma}$ and $\Xi \gtrsim |p|^2$ (cf.~\eqref{e:Triangular}), and in the fourth line we noticed that the last integral is finite since $\gamma > 0$. This proves~\eqref{e:ConvertionH1feH1gammaGA+}.
\end{proof}

We are now ready to show~\eqref{e:AnsatzH1} and~\eqref{e:AnsatzH1+gamma}. By applying~\eqref{e:ConvertionH1feH1GA+} and~\eqref{e:ConvertionH1feH1gammaGA+} in each chaos and accounting for the weights in the number operator, we obtain for any $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim_{\kappa, \alpha} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \phi\| \, , \label{e:ConvertionH1feH1GA+bis} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim_{\kappa, \alpha, \gamma} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, . \label{e:ConvertionH1feH1gammaGA+bis}
\end{equs}
By taking $\phi = \mathfrak{Ans}_{\mu}(\bm \varphi)$ and using the recursive identity~\eqref{e:AnsatzIdentity}, we deduce
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, &(- {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \\
&\lesssim_{\kappa, \alpha} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| + \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, , \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, &(- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \\
&\lesssim_{\kappa, \alpha, \gamma} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| + \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, .
\end{equs}
The first terms on the two right-hand sides can be bounded by using~\eqref{e:H1feEstimate} with $\theta = 1$ and~\eqref{e:AnsatzH1fe}, respectively. This results in the desired estimates~\eqref{e:AnsatzH1} and~\eqref{e:AnsatzH1+gamma}, and completes Step 2 of the proof of Proposition~\ref{p:GenericAnsatz}.

\label{lem:ReplLemma}
1) For every $\nu \geq 0$, $\mu > 0$ and $\phi, \psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:ReplFixPt}
\big|\langle \big(- {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp + {\mathfrak L}_0^\mathfrak{e}[\Upsilon_\nu]_\mu\big) \, \phi, \psi \rangle\big| \lesssim_\nu  \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \psi\| \, ,
\end{equ}

2) There exists $\nu_1 \geq 0$, depending only on $D_0$ and $\lambda$, such that for every $\nu \geq \nu_1$, $\theta \in (0, 1]$, $\mu > 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:ReplContraction}
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon_\nu^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu, \nu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\|^2 \leq \frac{1}{2 \theta} \, \|(- {\mathfrak L}_0^\mathfrak{e} \big[\tilde \Upsilon_\nu^\theta\big]_\mu)^{1/2} \, \phi\|^2 \, .
\end{equ}

\label{lem:H1feEstimate}
Let $\theta \in (1/2, 1]$, $\alpha \in [1, \sqrt{2 \theta})$ and $\kappa \geq 0$. For every $\mu > 0$ and $\bm{\varphi} \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ}  \label{e:H1feEstimate}
\|{\mathfrak N}_*^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \lesssim_{\alpha, \kappa, \theta} \|{\mathfrak N}_*^\kappa \alpha^{{\mathfrak N}} \, (-{\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| = K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}(\bm \varphi) \, .
\end{equ}

Iterating~\eqref{e:ReplContraction}, we find that, for any $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$,
\begin{equ}
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, \big((\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp\big)^n (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| \leq \frac{1}{(2 \theta)^{n/2}} \, \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| \, .
\end{equ}
Since the operator $\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}$ maps $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0}
    \fi
$ into $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0 + n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0 + n}
    \fi
$ for any $n_0 \geq 0$, the orthogonality of chaoses and the bound $(n_0 + n)_*^\kappa \, \alpha^{n_0 + n} \lesssim_\kappa n_*^\kappa \alpha^n \, (n_0)_*^\kappa \alpha^{n_0}$ further give, for any $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$,
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \big((\mu - &{\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}  \bm \varphi\| \\
&\lesssim_\kappa \frac{n_*^\kappa \alpha^n}{(2 \theta)^{n/2}} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, .
\end{equs}
By summing this bound over $n \geq 0$ (recall that $\alpha < \sqrt{2 \theta}$) and recognising~\eqref{e:TrueAnsatz}, we deduce~\eqref{e:H1feEstimate}.

\label{lem:ConvertionH1GA+}
For every $\gamma \in (0,1]$, $\mu > 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equs}
\|(\mu - {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \phi\| \, , \label{e:ConvertionH1feH1GA+} \\
\|(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\| &\lesssim_\gamma \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, . \label{e:ConvertionH1feH1gammaGA+}
\end{equs}

We start with~\eqref{e:ConvertionH1feH1GA+}. The trivial bound $- {\mathfrak L}_0 \leq - \|D_0^{-1}\| \, {\mathfrak L}_{\mu}^{\mathrm{eff}}$ gives
\begin{equs}
\|(\mu - {\mathfrak L}_0)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \, \phi\|^2 &\lesssim \langle (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi\rangle \\
&\lesssim \langle - {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu \, \phi, \phi\rangle + \langle - {\mathfrak L}_0^\mathfrak{e} \, \phi, \phi\rangle \\
&\lesssim \|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \, \phi\|^2 \, ,
\end{equs}
where the second inequality follows from the first replacement lemma~\eqref{e:ReplFixPt}. This proves~\eqref{e:ConvertionH1feH1GA+}.

We turn to~\eqref{e:ConvertionH1feH1gammaGA+}. By orthogonality of chaoses, it is sufficient to prove the bound for $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$, with $n \geq 1$. We apply~\eqref{e:SharpDiag} from Lemma~\ref{lem:Diag} and use the notation~\eqref{e:XiNotation}, which leads to
\begin{equs}
\|&(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \, {\mathfrak A}_+^\sharp \phi\|^2 = \langle (\mu - {\mathfrak L}_0)^{1 + \gamma} (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-2} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi \rangle_{\mathrm{diag}} \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{(\mu + \Xi_0)^{1 + \gamma} \, \1_{|p|_\infty \leq \pi} \, \mathrm{d} p}{(\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e})^2} \, \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{\1_{|p|_\infty \leq \pi} \, \mathrm{d} p}{|p|^{2 - 2 \gamma}} \, , \\
&\lesssim_\gamma \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\|^2 \, ,
\end{equs}
where in the third line we used $(\mu + \Xi_0)^{1 + \gamma} \lesssim (\mu + \Xi)^{1 + \gamma}$ and $\Xi \gtrsim |p|^2$ (cf.~\eqref{e:Triangular}), and in the fourth line we noticed that the last integral is finite since $\gamma > 0$. This proves~\eqref{e:ConvertionH1feH1gammaGA+}.

\label{p:AnsatzA+}

Let $\varepsilon \in (0,1/6)$, $\alpha \in [1, \sqrt{1 + 6 \varepsilon})$, $\kappa \geq 0$ and $\gamma \in (0,1]$. For every $\tau \geq 1$, $\mu > 0$ such that $\mu \tau \geq 1$, and $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, it holds
\begin{equs}
\sqrt{\mu \tau} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| &\lesssim_{\alpha, \kappa} \log_{*}(\tau)^{-1/3} \, C_{\alpha, \kappa}^{1/2}(\varphi) \, , \label{e:AnsatzA+L2} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- \tau {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| &\lesssim_{\alpha, \kappa} C_{\alpha, \kappa}^{1/2}(\varphi) \, , \label{e:AnsatzA+H1} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- \tau {\mathfrak L}_0^\mathfrak{e})^{1/2} \,  \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| &\lesssim_{\alpha, \kappa, \varepsilon} \log_{*}(\tau)^{-1/6 + \varepsilon} \, C_{\alpha, \kappa}^{1/2}(\varphi) \, , \label{e:AnsatzA+H1fe} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \tau^{- \gamma/2} (- \tau {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| &\lesssim_{\alpha, \kappa, \gamma, \varepsilon} \log_{*}(\tau)^{-1/6 + \varepsilon} \, C_{\alpha, \kappa}^{1}(\varphi) \, . \label{e:AnsatzA+H1+gamma} \\
\Big\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (\mu \tau - \tau {\mathfrak L}_0)^{-1/2} \, \Big(\tau {\mathfrak A}_+ {\mathfrak U}_t^\tau \varphi + (\partial_t + \tau {\mathfrak L}) \, &\mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big)\Big\| \\
&\lesssim_{\alpha, \kappa, \varepsilon} \log_{*}(\tau)^{-1/6 + \varepsilon} \, C^1_{\alpha, \kappa+1}(\varphi) \, , \label{e:AnsatzA+Gen}
\end{equs}

\label{lem:AnsatzA+bis}
In the notation of Proposition~\ref{p:GenericAnsatz}, for every $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ we have
\begin{equs}
\, \sqrt{\mu} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \mathfrak{Ans}_{\mu}({\mathfrak A}_+^\sharp \phi)\| &\lesssim_{\alpha, \kappa} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, , \label{e:AnsatzA+L2bis} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_{\mu}({\mathfrak A}_+^\sharp \phi)\| &\lesssim_{\alpha, \kappa} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \phi\| \, , \label{e:AnsatzA+H1bis} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \,  \mathfrak{Ans}_{\mu}({\mathfrak A}_+^\sharp \phi)\| &\lesssim_{\alpha, \kappa, \theta} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| \, , \label{e:AnsatzA+H1febis} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_{\mu}({\mathfrak A}_+^\sharp \phi)\| &\lesssim_{\alpha, \kappa, \theta, \gamma} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| \, , \label{e:AnsatzA+H1gammabis} \\
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} (\mu - {\mathfrak L}_0)^{-1/2} \big(\bar {\mathfrak L} \, \mathfrak{Ans}_{\mu}({\mathfrak A}_+^\sharp \phi) + {\mathfrak A}_+ \phi &- {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu \phi\big)\| \lesssim_{\alpha, \kappa, \theta} \|{\mathfrak N}_{*}^{\kappa+1} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| \, . \qquad \ \ \label{e:GenAnsatzA+bis}
\end{equs}

Recall the constants $K$ defined in~\eqref{e:AnsatzConstantK} in Proposition~\ref{p:GenericAnsatz}. We first claim that
\begin{equs}
K_{\alpha, \kappa}^{1/2}({\mathfrak A}_+^\sharp \phi) &\lesssim_{\alpha, \kappa} \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^{\mathfrak{e}}\big[\tilde \Upsilon^1\big]_\mu)^{1/2} \phi\| \, , \label{e:BoundK1A+} \\
K_{\alpha, \kappa}^{(1+\gamma)/2}({\mathfrak A}_+^\sharp \phi) &\lesssim_{\alpha, \kappa}  \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, , \label{e:BoundK1gammaA+} \\
K_{\alpha, \kappa}^{1/2, \mathfrak{e}, \theta}({\mathfrak A}_+^\sharp \phi) &\lesssim_{\alpha, \kappa}  \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| \, , \label{e:BoundK1feA+} \\
K_{\alpha, \kappa}^0({\mathfrak A}_+^\sharp \phi) &\lesssim_{\alpha, \kappa} \mu^{-1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^{\mathfrak{e}})^{1/2} \phi\| \, . \label{e:BoundK0A+}
\end{equs}
By orthogonality of chaoses, to prove the above claim we can reduce to the case $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n}
    \else
        \Gamma H^{}_{n}
    \fi
$ with $n \geq 1$, and $\alpha = 1$, $\kappa = 0$ (up to dividing both sides by $n_*^\kappa \alpha^n$). Note that~\eqref{e:BoundK1A+} and~\eqref{e:BoundK1gammaA+} immediately follow from~\eqref{e:ConvertionH1feH1GA+} and~\eqref{e:ConvertionH1feH1gammaGA+}. As for~\eqref{e:BoundK1feA+}, it readily follows from the recursive replacement lemma~\eqref{e:ReplContraction}. We turn to the proof of~\eqref{e:BoundK0A+}: by using the trivial bound $- {\mathfrak L}^\mathrm{eff}_\mu \geq \|D_0\|^{-1} \, (- {\mathfrak L}_0)$, the identity~\eqref{e:SharpDiag} from Lemma~\ref{lem:Diag}, and the integral estimate $\int_{\mathbb{R}^2} \frac{\mathrm{d} p}{(\mu + |p|^2)^2} \lesssim \mu^{-1}$, we deduce
\begin{equs}
K_{1, 0}^0({\mathfrak A}_+^\sharp \phi)^2 &\lesssim \langle (\mu - {\mathfrak L}_0)^{-2} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi \rangle_{\mathrm{diag}} \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{\mathrm{d} p}{(\mu + |p|^2)^2} \\
&\lesssim \mu^{-1} \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\|^2 \, .
\end{equs}

Now that we have proved the claim, the estimates~\eqref{e:AnsatzA+L2bis},~\eqref{e:AnsatzA+H1bis},~\eqref{e:AnsatzA+H1febis},~\eqref{e:AnsatzA+H1gammabis} readily follow from their counterparts~\eqref{e:AnsatzL2},~\eqref{e:AnsatzH1},~\eqref{e:AnsatzH1fe},~\eqref{e:AnsatzH1+gamma} in Proposition~\ref{p:GenericAnsatz} (using in particular the trivial bound $1 \lesssim \tilde \Upsilon^\theta \lesssim \tilde \Upsilon^1$). We turn to the proof of~\eqref{e:GenAnsatzA+bis}: we first rearrange its left hand side by the triangle inequality, as follows
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, &(\mu - {\mathfrak L}_0)^{-1/2} \, (\bar {\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp \phi) + {\mathfrak A}_+ \phi - {\mathfrak L}_0^\mathfrak{e}\big[\Upsilon\big]_\mu)\| \\
&\leq \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, \big((\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak A}_+ \phi) - {\mathfrak A}_+^\sharp \phi + {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp \phi\big)\| \\
&\quad + \mu^{-1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp \phi)\| + \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, {\mathfrak A}_+^\flat \phi\| \\
&\quad + \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, ({\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp - {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu) \, \phi\| \, .
\end{equs}
Now we can bound the first term by using~\eqref{e:AnsatzGen} (with $\bm \varphi = {\mathfrak A}_+^\sharp \varphi$) together with~\eqref{e:BoundK1feA+}, the second term by using~\eqref{e:AnsatzA+L2bis}, the third term by using~\eqref{e:Aflat} (which clearly holds with extra ${\mathfrak N}_*^\kappa \alpha^{\mathfrak N}$ on both sides up to paying a multiplicative cost $\lesssim_{\alpha, \kappa}$, because ${\mathfrak A}_+^\flat$ increases the number operator ${\mathfrak N}$ by $1$), and the fourth term by the first replacement lemma~\eqref{e:ReplFixPt} (and by noticing that ${\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp - {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu$ preserves the number operator ${\mathfrak N}$). Thus, we deduce
\begin{equs}
\|&{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_0)^{-1/2} \, (\bar {\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp \phi) + {\mathfrak A}_+ \phi - {\mathfrak L}_0^\mathfrak{e}\big[\Upsilon\big]_\mu)\| \\
&\lesssim \|{\mathfrak N}_{*}^{\kappa} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| + \|{\mathfrak N}_{*}^{\kappa} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| + \|{\mathfrak N}_{*}^{\kappa+1} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| + \|{\mathfrak N}_{*}^{\kappa} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, \\
&\lesssim \|{\mathfrak N}_{*}^{\kappa+1} \alpha^{\mathfrak N} (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \phi\| \, ,
\end{equs}
which proves~\eqref{e:GenAnsatzA+bis} and concludes the proof.

Let us first state a simple estimate that we shall use repeatedly in the paper: for any $a, b \geq 0$, $\tau \geq 1$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$,
\begin{equ}
\|(- {\mathfrak L}_0)^{a} (- {\mathfrak L}_0^\mathfrak{e})^{b} \, {\mathfrak U}_t^\tau \phi\| \leq \tau^{- a - b} \, \log_{*}(\tau)^{-b/3} \, \|(- {\mathfrak L}_0)^{a+b} \phi\| \, , \label{e:HsUtau}
\end{equ}
and also, for any $\theta \in [0,1]$ and $\mu > 0$ such that $\mu \tau \geq 1$,
\begin{equ}
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, {\mathfrak U}_t^\tau \varphi\| \lesssim \tau^{-1/2} \log_{*}(\tau)^{-(1-\theta)/3} \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \varphi\| \, . \label{e:H1fethetaUtau}
\end{equ}
Obviously,~\eqref{e:HsUtau} and~\eqref{e:H1fethetaUtau} still hold if we add an extra factor ${\mathfrak N}_*^\kappa \alpha^{\mathfrak N}$ on both sides. These two bounds easily follow from Definition~\ref{def:Utau} and the trivial estimates
\begin{equs}
|\mathfrak{e} \cdot (\Sigma^\tau)^{-1} \, k_{1:n}|^2 &= \tau^{-1} \log_{*}(\tau)^{-2/3} \, |\mathfrak{e} \cdot k_{1:n}|^2 \, , \\
|(\Sigma^\tau)^{-1} k_{1:n}|^2 &\leq \tau^{-1} \, |k_{1:n}|^2 \, , \\
\tilde \Upsilon^\theta(\mathrm{Log}(\mu + |p_{1:n}|^2/2)) &\lesssim \log_*(\tau)^{2 \theta/3} \, ,
\end{equs}
where, for the last bound, we used that $\mu + |p_{1:n}|^2/2 \geq 1/\tau$ and the trivial bound $\tilde \Upsilon^\theta(\mathrm{Log}(\cdot)) \lesssim \log_*(1/\cdot)^{2 \theta/3}$ (recall~\eqref{e:Upstheta},~\eqref{e:ODEexplicit}, and $\mathrm{Log}(\cdot) = \log(1/\cdot) \, \1_{0 < \cdot \leq 1}$).
\smallskip

By using~\eqref{e:HsUtau} and~\eqref{e:H1fethetaUtau}, the estimates~\eqref{e:AnsatzA+L2},~\eqref{e:AnsatzA+H1},~\eqref{e:AnsatzA+H1fe},~\eqref{e:AnsatzA+H1+gamma} readily follows from their counterpart~\eqref{e:AnsatzA+L2bis},~\eqref{e:AnsatzA+H1bis},~\eqref{e:AnsatzA+H1febis},~\eqref{e:AnsatzA+H1gammabis} in Lemma~\ref{lem:AnsatzA+bis} (with $\theta$ therein chosen as $1/2 + 3 \varepsilon \in (1/2, 1)$).

We turn to the proof of~\eqref{e:AnsatzA+Gen}. We first observe that ${\mathfrak A}_0$ commutes with ${\mathfrak A}_+^\sharp$ and $\mathfrak{Ans}_{\mu}$ (which is clear from Remark~\ref{rmk:fA0} and formulas~\eqref{e:fA+Sharp},~\eqref{e:TrueAnsatz}). By recalling that $(\partial_t + \tau {\mathfrak A}_0) \, {\mathfrak U}_t^\tau = 0$ (cf. Remark~\ref{rmk:GalileanTransform}), we deduce
\begin{equ} \label{e:GalileanCancellation}
(\partial_t + \tau {\mathfrak A}_0) \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) = \mathfrak{Ans}_\mu\big({\mathfrak A}_+^\sharp \, (\partial_t + \tau {\mathfrak A}_0) \, {\mathfrak U}_t^\tau \varphi\big) = 0 \, ,
\end{equ}
and, equivalently: $(\partial_t + \tau {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) = \tau \bar {\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)$. We also observe that Definition~\ref{def:Utau} readily implies: ${\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} = \tau \log_*(\tau)^{2/3} \, {\mathfrak L}_0^\mathfrak{e} \, {\mathfrak U}_t^\tau$. Consequently, we deduce
\begin{equs}
\Big\|&{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (\mu \tau - \tau {\mathfrak L}_0)^{-1/2} \, \Big((\partial_t + \tau {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) + \tau {\mathfrak A}_+ {\mathfrak U}_t^\tau \varphi - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big)\Big\| \\
&\leq \tau^{1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_0)^{-1/2} \, (\bar {\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) + {\mathfrak A}_+ {\mathfrak U}_t^\tau \varphi - {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu \, {\mathfrak U}_t^\tau\varphi)\| \\
&\quad + \tau^{1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, ({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu - d^{\lim} \log_{*}(1/\mu)^{2/3} {\mathfrak L}_0^\mathfrak{e}) \, {\mathfrak U}_t^\tau \varphi\| \, \\
&\lesssim \log(\tau)^{-1/6 + \varepsilon} \, C_{\alpha, \kappa + 1}^{1/2}(\varphi) + \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- \tau {\mathfrak L}_0)^{-1/2} \, ({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu - d^{\lim} \log_{*}(1/\mu)^{2/3} {\mathfrak L}_0^\mathfrak{e}) \, {\mathfrak U}_t^\tau \varphi\| , \label{e:AnsatzA+GenProof}
\end{equs}
where in the last bound we used~\eqref{e:GenAnsatzA+bis} (with $\theta = 1/2 + 3 \varepsilon$) together with~\eqref{e:HsUtau}. It only remains to estimate the last term. First, we observe that for any $k_{1:n} \in \mathbb{R}^{2n}$ we have
\begin{equ}
|\mathrm{Log}(\mu + |k_{1:n}|^2/2) - \log_{*}(1/\mu)| \lesssim 1 + \log(1 + \mu^{-1} \, |k_{1:n}|^2/2) \lesssim 1 + \mu^{-1/2} \, |k_{1:n}| \, .
\end{equ}
Then, we use~\eqref{e:AsymptoticUps} (and the trivial bound $|a^{2/3} - b^{2/3}| \lesssim 1 + |a - b|$) and deduce
\begin{equ} \label{e:gnewglim}
|\Upsilon(\mathrm{Log}(\mu + |k_{1:n}|^2/2)) - d^{\lim} \log_{*}(1/\mu)^{2/3}| \lesssim 1 + \mu^{-1/2} \, |k_{1:n}| \leq 1 + \tau^{1/2} \, |k_{1:n}| \, ,
\end{equ}
where in the last bound we used that $\mu \tau \geq 1$. By combining~\eqref{e:gnewglim} and~\eqref{e:HsUtau}, we obtain
\begin{equs}
\tau^{1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, &(- {\mathfrak L}_0)^{-1/2} \, ({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu - d^{\lim} \log_{*}(1/\mu)^{2/3} {\mathfrak L}_0^\mathfrak{e}) \, {\mathfrak U}_t^\tau \varphi\| \\
&\lesssim \tau^{1/2} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, {\mathfrak U}_t^\tau \varphi\| + \tau \,  \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} (- {\mathfrak L}_0)^{1/2} \, {\mathfrak U}_t^\tau \varphi\| \\
&\lesssim \log(\tau)^{-1/6} \, C_{\alpha, \kappa}^1(\varphi) \, . \label{e:LnewLlim}
\end{equs}
Plugging this bound in~\eqref{e:AnsatzA+GenProof} gives the desired estimate~\eqref{e:AnsatzA+Gen} and concludes the proof.

\label{def:AnsatzA+ASEP}
For any $\tau \geq 1$, $\mu > 0$ with $\mu \tau \geq 1$, and $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ we set
\begin{equ} \label{e:AnsatzA+ASEP}
\mathrm{Cor}^{\tau, \mu}_{t}(\varphi) \stackrel{\mbox{\tiny\rm def}}{=} \mathsf{R} \mathsf{P} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) \, .
\end{equ}

\label{p:AnsatzA+ASEP}
Let $\tau \geq 1$ and $\mu > 0$ such that $\mu \tau \geq 1$, and let $\varepsilon \in (0,1/6)$, $\alpha \in [1, \sqrt{1 + 6 \varepsilon})$, $\kappa \geq 0$. Then it holds
\begin{equs}
\sqrt{\mu \tau} \, \|N_{*}^\kappa \alpha^N \, \mathrm{Cor}^{\tau, \mu}_{t}(\varphi)\| &\lesssim_{\alpha, \kappa} \log_{*}(\tau)^{-1/3} \, C_{\alpha, \kappa}^{1/2}(\varphi) \, , \label{e:AnsatzA+L2ASEP} \\
\|N_{*}^\kappa \alpha^N \, (- \tau S)^{1/2} \, \mathrm{Cor}^{\tau, \mu}_{t}(\varphi)\| &\lesssim_{\alpha, \kappa} C_{\alpha, \kappa}^{1/2}(\varphi) \, , \label{e:AnsatzA+H1ASEP} \\
\Big\|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \Big(\tau A_+ \mathsf{i}_t^\tau
\varphi + (\partial_t + \tau L) \, &\mathrm{Cor}^{\tau, \mu}_{t}(\varphi) - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, \mathsf{i}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big)\Big\| \\
&\lesssim_{\alpha, \kappa, \varepsilon} \log_{*}(\tau)^{-1/6 + \varepsilon} \, C_{\alpha, \kappa+6}^{3/2}(\varphi) \, , \label{e:AnsatzA+GenASEP}
\end{equs}
where $\mathsf{i}_t^\tau$ is defined in~\eqref{e:fsittau}, and the constants $C^s_{\alpha, \kappa}(\varphi)$ are given by~\eqref{e:Cvphi}.

We first comment that, by orthogonality of chaoses, the estimates of Lemma~\ref{lem:BoundR}, Lemma~\ref{lem:BoundQ}, Lemma~\ref{lem:BoundP}, and~\eqref{e:HsUtau} remain valid if we add an extra factor $N_{*}^\kappa \alpha^N$, $\mathcal{N}_{*}^\kappa \alpha^\mathcal{N}$ or ${\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N}$ (depending on the context) on both sides of the inequalities. Furthermore, the same holds for Theorem~\ref{th:ComparisonGen}, up to paying an extra multiplicative cost only depending on $\alpha$ and $\kappa$ (because $(n \pm 1)_*^\kappa \alpha^{n \pm 1} \lesssim_{\kappa, \alpha} n_{*}^\kappa \alpha^n)$. For the upcoming estimates, it is useful to choose any $\gamma \in (0,1)$ that we fix for the rest of the proof.
\smallskip

We start with the proof of~\eqref{e:AnsatzA+L2ASEP} and~\eqref{e:AnsatzA+H1ASEP}. By first using~\eqref{e:BoundR} and~\eqref{e:BoundP}, and then applying~\eqref{e:AnsatzA+L2} and~\eqref{e:AnsatzA+H1}, we readily deduce
\begin{equs}
\sqrt{\mu \tau} \, \|N_{*}^\kappa \alpha^N \, \mathrm{Cor}^{\tau, \mu}_t(\varphi)\| &\lesssim \sqrt{\mu \tau} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| \lesssim \log_{*}(\tau)^{-1/3} \, C_{\alpha, \kappa}^{1/2}(\varphi) \, , \\
\|N_{*}^\kappa \alpha^N \, (- \tau S)^{1/2} \, \mathrm{Cor}^{\mu, \tau}_t(\varphi)\| &\lesssim \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (- \tau {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| \lesssim C_{\alpha, \kappa}^{1/2}(\varphi) \, ,
\end{equs}
which proves the two desired estimates.
\smallskip

We turn to the proof of~\eqref{e:AnsatzA+GenASEP}. We can rearrange its left hand side by the triangle inequality, as follows
\begin{equs}
\Big\|&N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \Big(\tau A_+ \mathsf{i}_t^\tau
\varphi + (\partial_t + \tau L) \, \mathrm{Cor}^{\tau, \mu}_{t}(\varphi) - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, \mathsf{i}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big)\Big\| \\
&\leq \Big\|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, \mathsf{Q}^* \mathsf{P} \Big(\tau {\mathfrak A}_+ {\mathfrak U}_t^\tau \varphi + (\partial_t + \tau {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi) - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big)\Big\| \\
&\qquad + \|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, (\tau A_+ \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak A}_+) \, {\mathfrak U}_t^\tau \varphi\| \\
&\qquad + \|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, (\mathsf{R} - \mathsf{Q}^*) \, \mathsf{P} \, \partial_t \,  \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| \\
&\qquad + \|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, (\tau L \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| \\
&\qquad + \frac{d^{\lim} \log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, \|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, (\mathsf{R} - \mathsf{Q}^*) \mathsf{P} \, {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\| \\
&=: \mathrm{(I)} + \mathrm{(II)} + \mathrm{(III)} + \mathrm{(IV)} + \mathrm{(V)} \, . \label{e:AnsatzA+ASEP0}
\end{equs}

For the first summand, we use~\eqref{e:BoundQ*},~\eqref{e:BoundP} and~\eqref{e:AnsatzA+Gen}, which results in
\begin{equ}
\mathrm{(I)} \lesssim_{\alpha, \kappa, \varepsilon} \|{\mathfrak N}_{*}^{\kappa + 3} \alpha^{\mathfrak N} \, (\mu \tau - \tau {\mathfrak L}_0)^{-1/2} \, (...)\| \lesssim \log_{*}(\tau)^{-1/6+\varepsilon} \, C_{\alpha, \kappa + 4}^{1}(\varphi) \, , \label{e:AnsatzA+ASEP1}
\end{equ}
where $(...)$ stands for the expression inside the large parenthesis in the definition of $\mathrm{(I)}$.

For the second summand, we use Theorem~\ref{th:ComparisonGen} and~\eqref{e:HsUtau}, which gives
\begin{equs}
\mathrm{(II)} &\lesssim_{\gamma} \tau^{1/2} \, \|{\mathfrak N}_{*}^{\kappa + 6} \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, {\mathfrak U}_t^\tau \varphi\| + \tau^{1/2} \, \|{\mathfrak N}_{*}^{\kappa + 6} \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, {\mathfrak U}_t^\tau \varphi\| \\
&\lesssim \tau^{- \gamma/2} \, C_{\alpha, \kappa + 6}^{(1+\gamma)/2}(\varphi) + \log_{*}(\tau)^{-1/3} \, C_{\alpha, \kappa + 6}^{1/2}(\varphi) \, . \label{e:AnsatzA+ASEP2}
\end{equs}

For the third summand, we first observe that $\partial_t \, {\mathfrak U}_t^\tau = - \tau {\mathfrak A}_0 \, {\mathfrak U}_t^\tau = - \tau^{1/2} \log_{*}(\tau)^{-1/3} \, {\mathfrak U}_t^\tau \, {\mathfrak A}_0$ (recall Definition~\ref{def:Utau} and~\eqref{e:fA0}). We then deduce
\begin{equs}
\mathrm{(III)} &= \tau^{1/2} \log_{*}(\tau)^{-1/3} \, \|N_{*}^\kappa \alpha^N (\mu \tau - \tau S)^{-1/2} \, (\mathsf{R} - \mathsf{Q}^*) \, \mathsf{P} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau {\mathfrak A}_0 \varphi)\| \\
&\lesssim \tau^{1/2} \log_{*}(\tau)^{-1/3} \times \log_{*}(1/\mu) \, \tau^{-1} \|{\mathfrak N}_{*}^{\kappa+2} \alpha^{\mathfrak N} (\mu \tau - \tau {\mathfrak L}_0)^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau {\mathfrak A}_0 \varphi)\| \\
&\lesssim_{\alpha, \kappa} \tau^{-1/2} \log_{*}(\tau)^{2/3} \, C_{\alpha, \kappa + 2}^1({\mathfrak A}_0 \varphi) \\
&\lesssim \tau^{-1/2} \log_{*}(\tau)^{2/3} \, C_{\alpha, \kappa + 5/2}^{3/2}(\varphi) \, , \label{e:AnsatzA+ASEP3}
\end{equs}
where in the first bound we used~\eqref{e:RemovalQ*R} and~\eqref{e:BoundP}, in the second bound we used~\eqref{e:AnsatzA+L2} and~\eqref{e:AnsatzA+H1} (and $\mu \tau \geq 1$), and in the third bound we used the trivial bound $|v \cdot (k_1 + \dots + k_n)| \lesssim \sqrt{n} \, |k_{1:n}|$ due to the Cauchy-Schwarz inequality. 

For the fourth summand, we first apply Theorem~\ref{th:ComparisonGen} and then use~\eqref{e:AnsatzA+H1+gamma} and~\eqref{e:AnsatzA+H1fe}, which leads to
\begin{equs}
\mathrm{(IV)} &\lesssim_{\gamma} \tau^{1/2} \, \|{\mathfrak N}_{*}^{\kappa + 6} \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| + \tau^{1/2} \, \|{\mathfrak N}_{*}^{\kappa + 6} \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak A}_+^\sharp {\mathfrak U}_t^\tau \varphi)\| \\
&\lesssim_{\alpha, \kappa, \varepsilon} \tau^{- \gamma/2} \, C_{\alpha, \kappa + 6}^{(1+\gamma)/2}(\varphi) + \log_{*}(\tau)^{-1/6 + \varepsilon} \, C_{\alpha, \kappa + 6}^{1}(\varphi) \, . \label{e:AnsatzA+ASEP4}
\end{equs}

For the fifth summand, we use $\mu \tau \geq1$,~\eqref{e:RemovalQ*R},~\eqref{e:BoundP} and~\eqref{e:HsUtau}, which gives
\begin{equs}
\mathrm{(V)} &\lesssim \|N_{*}^\kappa \alpha^N (1 - \tau S)^{-1/2} \, (\mathsf{R} - \mathsf{Q}^*) \mathsf{P} \, {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\| \\
&\lesssim \tau^{-1} \log_{*}(\tau) \, \|{\mathfrak N}_{*}^{\kappa+2} \alpha^{\mathfrak N} \, (1 - \tau {\mathfrak L}_0)^{1/2} {\mathfrak U}_t^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\| \\
&\lesssim \tau^{-1} \log_{*}(\tau) \,  C_{\alpha, \kappa + 2}^{1/2}({\mathfrak L}_0^\mathfrak{e} \varphi) \\
&\leq \tau^{-1} \log_{*}(\tau) \, C_{\alpha, \kappa + 2}^{3/2}(\varphi) \, . \label{e:AnsatzA+ASEP5}
\end{equs}

We can finally gather~\eqref{e:AnsatzA+ASEP0},~\eqref{e:AnsatzA+ASEP1},~\eqref{e:AnsatzA+ASEP2},~\eqref{e:AnsatzA+ASEP3},~\eqref{e:AnsatzA+ASEP4},~\eqref{e:AnsatzA+ASEP5} and deduce the estimate~\eqref{e:AnsatzA+GenASEP}, which concludes the proof.

\label{p:AnsatzDiff}
Let $\mu > 0$, $\delta \in (0,1]$, $\varepsilon \in (0,1/6)$, $\alpha \in [1, \sqrt{1 + 6 \varepsilon})$, and $\gamma \in (0,1]$. Then it holds
\begin{equs}
\sqrt{\mu} \, \|\alpha^{\mathfrak N} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| &\lesssim_\alpha 1 \, , \label{e:AnsatzDiffL2} \\
\|\alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| &\lesssim_{\alpha, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, , \label{e:AnsatzDiffH1fe} \\
\|\alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| &\lesssim_{\alpha, \varepsilon, \gamma} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, ,
\label{e:AnsatzDiffH1+gamma} \\
\limsup_{\delta \to 0} \big\|\alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_0)^{-1/2} \, \big({\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta) + {\mathfrak B}_+ &\mathcal{V}^\delta\big)\big\| \lesssim_{\alpha, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, , \label{e:AnsatzDiffGen} \\
\limsup_{\delta \to 0} \big|\, 2 \, \|(- {\mathfrak S})^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 - d^{\lim} \log_{*}(1/&\mu)^{2/3}\big| \lesssim_{\varepsilon} \log_{*}(1/\mu)^{1/3 + 2 \varepsilon} \, .\label{e:AnsatzDiffH1}
\end{equs}

\label{def:AnsatzDiffASEP}
For every $\mu > 0$ and $\delta \in (0,1]$, we define
\begin{equ}
\mathrm{Cor}_{\mu, \delta}^{B+} \stackrel{\mbox{\tiny\rm def}}{=} \mathsf{R} \mathsf{P} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta) \, .
\end{equ}

\label{p:AnsatzDiffASEP}
In the notation of Definition~\ref{def:AnsatzDiffASEP}, let $\varepsilon \in (0,1/6)$ and $\alpha \in [1, \sqrt{1 + 6 \varepsilon})$. Then it holds
\begin{equs}
\sqrt{\mu} \, \|\alpha^N \, \mathrm{Cor}_{\mu, \delta}^{B+}\| &\lesssim_\alpha 1 \, , \label{e:AnsatzDiffL2ASEP} \\
\limsup_{\delta \to 0} \big\|\alpha^N (\mu - S)^{-1/2} \big(L \, \mathrm{Cor}_{\mu, \delta}^{B+} + B_+ \mathcal{V}^\delta_{|\mathbb{Z}^2}\big)\big\| &\lesssim_{\alpha, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, , \label{e:AnsatzDiffGenASEP} \\
\limsup_{\delta \to 0} \big|\, 2 \, \|(- S)^{1/2} \, \mathrm{Cor}_{\mu, \delta}^{B+}\|^2 - d^{\lim} \log_{*}(1/\mu)^{2/3}\big| &\lesssim_{\varepsilon} \log_{*}(1/\mu)^{1/3 + 2 \varepsilon} \, . \label{e:AnsatzDiffH1ASEP}
\end{equs}

For the upcoming estimates, it is useful to choose any $\gamma \in (0,1)$ and $\beta \in (\alpha, \sqrt{1 + 6 \varepsilon})$ that we fix for the proof.
\smallskip

First, since the bridges $\mathsf{R}$ and $\mathsf{P}$ trivially contract the $L^2$-norm $\|\cdot\|$ (and preserve the number operator), we readily deduce~\eqref{e:AnsatzDiffL2ASEP} from~\eqref{e:AnsatzDiffL2}.

Next, we turn to the estimate~\eqref{e:AnsatzDiffH1ASEP}. By using Lemma~\ref{lem:ComparisonH1} and the bound~\eqref{e:AnsatzDiffH1+gamma} (with any $\alpha \in (1, \sqrt{1 + 6 \varepsilon})$, so that we can crudely bound $n \lesssim_\alpha \alpha^n$), we deduce
\begin{equs}
\big|\|(- S)^{1/2} \, \mathrm{Cor}^{B+}_{\mu, \delta}\|^2 - \|(-{\mathfrak S})^{1/2} \,  \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\|^2\big| &\lesssim_\gamma \|{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 \\
&\lesssim_{\alpha, \varepsilon, \gamma} \log_{*}(1/\mu)^{1/3 + 2\varepsilon} \, .
\end{equs}
By combining this estimate with~\eqref{e:AnsatzDiffH1}, we readily deduce~\eqref{e:AnsatzDiffH1ASEP}.
\smallskip

Finally, we tackle~\eqref{e:AnsatzDiffGenASEP}. By the triangle inequality, we write
\begin{equs}
\big\|\alpha^N (\mu - S)^{-1/2} \big(L \, \mathrm{Cor}_{\mu, \delta}^{B+} + B_+ \mathcal{V}^\delta_{|\mathbb{Z}^2}\big)\big\| &\leq \|\alpha^N (\mu - S)^{-1/2} \, \mathsf{Q}^* \mathsf{P} \big({\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta) + {\mathfrak B}_+ \mathcal{V}^\delta\big)\| \\
&\quad + \|\alpha^N (\mu - S)^{-1/2} \big(L \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} {\mathfrak L}) \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| \\
&\quad + \|\alpha^N (\mu - S)^{-1/2} (B_+ \mathcal{V}^\delta_{|\mathbb{Z}^2} - \mathsf{Q}^* \mathsf{P} {\mathfrak B}_+ \mathcal{V}^\delta)\| \\
&=: \mathrm{(I)} + \mathrm{(II)} + \mathrm{(III)} \, . \label{e:AnsatzDiffGenASEP0}
\end{equs}

For the first summand, we use~\eqref{e:BoundQ*},~\eqref{e:BoundP}, and~\eqref{e:AnsatzDiffGen} (with $\beta$ instead of $\alpha$, so that we can crudely bound $n^3 \alpha^n \lesssim_{\alpha, \beta} \beta^n$), which gives
\begin{equ}
\limsup_{\delta \to 0} \mathrm{(I)} \lesssim \limsup_{\delta \to 0} \|{\mathfrak N}^3 \alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_0)^{-1/2} \big({\mathfrak L} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta) + {\mathfrak B}_+ \mathcal{V}^\delta\big)\| \lesssim_{\alpha, \beta, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, .  \label{e:AnsatzDiffGenASEP1}
\end{equ}

For the second summand, we use Theorem~\ref{th:ComparisonGen},~\eqref{e:AnsatzDiffH1+gamma} and~\eqref{e:AnsatzDiffH1fe} (with $\beta$ instead of $\alpha$, so that we can bound $n^6 \alpha^n \lesssim_{\alpha, \beta} \beta^n$), which results in
\begin{equs}
\mathrm{(II)} &\lesssim \|{\mathfrak N}^6 \alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{(1+\gamma)/2} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| + \|{\mathfrak N}^6 \alpha^{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_\mu({\mathfrak B}_+ \mathcal{V}^\delta)\| \\
&\lesssim_{\alpha, \beta, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} \, . \label{e:AnsatzDiffGenASEP2}
\end{equs}

For the third summand, we first notice that $B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta = \mathsf{Q}^* B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta$ because $B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma \ell^2_{}
    \else
        \Gamma h^{}_{}
    \fi
$. Then we use~\eqref{e:BoundQ} (and note that the number operator simply contributes here as $2$) to deduce
\begin{equ}
\mathrm{(III)} = \alpha^2 \, \|(\mu - S)^{-1/2} \, \mathsf{Q}^* (B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta -\mathsf{P} {\mathfrak B}_+ \mathcal{V}^\delta)\| \lesssim \|(\mu - \mathcal{S})^{-1/2} \, (B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta - \mathsf{P}  {\mathfrak B}_+ \mathcal{V}^\delta)\| \, . \label{e:AnsatzDiffGenASEP3}
\end{equ}
Now, we claim that the last term can be bounded as
\begin{equ} \label{e:B+Replacement}
\|(- \mathcal{S})^{-1/2} \, (B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta - \mathsf{P}  {\mathfrak B}_+ \mathcal{V}^\delta)\| \lesssim 1 \, .
\end{equ}
Then, by gathering~\eqref{e:AnsatzDiffGenASEP0},~\eqref{e:AnsatzDiffGenASEP1},~\eqref{e:AnsatzDiffGenASEP2},~\eqref{e:AnsatzDiffGenASEP3}, and the claim~\eqref{e:B+Replacement}, we deduce the desired estimate~\eqref{e:AnsatzDiffGenASEP}.
\smallskip

Consequently, it only remains to show the claim~\eqref{e:B+Replacement}. Let us first compute the Fourier transforms of the functionals $\mathsf{P} {\mathfrak B}_+ \mathcal{V}^\delta$ and $B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta$. For the first functional, we deduce from the definition~\eqref{e:fB+} of ${\mathfrak B}_+$ that, for any $p, q \in (- \pi, \pi)^2$, we have
\begin{equ} \label{e:FourierfB+}
\mathcal{F}(\mathsf{P} {\mathfrak B}_+ \mathcal{V}^\delta) \, (p,q) = \frac{\sqrt{\varrho(1 - \varrho)}}{2 \pi} \, \lambda \, \Pi_{p, q} \ {\mathfrak F} \mathcal{V}^\delta (\llbracket p+q \rrbracket) \, .
\end{equ}
As for the second functional, an easy computation starting from the definition~\eqref{e:B+} of $B_+$ shows that
\begin{equ} \label{e:FourierB+}
\mathcal{F}(B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta) \, (p,q) = \frac{\sqrt{\varrho(1 - \varrho)}}{2 \pi} \, \frac{\lambda(p) + \lambda(q)}{2} \, \mathcal{F} (\mathcal{V}_{|\mathbb{Z}^2}^\delta) (p+q) \, ,
\end{equ}
where we have defined, for any $k \in \mathbb{T}^2$,
\begin{equ} \label{e:LambdaTrigo}
\lambda(k) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{z \in \mathbb{Z}^2} a(z) \, (\mathfrak{e} \cdot z) \, \cos(z \cdot k) \, .
\end{equ}
Furthermore, since ${\mathfrak F} \mathcal{V}^\delta$ is supported on $(- \pi, \pi)^2$ (by the assumption on $\mathcal{V}$, cf. Definition~\ref{def:V}), the Poisson summation formula~\eqref{e:PoissonSummation} shows that, for any $k \in \mathbb{T}^2$, we have $\mathcal{F}(\mathcal{V}_{|\mathbb{Z}^2}^\delta) \, (k) = {\mathfrak F} \mathcal{V}^\delta \, (\llbracket k \rrbracket)$. Hence, it holds
\begin{equ} \label{e:FourierB+Bis}
\mathcal{F}(B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta) \, (p,q) = \frac{\sqrt{\varrho(1 - \varrho)}}{2 \pi} \, \frac{\lambda(p) + \lambda(q)}{2} \, {\mathfrak F} \mathcal{V}^\delta (\llbracket p+q \rrbracket) \, .
\end{equ}
Now we compare~\eqref{e:FourierfB+} and~\eqref{e:FourierB+}. On the one hand, from the Taylor estimate $|\cos(\theta) - 1| \lesssim \theta^2$ we deduce that, for any $k \in \mathbb{R}^2$,
\begin{equ}
|\lambda(k) - \lambda| \leq \sum_{z \in \mathbb{Z}^2} |a(z)| \, |\mathfrak{e} \cdot z| \, |\cos(z \cdot k) - 1| \lesssim |k|^2 \, .
\end{equ}
On the other hand, we can trivially bound $|\Pi_{p,q} - 1| \lesssim |p|^2 + |q|^2$ for any $p, q \in \mathbb{R}^2$. Consequently, we deduce for every $p, q \in (- \pi, \pi)^2$
\begin{equ}
|\mathcal{F}(B_+ \mathcal{V}_{|\mathbb{Z}^2}^\delta - \mathsf{P} {\mathfrak B}_+ \mathcal{V}^\delta) \, (p,q)| \lesssim (|p|^2 + |q|^2) \ |{\mathfrak F} \mathcal{V}^\delta \, (\llbracket p+q \rrbracket)| \, .
\end{equ}
Then, by squaring, dividing by $d_0(p,q) \asymp |p|^2 + |q|^2$ (recall~\eqref{e:d0D0equivalence}), integrating over $p, q \in (- \pi, \pi)^2$ and recalling that $\|\mathcal{V}^\delta\|_{L^2(\mathbb{R}^2)}^2 = 1$, we deduce the desired claim~\eqref{e:B+Replacement} and conclude the proof.

\label{def:MI}
Let $\tau \geq 1$ and $T > 0$. For any $f = (f_t)_{t \in [0,T]} \in C^1([0, T], 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
)$ and $g = (g_t)_{t \in [0,T]} \in C([0, T], 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{{\mathrm{rap}}}
    \else
        \Gamma_0 h^{}_{{\mathrm{rap}}}
    \fi
)$, we define the processes $(M_t^\tau(f))_{t \in [0,T]}$ and $(W_t^\tau(g))_{t \in [0,T]}$ on $(\bm{\Omega}, \mathbf P_{\nu_\varrho})$ as follows
\begin{equ} \label{e:DefMI}
M_t^\tau(f) \stackrel{\mbox{\tiny\rm def}}{=} f_t(\eta_{\tau t}) - f_0(\eta_0) - \int_0^t (\partial_r + \tau L) f_{r} \, (\eta_{\tau r}) \ \mathrm{d} r \, , \quad W_t^\tau(g) \stackrel{\mbox{\tiny\rm def}}{=} \int_0^t g_r(\eta_{\tau r}) \, \mathrm{d} r \, .
\end{equ}
It is classical that $(M_\cdot^\tau(f))_{t \geq 0}$ is a càdlàg $(\mathcal{F}_{\tau t})_{t \geq 0}$-martingale and that $(W_t^\tau(g))_{t \geq 0}$ is a continuous $(\mathcal{F}_{\tau t})_{t \geq 0}$-adapted finite-variation process.
For $0 \leq s \leq t \leq T$, we set $M_{s, t}^\tau(f) := M_t^\tau(f) - M_s^\tau(f)$ and $W_{s,t}^\tau(g) := W_t^\tau(g) - W_s^\tau(g)$.
When $\tau = 1$ we omit the superscript $\tau$ in the previous notations; let us notice that $M_t^\tau(f_\cdot) = M_{\tau t}(f_{\cdot/\tau})$ and $W_t^\tau(g_\cdot) = \tau^{-1} \, W_{\tau t}(g_{\cdot/\tau})$.

\label{lem:MIL2}
In the notation of Definition~\ref{def:MI}, for every $0 \leq s < t \leq T$, we have
\begin{equs}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |M_{a,b}^\tau(f)|^2\Big] &\lesssim |t-s| \sup_{r \in [0,T]} \|(- \tau S)^{1/2} f_r\|^2 \label{e:ML2} \\
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |W^\tau_{a,b}(f)|^2\Big] &\lesssim |t-s| \sup_{r \in [0,T]} \|(|t-s|^{-1} - \tau S)^{-1/2} f_r\|^2 \, . \label{e:IL2}
\end{equs}

\label{p:TightnessBlackBox}
Let $(\alpha(p))_{p > 2}$ be the family of constants from Lemma~\ref{lem:UltimateHypercontractivity} (which, in particular, satisfy $\alpha(p) \to 1$ as $p \to 2$). We use the notations of Definition~\ref{def:MI}, and let $p > 2$. For every $0 \leq s < t \leq T$, we have
\begin{equs}
\label{e:KolmogorovM}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |M_{a,b}^\tau(f)|^p\Big] &\lesssim_p |t-s|^{p/2} \sup_{r \in [0,T]} \|\alpha(p)^N \, (|t-s|^{-1} - \tau S)^{1/2} f_r\|^p \, , \\
\label{e:KolmogorovI}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |W_{a,b}^\tau(g)|^p\Big] &\lesssim_p |t-s|^{p/2} \sup_{r \in [0,T]} \|\alpha(p)^N \, (|t-s|^{-1} - \tau S)^{-1/2} g_r\|^p \, .
\end{equs}
Moreover, for any $\delta > 0$ and $(\mathcal{F}_{\tau t})_{t \geq 0}$-stopping times $\rm T_1, \rm T_2$ taking values in $[0, T]$ such that $\rm T_1 \leq \rm T_2 \leq \rm T_1 + \delta$, we have
\begin{equ}
\label{e:AldousM}
\mathbf E_{\nu_\varrho}\Big[|M_{\rm T_1, \rm T_2}^\tau(f)|^2\Big] \lesssim_p \delta^{1 - \frac{2}{p}} \, T^{\frac{2}{p}} \sup_{r \in [0, T]} \|\alpha(p)^N \, (- \tau S)^{1/2} f_r\|^2 \, .
\end{equ}

First, it is easily checked that the statement for general $\tau \geq 1$ can be deduced from the one with $\tau = 1$ by using the scaling relations $M_{s,t}^\tau(f) = M_{\tau s, \tau t}(f_{\cdot/\tau})$ and $W^\tau_{s,t}(g) = \tau^{-1} \, W_{\tau s, \tau t}(g_{\cdot/\tau})$. Consequently, we assume $\tau = 1$.

Second, an easy approximation argument shows that it is sufficient to prove the statement for smooth local paths $f$ and $g$ (that is to say functionals of the form $[0,T] \times \Omega \ni (t, \eta) \mapsto h(t, \mathchoice
              {\setbox1\hbox{${\displaystyle \eta}_{\scriptstyle \Lambda}$}
              {\eta\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\Lambda}}
              {\setbox1\hbox{${\textstyle \eta}_{\scriptstyle \Lambda}$}
              {\eta\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\Lambda}}
              {\setbox1\hbox{${\scriptstyle \eta}_{\scriptscriptstyle \Lambda}$}
              {\eta\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\Lambda}}
              {\setbox1\hbox{${\scriptscriptstyle \eta}_{\scriptscriptstyle \Lambda}$}
              {\eta\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\Lambda}})$ for some finite subset $\Lambda \subset \mathbb{Z}^2$ and smooth function $h \colon [0,T] \times \{0, 1\}^{\Lambda} \to \mathbb{R}$). This reduction allows us to avoid unnecessary technical difficulties.
\smallskip

Before delving into the proof, we first state a useful fact about $M_t(f)$. For $q \geq 2$, let us define the $q$-variation process as
\begin{equ} \label{e:pVariationMartingale}
V_t^{(q)}(f) := \sum_{0 < r \leq t} |M_r(f) - M_{r-}(f)|^q = \sum_{0 < r \leq t} |f_r(\eta_r) - f_r(\eta_{r-})|^q \, ,
\end{equ}
which generalises the quadratic variation $[M_t(f)] = V_t^{(2)}(f)$. We denote by $C^{(q)}_t(f)$ the compensator of $V_t^{(q)}(f)$, which generalises the predictable quadratic variation $\langle M(f) \rangle_t = C_t^{(2)}(f)$. Then, it is clear that
\begin{equ} \label{e:PredictablepVariationMartingale}
C_t^{(q)}(f) = \int_0^t \Gamma_q f_r(\eta_r) \, \mathrm{d} r \, ,
\end{equ}
where the ``puissance $q$ du champ'' $\Gamma_q \psi \colon \Omega \to \mathbb{R}_+$, for any local functional $\psi \colon \Omega \to \mathbb{R}$, is given by
\begin{equ} \label{e:PuissanceDuChamp}
\Gamma_q \psi \, (\eta) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{x, y \in \mathbb{Z}^2} r(y-x) \, \eta(x) (1 - \eta(y)) \, \big|\psi(\eta^{x,y}) - \psi(\eta)\big|^q \, .
\end{equ}
In particular, we recover the classical formula of $\langle M(f) \rangle_t$ in terms of the ``carré du champ''.
\smallskip

We start the proof of~\eqref{e:KolmogorovM}. By the BDG inequality, we know that
\begin{equ} \label{e:KolmogorovBDG}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |M_{a,b}(f)|^p\Big] \lesssim_p \mathbf E_{\nu_\varrho}\big[\big([M(f)]_t - [M(f)]_s\big)^{p/2}\big] \, .
\end{equ}
We emphasise that, because $p > 2$ and $M_\cdot(f)$ is not continuous, it is not possible to replace the quadratic variation $[M(f)]$ by its compensator $\langle M(f) \rangle$. However, we can use~\cite[Theorem 2.1]{GeneralisedBDG} and~\eqref{e:PredictablepVariationMartingale} to deduce
\begin{equs}
\mathbf E_{\nu_\varrho}\big[\big([M(f)]_t - [M(f)]_s\big)^{p/2}\big] &\lesssim_p \mathbf E_{\nu_\varrho}\big[\big(\langle M(f) \rangle_t - \langle M(f) \rangle_s\big)^{p/2}\big] + \mathbf E_{\nu_\varrho}[C_t^{(p)} - C_s^{(p)}] \, , \label{e:GeneralisedBDG} \\
&= \mathbf E_{\nu_\varrho}\Big[\Big(\int_s^t \Gamma_2 f_r(\eta_r) \, \mathrm{d} r\Big)^{p/2}\Big] + \mathbf E_{\nu_\varrho}\Big[\int_s^t \Gamma_p f_r(\eta_r) \, \mathrm{d} r\Big] \, ,
\end{equs}
Now, we first use Jensen's inequality and the $\nu_\varrho$-stationarity of the ASEP, and then we apply the hypercontractivity estimates~\eqref{e:UltHyperGamma2} and~\eqref{e:UltHyperGammap}, which lead to
\begin{equs}
\, &\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |M_{a,b}(f)|^p\Big] \lesssim_p |t-s|^{p/2} \sup_{r \in [0,T]} \nu_\varrho\big(|\Gamma_2 f_r|^{p/2}\big) + |t-s| \sup_{r \in [0,T]} \nu_\varrho\big(\Gamma_p f_r\big) \\
&\lesssim_p |t-s|^{p/2} \sup_{r \in [0,T]} \|\alpha(p)^N \, (-S)^{1/2} f_r\|^p + |t-s| \sup_{r \in [0,T]} \|\alpha(p)^N f_r\|^{p - 2} \|\alpha(p)^N \, (-S)^{1/2} f_r\|^2 \\
&\lesssim |t-s|^{p/2} \, \sup_{r \in [0,T]} \|\alpha(p)^N \, (|t-s|^{-1}-S)^{1/2} f_r\|^p \, ,  \label{e:KolmogorovMproof}
\end{equs}
where in the last line we used the trivial bounds $\|(- S)^{1/2} \cdot \| \leq \|(|t-s|^{-1} - S)^{1/2} \cdot\|$ and $\|\cdot\| \leq |t-s|^{1/2} \, \| (|t-s|^{-1} - S)^{1/2} \cdot\|$. This shows the desired estimate~\eqref{e:KolmogorovM}.
\smallskip

We now prove~\eqref{e:KolmogorovI}, which follows from~\eqref{e:KolmogorovM} and the Itô trick. More precisely, we first define $h = (|t-s|^{-1} - S)^{-1} \, g$ and we split
\begin{equ} \label{e:KolmogorovIdecomposition}
W_{a,b}(g) = |t-s|^{-1} W_{a,b}(h) + W_{a,b}(- S h) \, .
\end{equ}
To deal with the first summand of~\eqref{e:KolmogorovIdecomposition}, we crudely bound $|W_{a,b}(h)| \leq \int_s^t |h(\eta_r)| \, \mathrm{d} r$, use Jensen's inequality, the $\nu_\varrho$-stationarity of the process, and the hypercontractivity estimate~\eqref{e:UltHyper}, which gives
\begin{equ} \label{e:KolmogorovItrivial}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} \big||t-s|^{-1} W_{a,b}(h)\big|^p\Big] \leq \sup_{r \in [0,T]} \nu_\varrho(|h_r|^p) \leq \sup_{r \in [0,T]}  \|\alpha(p)^{N} h_r\|^p \, ,
\end{equ}
To deal with the second summand of~\eqref{e:KolmogorovIdecomposition}, we use the Itô trick by writing
\begin{equs}
W_{a,b}(- S h) &= \frac{1}{2} \, \big(M_{a,b}(h) + \tilde M_{a+,b+}(\tilde h)\big) \, , \label{e:ItoTrick} \\
\mbox{where } \tilde M_{a,b}(\tilde h) &\stackrel{\mbox{\tiny\rm def}}{=} \tilde h_{T-a}(\tilde \eta_{T-a}) - \tilde h_{T-b}(\tilde \eta_{T-b}) - \int_{T-b}^{T-a} (\partial_r + \tilde L) \, \tilde h_r \, (\tilde \eta_r) \, \mathrm{d} r \, ,
\end{equs}
and where we introduced the time-reversed path $\tilde h_t := h_{T-t}$, the time-reversed ASEP\relax{The time-reversal we consider is $\eta_{(T-t)-}$ rather than $\eta_{T-t}$ because we want to work with càdlàg processes.} $\tilde \eta_t := \eta_{(T-t)-}$ and the time-reversed generator $\tilde L := S - A$. Now, we recall the classical fact that the time-reversed ASEP $(\tilde \eta_r)_{r \in [0, T]}$ under $\mathbb P_{\nu_\varrho}(\mathrm{d} \eta_\cdot)$ has the same law as the $\nu_\varrho$-stationary skewed ASEP, that is, with jump rates $s(\cdot) - a(\cdot)$ and generator $\tilde L$. Thus, the process $(\tilde M_{a,b}(\tilde h))_{0 < a \leq b < T}$ has the same law as the process $(M_{T-b,T-a}(\tilde h))_{0 < a \leq b < T}$ related to the skewed ASEP. Obviously, the estimate~\eqref{e:KolmogorovM} also holds for the skewed ASEP (indeed, the right hand side of~\eqref{e:KolmogorovM} depends only on the symmetric part of the jump rates, which is unchanged). Thus, we deduce from~\eqref{e:ItoTrick} and~\eqref{e:KolmogorovM} that it holds
\begin{equs}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |W_{a,b}(- S h)|^p\Big] &= \mathbf E_{\nu_\varrho}\Big[\sup_{s < a \leq b < t} |W_{a,b}(- S h)|^p\Big] \\
&\lesssim_p \mathbf E_{\nu_\varrho}\Big[\sup_{s < a \leq b < t} |M_{a,b}(h)|^p\Big] + \mathbf E_{\nu_\varrho}\Big[\sup_{s < a \leq b < t} |\tilde M_{a,b}(\tilde h)|^p\Big] \\
&\lesssim_p |t-s|^{p/2} \sup_{r \in [0,T]} \|\alpha(p)^N \, (|t-s|^{-1}-S)^{1/2} h_r\|^p \, . \label{e:KolmogorovItoTrick}
\end{equs}
Gathering~\eqref{e:KolmogorovIdecomposition},~\eqref{e:KolmogorovItrivial},~\eqref{e:KolmogorovItoTrick}, and recalling that $h_r = (|t-s|^{-1} - S)^{-1} g_r$, we deduce
\begin{equ}
\mathbf E_{\nu_\varrho}\Big[\sup_{s \leq a \leq b \leq t} |W_{a,b}(g)|^p\Big] \lesssim_p |t-s|^{p/2} \sup_{r \in [s,t]} \|\alpha(p)^N \, (|t-s|^{-1} - S)^{-1/2} g_r\|^p \, ,
\end{equ}
which shows~\eqref{e:KolmogorovI}.
\smallskip

We finish with the proof of~\eqref{e:AldousM}. By using classical properties of martingales and stopping times, we deduce
\begin{equ}
\mathbf E_{\nu_\varrho}[M_{\rm T_1, \rm T_2}(f)^2] = \mathbf E_{\nu_\varrho}\big[\langle M(f) \rangle_{\rm T_2} - \langle M(f) \rangle_{\rm T_1}\big] = \mathbf E_{\nu_\varrho}\Big[\int_{\rm T_1}^{\rm T_2} \Gamma_2 f_r (\eta_r) \, \mathrm{d} r\Big] \, .
\end{equ}
By Hölder's inequality, we can deterministically bound the last integral (recall that $|\rm T_2 - \rm T_1| \leq \delta$) as
\begin{equ}
\int_{\rm T_1}^{\rm T_2} \Gamma_2 f_r (\eta_r) \, \mathrm{d} r \leq \delta^{1 - \frac{2}{p}} \, \Big(\int_0^T |\Gamma_2 f_r (\eta_r)|^{p/2} \, \mathrm{d} r\Big)^{2/p} \, .
\end{equ}
Then, by using Jensen's inequality, the $\nu_\varrho$-stationarity of the ASEP, and finally using the hypercontractivity estimate~\eqref{e:UltHyperGamma2}, we deduce
\begin{equ}
\mathbf E_{\nu_\varrho}[M_{\rm T_1, \rm T_2}(f)^2] \leq \delta^{1 - \frac{2}{p}} \, T^{\frac{2}{p}} \sup_{r \in [0,T]} \nu_\varrho(|\Gamma_2 f_r|^{p/2})^{2/p} \, \lesssim_p \delta^{1 - \frac{2}{p}} \, T^{\frac{2}{p}} \sup_{r \in [0, T]} \|\alpha^N \, (- \tau S)^{1/2} f_r\|^2 \, ,
\end{equ}
which shows~\eqref{e:AldousM} and concludes the proof.

\label{lem:SimpleGen}
Let $\tau \geq 1$, $t \geq 0$, $\alpha \geq 1$, $\kappa \geq 0$, $\gamma \in (0,1)$, and $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$. Then it holds
\begin{equs}
\|N_{*}^\kappa \alpha^N \, (1 - \tau S)^{1/2} \, \mathsf{i}_t^\tau \varphi\| &\lesssim_{\alpha, \kappa} C_{\alpha, \kappa}^{2}(\varphi) \, , \label{e:SimpleH1} \\
\|N_{*}^\kappa \alpha^N \, (1 - \tau S)^{-1/2} \, (\tau S \, \mathsf{i}_t^\tau \varphi - D_0[\mathfrak{f}, \mathfrak{f}] \, \mathsf{i}_t^\tau {\mathfrak L}_0^\mathfrak{f} \varphi)\| &\lesssim_{\alpha, \kappa} \log_{*}(\tau)^{-1/3} \, C_{\alpha, \kappa+6}^{2}(\varphi) \, , \label{e:SimpleS} \\
\|N_{*}^\kappa \alpha^N \, (1 - \tau S)^{-1/2} \ \tau A_- \, \mathsf{i}_t^\tau \varphi\| &\lesssim_{\alpha, \kappa} \log_{*}(\tau)^{-1/2} \, C_{\alpha, \kappa+6}^{2}(\varphi) \, , \label{e:SimpleA-} \\
\|N_{*}^\kappa \alpha^N \, (1 - \tau S)^{-1/2} \, (\partial_t + \tau A_0) \, \mathsf{i}_t^\tau \varphi\| &\lesssim_{\alpha, \kappa, \gamma} \tau^{- \gamma/2} \, C_{\alpha, \kappa+6}^{2}(\varphi) \, , \label{e:SimpleA0}
\end{equs}
where the constant $C_{\alpha, \kappa}^s(\varphi)$ is defined in~\eqref{e:Cvphi}.

By using the orthogonality of chaoses, it is sufficient to show the statement for every $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$ and $n \geq 1$. In addition, we can assume $\alpha = 1$ and $\kappa = 0$ up to dividing both sides by $n_{*}^\kappa \alpha^n$. Next, we recall the useful estimate~\eqref{e:HsUtau} and give another similar statement: for any $a, b \geq 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ}
\|(- {\mathfrak L}_0)^{a} (- {\mathfrak L}_0^\mathfrak{e})^{b} \, {\mathfrak A}_0 \, {\mathfrak U}_t^\tau \phi\| \lesssim \tau^{- a - b - 1/2} \, \log_{*}(\tau)^{-b/3} \, \|{\mathfrak N} \, (- {\mathfrak L}_0)^{a+b+1/2} \phi\| \, \label{e:SimpleHsA0}
\end{equ}
Indeed, it follows from the same proof as~\eqref{e:HsUtau} by noticing in addition the trivial bound
\begin{equ} \label{e:SimpleScalingA0}
|v \cdot (\Sigma^\tau)^{-1} (k_1 + ... + k_n)| = \tau^{-1/2} \log_{*}(\tau)^{-1/3} \, |v \cdot (k_1 + \dots + k_n)| \lesssim \tau^{-1/2} \log_{*}(\tau)^{-1/3} \, n \, |k_{1:n}| \, .
\end{equ}

We start with the proof of~\eqref{e:SimpleH1}. This is a straightforward consequence of~\eqref{e:BoundR},~\eqref{e:BoundP} and~\eqref{e:HsUtau}, as follows
\begin{equ}
\|(1 - \tau S)^{1/2} \, \mathsf{R} \mathsf{P} {\mathfrak U}_t^\tau \phi\| \lesssim \|(1 - \tau {\mathfrak L}_0)^{1/2} \, {\mathfrak U}^\tau \varphi\| \lesssim \|(- {\mathfrak L}_0)^{1/2} \varphi\| \, .
\end{equ}

We turn to~\eqref{e:SimpleS}. We decompose its left hand side as follows
\begin{equs}
\|(1 - \tau S)^{-1/2} \, (\tau S \, \mathsf{i}_t^\tau \varphi -  \mathsf{i}_t^\tau D_0[\mathfrak{f}, \mathfrak{f}] {\mathfrak L}_0^\mathfrak{f} \varphi)\| &\leq \|(- \tau S)^{-1/2} \, (\tau S \, \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak S}) {\mathfrak U}_t^\tau \varphi\| \\
&\quad + \|(- \tau S)^{-1/2} \, \mathsf{Q}^* \mathsf{P} (\tau {\mathfrak S} \, {\mathfrak U}_t^\tau \varphi - {\mathfrak U}_t^\tau D_0[\mathfrak{f}, \mathfrak{f}] {\mathfrak L}_0^\mathfrak{f} \varphi)\| \\
&\quad + \|(1 - \tau S)^{-1/2} \, (\mathsf{Q}^* - \mathsf{R}) \mathsf{P} \, {\mathfrak U}_t^\tau D_0[\mathfrak{f}, \mathfrak{f}] {\mathfrak L}_0^\mathfrak{f} \varphi\| \\
&=: \mathrm{(I)} + \mathrm{(II)} + \mathrm{(III)} \, ,
\end{equs}
and we bound individually each summand. For the first one, we use Theorem~\ref{th:ComparisonGen} and~\eqref{e:HsUtau}, which gives
\begin{equ} \label{e:SimpleS1}
\mathrm{(I)} \lesssim_\gamma n^6 \, \tau^{1/2} \, \|(- {\mathfrak L}_0)^{3/4} \, {\mathfrak U}^\tau \varphi\| \lesssim n^6 \, \tau^{-1/4} \, \|(- {\mathfrak L}_0)^{3/4} \varphi\| \, .
\end{equ}
For the second summand, we use~\eqref{e:BoundQ*},~\eqref{e:BoundP}, and deduce
\begin{equ} \label{e:SimpleS2}
\mathrm{(II)} \lesssim n^3 \, \|(- {\mathfrak L}_0)^{-1/2}(\tau {\mathfrak S} \, {\mathfrak U}_t^\tau \varphi - {\mathfrak U}_t^\tau D_0[\mathfrak{f}, \mathfrak{f}] {\mathfrak L}_0^\mathfrak{f} \varphi)\| \lesssim n^3 \log_{*}(\tau)^{-1/3} \, \|(-{\mathfrak L}_0)^{1/2} \varphi\| \, ,
\end{equ}
where in the last bound we used the definition of ${\mathfrak U}^\tau$ and the simple bound
\begin{equ}
\big|\tau D_0((\Sigma^\tau)^{-1} k_{1:n}) - D_0[\mathfrak{f}, \mathfrak{f}] \, |\mathfrak{f} \cdot k_{1:n}|^2\big| \lesssim \log_{*}(\tau)^{-1/3} \, |k_{1:n}|^2 \, .
\end{equ}
For the third summand, we use~\eqref{e:RemovalQ*R},~\eqref{e:BoundP} and~\eqref{e:HsUtau}, which results in
\begin{equ} \label{e:SimpleS3}
\mathrm{(III)} \lesssim n^2 \, \log_{*}(\tau) \, \tau^{-1} \, \|(1 - \tau {\mathfrak L}_0)^{1/2} \, {\mathfrak U}^\tau {\mathfrak L}_0^\mathfrak{f} \varphi\| \lesssim n^2 \log_{*}(\tau) \, \tau^{-1} \, \|(- {\mathfrak L}_0)^{3/2} \varphi\| \, .
\end{equ}
By combining~\eqref{e:SimpleS1},~\eqref{e:SimpleS2} and~\eqref{e:SimpleS3}, we deduce the desired estimate~\eqref{e:SimpleS}.
\smallskip

We tackle the proof of~\eqref{e:SimpleA-}. We write
\begin{equs}
\|(1 - \tau S)^{-1/2} \, \tau A_- \mathsf{i}_t^\tau \varphi\| &\leq \|(- \tau S)^{-1/2} \, (\tau A_- \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak A}_-) \, {\mathfrak U}_t^\tau\varphi\| + \|\mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak A}_- \, {\mathfrak U}_t^\tau\varphi\| \\
&\lesssim_\gamma n^6 \, \tau^{-1/4} \, \|(- {\mathfrak L}_0)^{3/4} \varphi\| + \tau \, \|{\mathfrak A}_- {\mathfrak U}_t^\tau\varphi\| \, , \label{e:SimpleA-1}
\end{equs}
where in the last bound we used Theorem~\ref{th:ComparisonGen} and~\eqref{e:HsUtau} to deal with the first summand (similarly to~\eqref{e:SimpleS1}), and we used~\eqref{e:BoundQ*} and~\eqref{e:BoundP} to deal with the second summand. Now, we estimate further the last term and write
\begin{equs}
\|&{\mathfrak A}_- {\mathfrak U}^\tau_t \varphi\|^2 \lesssim (n-1)! \int_{\mathbb{R}^{2(n-1)}} \mathrm{d} k_{1:n-1} \Big|n \, \sum_{i=1}^{n-1} (\mathfrak{e} \cdot k_i) \int_{\mathbb{R}^{2}} \mathrm{d} \ell \, \Pi_{\ell, k_i - \ell} \, {\mathfrak F}({\mathfrak U}^\tau_t \varphi) \, (\ell, k_i - \ell, k_{1:n-1 \setminus i})\Big|^2 \\
&\lesssim n! \, n^3 \int_{\mathbb{R}^{2(n-1)}} \mathrm{d} k_{1:n-1} \, |\mathfrak{e} \cdot k_1|^2 \Big|\int_{\mathbb{R}^2} \mathrm{d} \ell \, \Pi_{\ell, k_1 - \ell} \, {\mathfrak F}({\mathfrak U}^\tau_t \varphi) \, (\ell, k_1 - \ell, k_{2:n-1})\Big|^2 \\
&\lesssim n! \, n^3 \int_{\mathbb{R}^{2(n-1)}} \mathrm{d} k_{1:n-1} \mathrm{d} \ell \, |\mathfrak{e} \cdot k_1|^2 \, (1 + \tau \log_{*}(\tau)^{2/3} |\mathfrak{e} \cdot \ell|^2) \, (1 + \tau |\mathfrak{f} \cdot \ell|^2) \, |{\mathfrak F}({\mathfrak U}^\tau_t \varphi) \, (\ell, k_1 - \ell, k_{2:n-1})|^2 \\
&\qquad \times \int_{\mathbb{R}^2} \mathrm{d} \ell \, \frac{1}{(1 + \tau \log_{*}(\tau)^{2/3} |\mathfrak{e} \cdot \ell|^2) \, (1 + \tau |\mathfrak{f} \cdot \ell|^2)} \\
&\lesssim_\nu n! \, n^3 \int \mathrm{d} p_{1:n} \, |\mathfrak{e} \cdot p_{1:n}|^2 \, (1 + \tau \log_{*}(\tau)^{2/3} |\mathfrak{e} \cdot p_{1:n}|^2) \, (1 + \tau |\mathfrak{f} \cdot p_{1:n}|^2) \, |{\mathfrak F}({\mathfrak U}^\tau_t \varphi)(p_{1:n})|^2 \\
&\qquad \times \tau^{-1/2} \log_{*}(\tau)^{-1/3} \times \tau^{-1/2} \\
&\lesssim_\nu n^3 \, \tau^{-1} \log_{*}(\tau)^{-2/3} \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} (1 - {\mathfrak L}_0^\mathfrak{e})^{1/2} (1 - {\mathfrak L}_0^\mathfrak{f})^{1/2} \varphi\|^2 \times \tau^{-1} \log_{*}(\tau)^{-1/3} \\
&\lesssim n^3 \, \tau^{-2} \log_{*}(\tau)^{-1} \, \|(1 - {\mathfrak L}_0)^{3/2} \varphi\|^2 \, , \label{e:SimpleA-2}
\end{equs}
where we proceeded as follows: in the first bound we used the definition of ${\mathfrak A}_-$ as in~\eqref{e:fA-}; in the second bound we used the Cauchy-Schwarz inequality for the sum over $i$, and the symmetry of $f$ with respect to permutations of variables to reduce to $i = 1$; in the third bound, we used the Cauchy-Schwarz inequality for the integral over $\ell$, after biasing by $(1 + \tau \log_{*}(\tau)^{2/3} |\mathfrak{e} \cdot \ell|^2)^{\pm 1} \, (1 + \tau |\mathfrak{f} \cdot \ell|^2)^{\pm 1}$; in the fourth bound, we made the change of variable $p_{1:n} = (\ell, k_1 - \ell, k_{2:n})$ for the first integral, and we bounded the second integral by using the general estimate $\int_{\mathbb{R}} \frac{1}{1 + A x^2} \lesssim A^{-1/2}$ for $A > 0$;
in the fifth bound, we made the change of variable $q_{1:n} = (\Sigma^\tau)^{-1} p_{1:n}$ and used the definition of ${\mathfrak U}_t^\tau$ (cf. Definition~\ref{def:Utau}). Therefore, by plugging~\eqref{e:SimpleA-2} into~\eqref{e:SimpleA-1}, we deduce
\begin{equ}
\|(1 - \tau S)^{-1/2} \, \tau A_- \mathsf{i}_t^\tau \varphi\| \lesssim n^6 \log_{*}(\tau)^{-1/2} \, \|(1 - {\mathfrak L}_0)^{3/2} \varphi\| \, ,
\end{equ}
which shows the desired bound~\eqref{e:SimpleA-}.
\smallskip

Finally, we prove~\eqref{e:SimpleA0}. We first recall that $(\partial_t + \tau {\mathfrak A}_0) \, {\mathfrak U}_t^\tau = 0$ (cf. Remark~\ref{rmk:GalileanTransform}), which gives $\partial_t \, \mathsf{i}_t^\tau \varphi = - \mathsf{R} \mathsf{P} \, \tau {\mathfrak A}_0 \, {\mathfrak U}_t^\tau \varphi$. Hence, we obtain
\begin{equs}
\|(1 - \tau S)^{-1/2} \, (\partial_t + \tau A_0) \, &\mathsf{i}_t^\tau \varphi\| \leq \|(- \tau S)^{-1/2} \, (\tau A_0 \mathsf{R} \mathsf{P} - \mathsf{Q}^* \mathsf{P} \, \tau {\mathfrak A}_0) \, {\mathfrak U}_t^\tau\varphi\| \\
&\qquad \quad + \|(1 - \tau S)^{-1/2} \, (\mathsf{Q}^* - \mathsf{R}) \, \mathsf{P} \, \tau {\mathfrak A}_0 \, {\mathfrak U}_t^\tau\varphi\| \\
&\lesssim_\gamma n^6 \, \tau^{1/2} \, \|(- {\mathfrak L}_0)^{3/4} \, {\mathfrak U}^\tau \varphi\| + n^2 \log_{*}(\tau) \, \|(1 - \tau {\mathfrak L}_0)^{1/2} \, {\mathfrak A}_0 {\mathfrak U}_t^\tau \varphi\| \, , \\
&\lesssim n^6 \, \tau^{-1/4} \, \|(- {\mathfrak L}_0)^{3/4} \varphi\| + n^2 \log_{*}(\tau) \, \tau^{-1/2} \, \|(1 - {\mathfrak L}_0)^{1/2} (- {\mathfrak L}_0)^{1/2} \varphi\| \, ,
\end{equs}
where in the second bound we used Theorem~\ref{th:ComparisonGen} and~\eqref{e:RemovalQ*R}, and in the last bound we used~\eqref{e:HsUtau} and~\eqref{e:SimpleHsA0}. This shows the desired bound~\eqref{e:SimpleA0} and concludes the proof.

\label{p:CVsemigroupFock}
Let $\varepsilon \in (0,1/6)$. Then, for every $\tau \geq 1$, $t \geq 0$ and $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, it holds
\begin{equ} \label{e:QuantitativeCVsemigroup}
\|P_{\tau t} \, \mathsf{i}_t^\tau \varphi - \mathsf{i}_0^\tau P_t^{\lim} \varphi\| \lesssim_{\varepsilon} \frac{(1 \vee t) \, C_{1, 6}^{2}(\varphi)}{\log_{*}(\tau)^{1/6 - \varepsilon}} \, ,
\end{equ}
where the constant $C_{\alpha, \kappa}^s(\varphi)$ is defined in~\eqref{e:Cvphi}. As a consequence, for every $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$, it holds
\begin{equ} \label{e:CVsemigroupFock}
\sup_{t_0, t \geq 0} \|P_{\tau t} \, \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equ}

{\noindent \it Part I. Proof of~\eqref{e:QuantitativeCVsemigroup}}

In this proof, we take $\mu := 1/\tau$ and write $\mathrm{Cor}_t^\tau := \mathrm{Cor}_t^{\tau, 1/\tau}$ for conciseness (recall Definition~\ref{def:AnsatzA+ASEP}). Let $T > 0$ and set $\varphi_t := P_{T - t}^{\lim} \, \varphi$ for any $t \in [0,T]$. We write the following two Dynkin decompositions (recall Definition~\ref{def:MI})
\begin{equs}
\mathsf{i}_t^{\tau} \varphi_t \, (\eta_{\tau t}) &= \mathsf{i}_0^{\tau} \varphi_0 \, (\eta_0) + W_t^\tau\big([(\partial_\cdot + \tau L) \, \mathsf{i}_\cdot^\tau] \, \varphi_\cdot - \mathsf{i}_\cdot^\tau {\mathfrak L}^{\lim} \varphi_\cdot\big) + M_t^\tau(\mathsf{i}_\cdot^{\tau} \varphi_\cdot) \, , \label{e:CVDynkin1} \\ \mathrm{Cor}_t^\tau \varphi_t \, (\eta_{\tau t}) &= \mathrm{Cor}_0^\tau \varphi_0 \, (\eta_0) + W_t^\tau\big([(\partial_\cdot + \tau L) \, \mathrm{Cor}_\cdot^{\tau}] \, \varphi_\cdot - \mathrm{Cor}_\cdot^{\tau} {\mathfrak L}^{\lim} \varphi_\cdot\big) + M_t^\tau(\mathrm{Cor}_\cdot^\tau \varphi_\cdot) \, . \label{e:CVDynkin2}
\end{equs}
By summing the two formulas and rearranging the terms (in particular, in~\eqref{e:CVDynkin1}, we expand $L$ as $S + A_- + A_0 + A_+$ and ${\mathfrak L}^{\lim}$ as $d^{\lim} {\mathfrak L}_0^\mathfrak{e} + D_0[\mathfrak{f}, \mathfrak{f}] {\mathfrak L}_0^\mathfrak{f}$), we deduce
\begin{equ} \label{e:MildProcessDecomposition}
\mathsf{i}_t^{\tau} \varphi_t \, (\eta_{\tau t}) = \mathsf{i}_0^{\tau} \varphi_0 \, (\eta_0) + M_t^\tau(\mathsf{i}_\cdot^{\tau} \varphi_\cdot) + M_t^\tau(\mathrm{Cor}_\cdot^\tau \varphi_\cdot) + \mathcal{R}_t^\tau(\varphi) \, ,
\end{equ}
where the remainder term $\mathcal{R}_t^\tau(\varphi)$ is given by
\begin{equs}
\mathcal{R}_t^\tau(\varphi) &:= W_t^\tau(\tau S \, \mathsf{i}_\cdot^\tau \varphi_\cdot - D_0[\mathfrak{f}, \mathfrak{f}] \, \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{f} \varphi_\cdot)
+ W_t^\tau(\tau A_- \mathsf{i}_\cdot^{\tau} \varphi_\cdot)
+ W_t^\tau\big([(\partial_{\cdot} + \tau A_0) \, \mathsf{i}_\cdot^\tau] \varphi_\cdot\big) \\
&\quad + W_t^\tau(\tau A_+ \mathsf{i}_\cdot^\tau \varphi_\cdot + [(\partial_{\cdot} + \tau L) \, \mathrm{Cor}_\cdot^\tau] \, \varphi_\cdot - d^{\lim} \, \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi_\cdot\big) \\
&\quad - W_t^\tau(\mathrm{Cor}_\cdot^\tau {\mathfrak L}^{\lim} \varphi_\cdot) - \mathrm{Cor}_t^{\tau} \varphi_t \, (\eta_{\tau t}) + \mathrm{Cor}_0^{\tau} \varphi_0 \, (\eta_{0}) \, . \label{e:CVsemigroupSplitting}
\end{equs}
Now, start from~\eqref{e:MildProcessDecomposition}, take the conditional expectation with respect to $\mathcal{F}_0$ (which eliminates the two martingales) and choose $t = T$ (note that $\varphi_0 = P_T^{\lim} \varphi$ and $\varphi_T = \varphi$), which leads to
\begin{equ} \label{e:MildSemigroup}
P_{\tau T} \, \mathsf{i}_t^\tau \varphi - \mathsf{i}_0^\tau P_T^{\lim} \varphi = \mathbf E_{\nu_\varrho}[\mathcal{R}_T^\tau(\varphi)  | \mathcal{F}_0] \, . 
\end{equ}
Consequently, to prove the desired estimate~\eqref{e:QuantitativeCVsemigroup}, it only remains to show that
\begin{equ} \label{e:CVsemigroupClaim}
\mathbf E_{\nu_\varrho}\Big[\big|\mathcal{R}_T^\tau(\varphi)\big|^2\Big]^{1/2} \lesssim_\varepsilon T_* \, C_{1,10}^2(\varphi) \, \log_{*}(\tau)^{-1/6 + \varepsilon} \, .
\end{equ}

To prove~\eqref{e:CVsemigroupClaim}, we treat separately each summand appearing in~\eqref{e:CVsemigroupSplitting} (that we refer to as $\mathrm{(I)}$, $\mathrm{(II)}$, $\mathrm{(III)}$, $\mathrm{(IV)}$, $\mathrm{(V)}$, $\mathrm{(VI)}$, $\mathrm{(VII)}$ respectively). For later use, we give some trivial bounds: from the definition~\eqref{e:Cvphi} of $C_{\alpha, \kappa}^s$ we readily deduce that, for any $t \in [0,T]$,
\begin{equ} \label{e:CvphiSemigroup}
C^s_{\alpha, \kappa}(\varphi_t) \leq C^s_{\alpha, \kappa}(\varphi) \, , \quad C^s_{\alpha, \kappa}( {\mathfrak L}^{\lim} \, \varphi_t) \lesssim C^{s+1}_{\alpha, \kappa}(\varphi) \, ,
\end{equ}
and next, for any $\psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$, we have
\begin{equ} \label{e:TrivialBoundmuH-1}
\|(T^{-1} - \tau S)^{-1/2} \, \psi\| \leq T_*^{1/2} \, \|(1 - \tau S)^{-1/2} \, \psi\| \leq T_*^{1/2} \, \|\psi\| \, .
\end{equ}
To deal with $\mathrm{(I)}$, we use~\eqref{e:IL2},~\eqref{e:TrivialBoundmuH-1},~\eqref{e:SimpleS},~\eqref{e:CvphiSemigroup} and deduce
\begin{equs}
\mathbf E_{\nu_\varrho}\Big[\big|W_T^\tau(\tau S \, \mathsf{i}_\cdot^\tau \varphi_\cdot - D_0[\mathfrak{f}, \mathfrak{f}] \, \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{f} \varphi_\cdot)\big|^2\Big]^{1/2} &\lesssim T_* \sup_{r \in [0,T]} \|(1 - \tau S)^{-1/2} \, (\tau S \, \mathsf{i}_r^\tau - D_0[\mathfrak{f}, \mathfrak{f}] \, \mathsf{i}_r^\tau {\mathfrak L}_0^\mathfrak{f}) \, \varphi_r\| \\
&\lesssim T_* \, C_{1, 6}^2(\varphi) \log_{*}(\tau)^{-1/2} \, . \label{e:QuantitativeCVsemigroup1}
\end{equs}
To deal with $\mathrm{(II)}$, we use~\eqref{e:IL2},~\eqref{e:TrivialBoundmuH-1},~\eqref{e:SimpleA-},~\eqref{e:CvphiSemigroup} and obtain
\begin{equ}
\mathbf E_{\nu_\varrho}\Big[\big|W_T^\tau(\tau A_- \mathsf{i}_\cdot^{\tau} \varphi_\cdot)\big|^2\Big]^{1/2} \lesssim T_* \sup_{r \in [0,T]} \|(1 - \tau S)^{-1/2} \, \tau A_- \mathsf{i}_r^\tau \varphi_r\| \lesssim T_* \, C_{1, 6}^2(\varphi) \log_{*}(\tau)^{-1/2} \, . \label{e:QuantitativeCVsemigroup2}
\end{equ}
To deal with $\mathrm{(III)}$, we use~\eqref{e:IL2},~\eqref{e:TrivialBoundmuH-1},~\eqref{e:SimpleA0} (with any fixed $\gamma \in (0,1)$) and~\eqref{e:CvphiSemigroup}, which yields
\begin{equ}
\mathbf E_{\nu_\varrho}\Big[\big|W_T^\tau\big([(\partial_{\cdot} + \tau A_0) \, \mathsf{i}_\cdot^\tau] \varphi_\cdot\big)\big|^2\Big]^{1/2} \lesssim T_* \sup_{r \in [0,T]} \|(1 - \tau S)^{-1/2} \, [(\partial_r + \tau A_0) \, \mathsf{i}_r^\tau] \varphi_r\| \lesssim_\gamma T_* \, C_{1, 6}^2(\varphi) \, \tau^{- \gamma/2} \, . \label{e:QuantitativeCVsemigroup3}
\end{equ}
To deal with $\mathrm{(IV)}$, we use~\eqref{e:IL2},~\eqref{e:TrivialBoundmuH-1},~\eqref{e:AnsatzA+GenASEP} (recall that $\mu = 1/\tau$) and~\eqref{e:CvphiSemigroup}, which shows
\begin{equs}
\mathbf E_{\nu_\varrho}\Big[\big|W_T^\tau&(\tau A_+ \mathsf{i}_\cdot^\tau \varphi_\cdot + [(\partial_{\cdot} + \tau L) \, \mathrm{Cor}_\cdot^\tau] \, \varphi_\cdot - d^{\lim} \, \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi_\cdot\big)\big|^2\Big]^{1/2} \\
&\lesssim T_* \sup_{r \in [0,T]} \|(1 - \tau S)^{-1/2} \, (\tau A_+ \mathsf{i}_r^\tau \varphi_r + [(\partial_r + \tau L) \, \mathrm{Cor}_r^\tau] \, \varphi_r - d^{\lim} \, \mathsf{i}_r^\tau {\mathfrak L}_0^\mathfrak{e} \varphi_r)\| \\
&\lesssim T_* \, C_{1,6}^{3/2}(\varphi) \, \log_{*}(\tau)^{-1/6 + \varepsilon} \, . \label{e:QuantitativeCVsemigroup4}
\end{equs}
To deal with $\mathrm{(V)}$, we use~\eqref{e:IL2},~\eqref{e:TrivialBoundmuH-1},~\eqref{e:AnsatzA+L2ASEP} (recall that $\mu = 1/\tau$),~\eqref{e:CvphiSemigroup}, and deduce
\begin{equ}
\mathbf E_{\nu_\varrho} \Big[\big|W_t^\tau(\mathrm{Cor}_\cdot^\tau {\mathfrak L}^{\lim} \varphi_\cdot)\big|^2\Big]^{1/2} \lesssim T_* \sup_{r_1, r_2 \in [0,T]} \|\mathrm{Cor}_r^{\tau} \, {\mathfrak L}^{\lim} \varphi_r\| \lesssim (1 \vee T) \, C_{1,6}^{3/2}(\varphi) \, \log_{*}(\tau)^{-1/3} \, . \label{e:QuantitativeCVsemigroup5}
\end{equ}
Finally, we finish with the boundary terms $\mathrm{(VI)}$ and $\mathrm{(VII)}$. We can easily bound them by using the $\nu_\varrho$-stationarity,~\eqref{e:AnsatzA+L2ASEP} (recall that $\mu = 1/\tau$) and~\eqref{e:CvphiSemigroup}, which leads to
\begin{equ}
\sup_{t \in [0,T]} \mathbf E_{\nu_\varrho}\Big[\big|\mathrm{Cor}_t^{\tau} \varphi_t \, (\eta_{\tau t})\big|^2\Big]^{1/2} \lesssim \sup_{t \in [0,T]} \|\mathrm{Cor}_t^{\tau} \varphi_r\| \lesssim C_{1,0}^{1/2}(\varphi) \, \log_{*}(\tau)^{-1/3} \, . \label{e:QuantitativeCVsemigroup6}
\end{equ}
By gathering~\eqref{e:QuantitativeCVsemigroup1},~\eqref{e:QuantitativeCVsemigroup2},~\eqref{e:QuantitativeCVsemigroup3},~\eqref{e:QuantitativeCVsemigroup4},~\eqref{e:QuantitativeCVsemigroup5},~\eqref{e:QuantitativeCVsemigroup6}, we deduce~\eqref{e:CVsemigroupClaim} and conclude the proof of~\eqref{e:QuantitativeCVsemigroup}.
\medskip 

{\noindent \it Part II. Proof of~\eqref{e:CVsemigroupFock}}

First, by recalling Definition~\ref{def:Utau} and noticing that the translation operator ${\mathfrak T}_\cdot$ commutes with $P_t^{\lim}$, we have
\begin{equ}
\mathsf{i}^\tau_{t_0 + t} = \mathsf{i}^\tau_t \, {\mathfrak T}_{\tau t_0 v} \, , \quad \mathsf{i}^\tau_{t_0} P_t^{\lim} = \mathsf{i}^\tau_{0} \, P_t^{\lim} \, {\mathfrak T}_{\tau t_0 v} \, .
\end{equ}
Hence, by applying~\eqref{e:QuantitativeCVsemigroup} to ${\mathfrak T}_{\tau t_0 v} \, \varphi$ (and noticing that $C_{\alpha, \kappa}^s({\mathfrak T}_{\tau t_0 v} \varphi) = C_{\alpha, \kappa}^s(\varphi)$) we deduce
\begin{equ}
\|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \lesssim_\varepsilon \frac{(1 \vee t) \, C_{1,6}(\varphi)}{\log_{*}(\tau)^{1/6-\varepsilon}} \, .
\end{equ}
In particular, for any $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $T > 0$, we have
\begin{equ} \label{e:CVsemigroupLocal}
\sup_{t_0 \geq 0, \, t \in [0,T]} \|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equ}
Then, a straightforward density argument allows us to extend~\eqref{e:CVsemigroupLocal} to any $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$, because the operators $P_{\tau t} \mathsf{i}_{t_0 + t}^\tau$ and $\mathsf{i}_{t_0}^\tau P_t^{\lim}$ are uniformly bounded by $1$ from $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ to $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
$.
\smallskip

Hence, it only remains to extend~\eqref{e:CVsemigroupLocal} to $T = \infty$. First, note that we can assume $\mathbb{E}[\varphi] = 0$ up to replacing $\varphi$ by $\varphi - \mathbb{E}[\varphi]$. Next, by using the contractivity of $P_\cdot$, $P_\cdot^{\lim}$ and $\mathsf{i}^\tau_\cdot$, we deduce, for any $t_0 \geq 0$ and $t \geq T \geq 0$ (let us denote $t_1 := t_0 + t - T \geq 0$),
\begin{equs}
\|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| &\leq \|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi\| + \|\mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \\
&\leq \|P_{\tau T} \mathsf{i}_{t_0 + t}^\tau \varphi\| + \|P_T^{\lim} \varphi\| \\
&\leq \|P_{\tau T} \mathsf{i}_{t_1 + T}^\tau \varphi - \mathsf{i}_{t_1}^\tau P_T^{\lim} \varphi\| + 2 \|P_T^{\lim} \varphi\| \, ,
\end{equs}
which gives, for any $T \geq 0$,
\begin{equ} \label{e:ExtensionTinfty}
\sup_{t_0 \geq 0, \, t \geq 0} \|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \leq 2 \, \|P_T^{\lim} \varphi\| + \sup_{t_0 \geq 0, \, t \in [0,T]} \|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau \varphi - \mathsf{i}_{t_0}^\tau P_t^{\lim} \varphi\| \, .
\end{equ}
Now, we notice that $\|P_T^{\lim} \varphi\| \to 0$ as $T \to \infty$ because $\mathbb{E}[\varphi] = 0$ (which can be easily checked by a direct computation using the chaos decomposition). Consequently, by taking in~\eqref{e:ExtensionTinfty} the limsup first as $\tau \to \infty$ (which eliminates the second summand of the right hand side, by~\eqref{e:CVsemigroupLocal}) and then as $T \to \infty$ (to eliminate the first summand of the right hand side, by the previous observation), we deduce~\eqref{e:CVsemigroupFock} and conclude the proof.

\label{p:CVfindim}
For any $n \geq 1$, $0 \leq t_1 \leq ... \leq t_n$, $\varphi_1, ..., \varphi_n \in \mathcal{S}(\mathbb{R}^2)$, $f \colon \mathbb{R}^n \to \mathbb{R}$ continuous with at most polynomial growth, $p \in [1,\infty)$, it holds
\begin{equs}
\mathbf E_{\nu_\varrho}&[f(Y^\tau_{t_1}(\varphi_1), \dots, Y^\tau_{t_n}(\varphi_n))] \xrightarrow[\tau \to \infty]{} \mathbf E_{\mathbb P}^{\lim}[f(Y^{\lim}_{t_1}(\varphi_1), \dots, Y^{\lim}_{t_n}(\varphi_n))] \, , \label{e:CVfindimAnnealed} \\
\int_{\Omega} \nu_\varrho(\mathrm{d} \eta) \, \big|\mathbf E_{\eta}&[f(Y^\tau_{t_1}(\varphi_1), \dots, Y^\tau_{t_n}(\varphi_n))] - \mathbf E_{Z_0^\tau(\eta)}^{\lim}[f(Y^{\lim}_{t_1}(\varphi_1), \dots, Y^{\lim}_{t_n}(\varphi_n))]\big|^p \xrightarrow[\tau \to \infty]{} 0 \, . \quad\label{e:CVfindimQuenched}
\end{equs}

\label{def:CylinderFunctional}
A \emph{cylinder functional} is a function $F \colon \mathcal{S}'(\mathbb{R}^2) \to \mathbb{R}$ such that there exist an integer $m \geq 1$, a continuous function $f \in \mathcal{C}(\mathbb{R}^m, \mathbb{R})$ that grows at most polynomially fast, and test functions $\varphi_1, \dots, \varphi_m \in \mathcal{S}(\mathbb{R}^2)$, such that for every $w \in \mathcal{S}'(\mathbb{R}^2)$ it holds
\begin{equ} \label{e:CylinderFunctional}
F(w) = f(w(\varphi_1), \dots, w(\varphi_m)) \, .
\end{equ}
We denote by $\mathrm{Cyl}$ the space of cylinder functionals. We can define the semigroup $(P_t^{\lim})_{t \geq 0}$ on $\mathrm{Cyl}$, simply by using the formula $(P_t^{\lim} F)(w) \stackrel{\mbox{\tiny\rm def}}{=} \mathbf E^{\lim}_w[F(Y_t^{\lim})]$. Indeed, the fact that $P_t^{\lim} F \in \mathrm{Cyl}$ can easily be checked from the following explicit representation of the process $(Y_t^{\lim})_{t \geq 0}$
\begin{equ} \label{e:YlimExplicit}
Y_t^{\lim}(\varphi) = Y_0^{\lim}(K^{\lim}_t \varphi) + \int_0^t \vec{\xi}(\mathrm{d} s) \, \big(K^{\lim}_{t-s} \,  \sqrt{D^{\lim}} \, \nabla \varphi\big) \, ,
\end{equ}
where we denoted by $K^{\lim}_r \stackrel{\mbox{\tiny\rm def}}{=} \exp(r \, \nabla \cdot D^{\lim} \nabla / 2)$ the tweaked heat semigroup.

\label{lem:CVchaos}
For every $F \in \mathrm{Cyl}$ and $t \geq 0$, it holds
\begin{equ} \label{e:CVchaos}
\|F(Z_t^\tau) - \mathsf{i}_t^\tau (F(\zeta))\|_{L^2(\nu_\varrho)} \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equ}

