If we omit the hardcore condition in the last sum of~\eqref{e:ConsistencyExample}, then we obtain $Z_t^\tau(h)^n$. But the missing $x_{1:n} \in \mathbb{Z}^{2n} \cap DI$ cannot be neglected: more precisely, they result in terms of smaller degree (depending on the ``collision diagram'' of $x_{1:n}$), which eventually leads to a linear combination of smaller powers of $Z_t^\tau(h)$. What Lemma~\ref{lem:CVchaos} really tells us is that the combinatorics behind the ``collision diagrams'' matches, in the limit $\tau \to \infty$, the coefficients $c_{k,n}$ of the Hermite polynomial (recall~\eqref{e:Hermite}), so that~\eqref{e:ConsistencyExample} eventually approximates $H_n(Z_t^\tau(h)) = F(Z_t^\tau(h))$.

\label{lem:CVsemigroupCyl}
For every $F \in \mathrm{Cyl}$, $t_0, t \geq 0$ and $p \in [1,\infty)$, it holds
\begin{equ} \label{e:CVsemigroupCyl}
\|P_{\tau t} (F(Z^{\tau}_{t_0 + t})) - (P_t^{\lim} F) (Z_{t_0}^\tau)\|_{L^p(\nu_\varrho)} \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equ}

By using the triangle inequality, we obtain
\begin{equs}
\|P_{\tau t}(F(Z^{\tau}_{t_0 + t})) - (P_t^{\lim} F)(Z_{t_0}^\tau)\|_{L^2(\nu_\varrho)} &\leq \|P_{\tau t} \mathsf{i}_{t_0 + t}^\tau (F(\zeta)) - \mathsf{i}_{t_0}^\tau P_t^{\lim} (F(\zeta))\|_{L^2(\nu_\varrho)} \\
&\quad + \|P_{\tau t} [F(Z^{\tau}_{t_0 + t}) - \mathsf{i}_{t_0 + t}^\tau (F(\zeta))]\|_{L^2(\nu_\varrho)} \\
&\quad + \|(P_t^{\lim} F) (Z^\tau_{t_0}) - \mathsf{i}_{t_0}^\tau \, ((P_t^{\lim} F)(\zeta))\|_{L^2(\nu_\varrho)} \\
&\xrightarrow[\tau \to \infty]{} 0 \, ,
\end{equs}
where we used Proposition~\ref{p:CVsemigroupFock} to deal with the first summand and Lemma~\ref{lem:CVchaos} (together with the contractivity of $P_{\tau t}$) to deal with the two last. This shows the desired statement~\eqref{e:CVsemigroupCyl} for $p = 2$. But note that, for any $q \geq 1$,
\begin{equ}
\|P_{\tau t} (F(Z^{\tau}_{t_0 + t})) - (P_t^{\lim} F) (Z_{t_0}^\tau)\|_{L^q(\nu_\varrho)} \leq \nu_\varrho[|F(Z^{\tau}_{t_0 + t})|^q]^{1/q} + \mathbf E_{\nu_\varrho}[\mathbf E^{\lim}_{Y_{t_0}^\tau}[|F(Y_{t}^{\lim})|^q]]^{1/q} \, ,
\end{equ}
which is uniformly bounded in $\tau$, because of~\eqref{e:Concentration} and the at most polynomial growth of cylinder functionals. Therefore, by using Hölder's inequality, we can extend the statement~\eqref{e:CVsemigroupCyl} from $p = 2$ to any $p \geq 1$, which concludes the proof.

First, from the concentration bounds~\eqref{e:Concentration} (and the $\nu_\varrho$-stationarity of the ASEP, the $\mathbb P$-stationarity of $Y_\cdot^{\lim}$), we immediately deduce that, for any $\varphi \in \mathcal{S}(\mathbb{R}^2)$, $t \geq 0$, and $q \geq 1$,
\begin{equ}
\sup_{\tau \geq 1} \mathbf E_{\nu_\varrho}[|Y_t^\tau(\varphi)|^q] \vee \mathbf E_{\nu_\varrho}[\mathbf E_{Y_0^\tau}^{\lim}[|Y_t^{\lim}(\varphi)|^q]] \vee \mathbf E_{\mathbb P}^{\lim}[|Y_t^{\lim}(\varphi)|^q] < \infty \, .
\end{equ}
Consequently, an easy density/approximation argument shows that it is enough to prove Proposition~\ref{p:CVfindim} for a subset of functions $f$ whose span is dense in $\mathcal{C}_0(\mathbb{R}^n, \mathbb{R})$. Hence, we can assume without loss of generality that $f$ is of the form $f(y_1, \dots, y_n) = f_1(y_1) \dots f_n(y_n)$ with functions $f_i \in \mathcal{C}_0(\mathbb{R}, \mathbb{R})$.
\smallskip

We denote $F_i = f_i(\cdot(\varphi_i)) \in \mathrm{Cyl}$, and let $t_0 := 0$. Let us define iteratively, for $k \in \{0, \dots, n\}$, the functionals $G_k^\tau \colon \Omega \to \mathbb{R}$ and $G_k^{\lim} \in \mathrm{Cyl}$ as follows: $G_n^\tau = G_n^{\lim} = 1$ and for $k \in \{0, \dots, n-1\}$
\begin{equ} \label{e:MarkovIteration}
G_k^\tau := P_{\tau (t_{k+1} - t_k)} \big(F_{k+1}(Z_{t_{k+1}}^\tau) \times G_{k+1}^\tau\big) \, , \quad G_k^{\lim} := P^{\lim}_{t_{k+1} - t_k} \big(F_{k+1} \times G_{k+1}^{\lim}\big) \, .
\end{equ}
Note that these functionals are uniformly bounded by $C := (1 \vee \|f_1\|_\infty) \dots (1 \vee \|f_n\|_\infty)$. The interest of this definition is that, by the Markov property, we have
\begin{equ} \label{e:MarkovCascade}
G_0^\tau(\eta) = \mathbf E_{\eta}[F_1(Y^\tau_{t_1}) \dots F_n(Y^{\tau}_{t_n})] \, , \quad G_0^{\lim}(Z_0^\tau) = E_{Z_0^\tau}^{\lim}[F_1(Y^{\lim}_{t_1}) \dots F_n(Y^{\lim}_{t_n})] \, .
\end{equ}
Let us show, by (backward) induction on the index $k$, that $G_k^\tau - G_k^{\lim}(Z_{t_k}^\tau) \to 0$ in $L^p(\nu_\varrho)$ for every $p \geq 1$. For the index $n$, this is trivial since $G_n^\tau \equiv 1 \equiv G_n^{\lim}$. Now, assume that the property holds for index $k+1$ and let us prove it for index $k$. Observe that
\begin{equs}
G_k^\tau - G_k^{\lim}(Z_k^\tau) &= P_{\tau (t_{k+1} - t_k)} \, \big((F_{k+1} \times G_{k+1}^{\lim})(Z_{t_{k+1}}^\tau)\big) - \big(P^{\lim}_{t_{k+1} - t_k} (F_{k+1} \times G_{k+1}^{\lim})\big) (Z_{t_k}^\tau) \\
&\quad + P_{\tau (t_{k+1} - t_k)} \, \big(F_{k+1}(Z_{t_{k+1}}^\tau) \times (G_{k+1}^\tau - G_{k+1}^{\lim}(Z_{t_{k+1}}^\tau))\big) \, .
\end{equs}
Notice that the two lines on the right hand side converge to $0$ in $L^p(\nu_\varrho)$ as $\tau \to \infty$: for the first line this follows from Lemma~\ref{lem:CVsemigroupCyl} (applied to the cylinder functional $F_{k+1} \times G_{k+1}^{\lim}$), and for the second line this follows from the $L^p(\nu_\varrho)$-contractivity of the ASEP semigroup, the bound $\|F_{k+1}\|_\infty \leq C$ and the induction hypothesis $\|G_{k+1}^\tau - G_{k+1}^{\lim}(Z_{t_{k+1}}^\tau)\|_{L^p(\nu_\varrho)} \to 0$. This concludes the proof of the induction: we deduce that $\|G_0^\tau - G_0^{\lim}(Z_0^\tau)\|_{L^p(\nu_\varrho)} \to 0$, which, in view of~\eqref{e:MarkovCascade}, is exactly the desired statement~\eqref{e:CVfindimQuenched}.
\smallskip

Finally, we prove~\eqref{e:CVfindimAnnealed}. By using the trivial bound
\begin{equs}
