In particular, we deduce
\begin{equ}
\|\mathrm{Err}_r^\tau(\psi)\| \leq \sum_{\ell \in 2 \pi \mathbb{Z}^2 \setminus \{0\}} \|{\mathfrak F}({\mathfrak U}_r^\tau \psi)\|_{L^2(\ell + \square)} \lesssim_m \sum_{\ell \in 2 \pi \mathbb{Z}^2 \setminus \{0\}} |\ell|^{-2m} \, \|(- {\mathfrak L}_0)^m \, {\mathfrak U}_r^\tau \psi\| \lesssim_m \|(- {\mathfrak L}_0)^m \, {\mathfrak U}_r^\tau \psi\| \, .
\end{equ}
Then, by using the definition of ${\mathfrak U}_r^\tau$ and the bound $|(\Sigma^\tau)^{-1} \, k|^2 \leq \tau^{-1} \, |k|^2$, we obtain $\|(- {\mathfrak L}_0)^m \, {\mathfrak U}_r^\tau \psi\| \leq \tau^{-m} \|(- {\mathfrak L}_0)^m \, \psi\|$ and deduce the claim~\eqref{e:ReplacementRP}.
\smallskip

Now, note that we deduce from~\eqref{e:ReplacementRP} the crude bounds
\begin{equ} \label{e:ReplacementRPCrude}
    \|(-\tau S)^{1/2} \, \mathrm{Err}_r^\tau(\psi)\| \lesssim_{m, \psi} \tau^{1/2 - m} \, , \quad \|\tau L \, \mathrm{Err}_r^\tau(\psi)\| \lesssim_{m, \psi} \tau^{1 - m} \, , \quad \|\partial_r \, \mathrm{Err}_r^\tau(\psi)\| \lesssim_{m, \psi} \tau^{1/2-m} \, ,
\end{equ}
where we used that $S$, $L$ are bounded from $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
$ to $
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{}
    \else
        \Gamma_0 h^{}_{}
    \fi
$, and we noticed that Definition~\ref{def:Utau} gives $\partial_r \mathrm{Err}_r^\tau(\psi) = - \tau^{1/2} \log_*(\tau)^{-1/3} \, \mathrm{Err}_r^\tau(v \cdot \nabla \psi)$.
\smallskip

Finally, we prove~\eqref{e:TightIRepl} and~\eqref{e:TightMRepl}. On the one hand, by using~\eqref{e:KolmogorovI} (with the trivial bound $\|(|t-s|^{-1} - \tau S)^{-1/2} \cdot\| \leq |t-s|^{1/2} \|\cdot\|$) and~\eqref{e:ReplacementRPCrude}, we obtain
\begin{equ} \label{e:TightIReplbis}
\mathbf E_{\nu_\varrho} \Big[\big|W_{s,t}^\tau\big((\partial_\cdot + \tau L) \mathrm{Err}_\cdot^\tau(\varphi)\big)\big|^p\Big] \lesssim_{\varphi} |t-s|^{p} \, \tau^{(1-m)p} \, .
\end{equ}
On the other hand, by using~\eqref{e:AldousM} and~\eqref{e:ReplacementRPCrude}, we deduce
\begin{equ}  \label{e:TightMReplbis}
\mathbf E_{\nu_\varrho} \Big[\big|M_{{\rm T}_1, {\rm T}_2}^\tau\big(\mathrm{Err}_\cdot^\tau(\varphi)\big)\big|^2\Big] \lesssim_{\varphi, T} \delta^{1-2/p} \, \tau^{1-2m} \, .
\end{equ}
Since $m$ can be chosen arbitrarily large, we deduce the desired estimates~\eqref{e:TightIRepl} and~\eqref{e:TightMRepl}.
\medskip

{\noindent \it Step 2. The diffusive part of the dynamics}
\smallskip

Now, we turn to the diffusive contributions and show that
\begin{equs}
\mathbf E_{\nu_\varrho} \Big[\big|W_{s,t}^\tau\big((\partial_\cdot + \tau L - \tau A_+) \, \mathsf{i}_\cdot^\tau \varphi\big)\big|^p\Big] &\lesssim_{T, \varphi} |t-s|^{p/2} \, , \label{e:TightIdiff} \\
\mathbf E_{\nu_\varrho} \Big[\big|M_{{\rm T}_1, {\rm T}_2}^\tau (\mathsf{i}_\cdot^\tau \varphi)\big|^2\Big] &\lesssim_{T, \varphi} \delta^{1 - 2/p} \, . \label{e:TightMdiff}
\end{equs}
In fact, these bounds are easy consequences of Proposition~\ref{p:TightnessBlackBox} and Lemma~\ref{lem:SimpleGen}.
\smallskip

First, observe that~\eqref{e:TightMdiff} readily follows from~\eqref{e:AldousM} and~\eqref{e:SimpleH1}.

We turn to the proof of~\eqref{e:TightIdiff}. First, note that $(\partial_r + \tau L - \tau A_+) \, \mathsf{i}_r^\tau \varphi = (\tau S + \partial_r + \tau A_0) \, \mathsf{i}_r^\tau \varphi$; indeed, $A_- \mathsf{i}_r^\tau \varphi = 0$ because $\varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{1}
    \else
        \Gamma_0 h^{}_{1}
    \fi
$. By using~\eqref{e:KolmogorovI} (with the trivial bound $\|(|t-s|^{-1} - \tau S)^{-1/2} \cdot\| \leq \|(- \tau S)^{-1/2} \cdot\|$) and~\eqref{e:SimpleH1}, we obtain
\begin{equ} \label{e:TightIdiffS}
\mathbf E_{\nu_\varrho} \Big[\big|W_{s,t}^\tau(\tau S \, \mathsf{i}_\cdot^\tau \varphi)\big|^p\Big] \lesssim_{T, \varphi} |t-s|^{p/2} \, .
\end{equ}
By using~\eqref{e:KolmogorovI} (with the trivial bound $\|(|t-s|^{-1} - \tau S)^{-1/2} \cdot\| \leq (1 \vee T)^{1/2} \, \|(1- \tau S)^{-1/2} \cdot\|$) and~\eqref{e:SimpleA0}, we deduce that, for any $\gamma \in (0,1)$,
\begin{equ} \label{e:TightIdiffA0}
\mathbf E_{\nu_\varrho} \Big[\big|W_{s,t}^\tau\big((\partial_\cdot + \tau A_0) \, \mathsf{i}_\cdot^\tau \varphi\big)\big|^p\Big] \lesssim_{T, \varphi, \gamma} |t-s|^{p/2} \, \tau^{- \gamma p/2} \, .
\end{equ}
By combining~\eqref{e:TightIdiffS} and~\eqref{e:TightIdiffA0}, we deduce the desired estimate~\eqref{e:TightIdiff}.
\medskip

{\noindent \it Step 3. The superdiffusive part of the dynamics}
\smallskip

Finally, we tackle the superdiffusive contribution and show that
\begin{equ}
    \mathbf E_{\nu_\varrho} \Big[\big|W_{s,t}^\tau\big(\tau A_+ \, \mathsf{i}_\cdot^\tau \varphi\big)\big|^p\Big] \lesssim_{T, \varphi} |t-s|^{p/2} \, . \label{e:TightIA+}
\end{equ}
This is the most interesting term because it requires the use of the fluctuation dissipation relation~\eqref{e:FormalFluctuationDissipationASEP}. As mentioned before, we choose here the parameter $\mu$ as $\mu := \tau^{-1} \, |t-s|^{-1}$. Note that, without loss of generality, it is sufficient to show~\eqref{e:TightIA+} for times $s,t$ that satisfy $|t-s| \leq 1$: then, we have $\mu \tau \geq 1$ as required in Proposition~\ref{p:AnsatzA+}. Now, we write
\begin{equs}
W_{s,t}^\tau\big(\tau A_+ \, \mathsf{i}_\cdot^\tau \varphi\big) &= M_{s,t}^\tau\big(\mathrm{Cor}^{\tau, \mu}_\cdot(\varphi)\big) + d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} W_{s,t}(\mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi) + \mathrm{Cor}^{\tau, \mu}_s(\varphi)(\eta_{\tau s}) - \mathrm{Cor}^{\tau, \mu}_t(\varphi)(\eta_{\tau t}) \\
&\quad + W_{s,t}^\tau\Big(\tau A_+ \, \mathsf{i}_\cdot^\tau \varphi + (\partial_\cdot + \tau L) \mathrm{Cor}^{\tau, \mu}_\cdot(\varphi) - d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\Big) \, . \label{e:TightFluctuationDissipation}
\end{equs}

To estimate the fluctuation term, we use~\eqref{e:KolmogorovM},~\eqref{e:AnsatzA+L2ASEP} and~\eqref{e:AnsatzA+H1ASEP}, which gives
\begin{equ} \label{e:TightIA+M}
\mathbf E_{\nu_\varrho}\Big[\big|M_{s,t}^\tau\big(\mathrm{Cor}^{\tau, \mu}_\cdot(\varphi)\big)\big|^p\Big] \lesssim_{T, \varphi} |t-s|^{p/2} \, (\log_{*}(\tau)^{-(1/6 - \varepsilon) p} \, |t-s|^{p/2} + 1) \lesssim_{T, \varphi} |t-s|^{p/2} \, .
\end{equ}

To estimate the dissipation term, we recall that $1/\mu \leq \tau$, use~\eqref{e:KolmogorovI} (with the trivial bound $\|(|t-s|^{-1} - \tau S)^{-1/2} \cdot\| \leq |t-s|^{1/2}$) and the $L^2$ contractivity of $\mathsf{i}_\cdot^\tau$, which leads to
\begin{equ} \label{e:TightIA+Lnew}
\mathbf E_{\nu_\varrho}\Big[\Big|d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \, W_{s,t}^\tau(\mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi)\Big|^p\Big] \lesssim_{T, \varphi} |t-s|^{p} \, .
\end{equ}

To estimate the boundary terms, we use the $\nu_\varrho$-stationarity, the hypercontractivity~\eqref{e:UltHyper} and~\eqref{e:AnsatzA+L2ASEP} (recall that $\mu \tau = |t-s|^{-1}$), which results in (for $r \in \{s,t\}$)
\begin{equ} \label{e:TightIA+bc}
\mathbf E_{\nu_\varrho}\Big[\big|\mathrm{Cor}^{\tau, \mu}_r(\varphi)\big|^p\Big] = \|\mathrm{Cor}^{\tau, \mu}_\cdot(\varphi)\|_{L^p(\nu_\varrho)}^p \lesssim \|\alpha^N \mathrm{Cor}^{\tau, \mu}_\cdot(\varphi)\|^p \lesssim_{\varphi} |t - s|^{p/2} \, \log_{*}(\tau)^{-p/3} \, .
\end{equ}

To estimate the error term, we use~\eqref{e:KolmogorovI} and~\eqref{e:AnsatzA+GenASEP}, which gives
\begin{equs} \label{e:TightIA+Error}
\mathbf E_{\nu_\varrho}\Big[\Big|W_{s,t}^\tau\big(\tau A_+ \, \mathsf{i}_\cdot^\tau \varphi + (\partial_\cdot + \tau L) \mathrm{Cor}^{\tau, \mu}_\cdot(\varphi) - &d^{\lim} \frac{\log_{*}(1/\mu)^{2/3}}{\log_{*}(\tau)^{2/3}} \mathsf{i}_\cdot^\tau {\mathfrak L}_0^\mathfrak{e} \varphi\big)\Big|^p\Big] \\
&\lesssim_{T, \varphi} |t-s|^{p/2} \, \log_{*}(\tau)^{-(1/6 - \varepsilon) p} \, .
\end{equs}

By combining~\eqref{e:TightIA+M},~\eqref{e:TightIA+Lnew},~\eqref{e:TightIA+bc}, and~\eqref{e:TightIA+Error}, we deduce~\eqref{e:TightIA+} and conclude the proof.

The convergence in law of the process $(Y_t^\tau)_{t \geq 0}$ under $\mathbf P_{\nu_\varrho}$ to the process $(Y_t^{\lim})_{t \geq 0}$ under $\mathbf P_{\mathbb P}^{\lim}$ is a standard consequence of the convergence of the finite-dimensional laws (\eqref{e:CVfindimAnnealed} in Proposition~\ref{p:CVfindim}) and tightness (Proposition~\ref{p:Tightness}). However, deducing the ``functional convergence in law conditioned on the initial condition'' as stated in~\eqref{e:CLTFunctionalQuenched} from its finite-dimensional marginal analogue (\eqref{e:CVfindimQuenched} in Proposition~\ref{p:CVfindim}) and tightness is much less standard; hence, we give more details.
\smallskip

The key ingredient is the following elementary result which states that bounded continuous functionals on $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ can always be uniformly approximated on compact subsets by space-time cylinder functionals.
\begin{lemma} \label{lem:ApproxCyl}
Let $F \colon D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2)) \to \mathbb{R}$ be a bounded continuous function, $K \subset D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ be a compact subset, and $\varepsilon > 0$. Then, there exist $n \geq 1$, $0 \leq t_1 \leq ... \leq t_n$, $\varphi_1, ..., \varphi_n \in \mathcal{S}(\mathbb{R}^2)$, and a continuous function $g \colon \mathbb{R}^n \to \mathbb{R}$ bounded by $\|F\|_\infty$ such that, for every $y_\cdot \in K$,
\begin{equ} \label{e:ApproxCyl}
|F(y_\cdot) - g(y_{t_1}(\varphi_1), ..., y_{t_n}(\varphi_n))| < \varepsilon \, .
\end{equ}
\end{lemma}
The subtlety here is that the space-time cylinder functionals themselves are \emph{not continuous} on $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. In particular, it is not possible to deduce Lemma~\ref{lem:ApproxCyl} from the Stone-Weierstrass theorem (contrary to the analogous statement with $C(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ instead of $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$). We postpone the proof of Lemma~\ref{lem:ApproxCyl} to the end of this section.
\smallskip

Now, let $\varepsilon > 0$. First, we recall that Proposition~\ref{p:Tightness} shows the tightness of the laws of $Y_\cdot^\tau$ under $\mathbf P_{\nu_\varrho}$ in $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. Second, as discussed at the end of the proof of Proposition~\ref{p:CVfindim}, we know that the process $Y_\cdot^{\lim}$ started from $Z_0^\tau(\eta)$ with $\eta \sim \nu_\varrho$ converges in law to $\mathbf P^{\lim}_{\mathbb P}$ as $\tau \to \infty$ in $C(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. In particular, the laws of the latter processes are also tight in $D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$. Consequently, there exists a compact subset $K \subset D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ such that, for every $\tau \geq 1$,
\begin{equ} \label{e:CompactTightness}
\mathbf P_{\nu_\varrho}[Y_\cdot^{\tau} \not \in K] < \varepsilon \, , \quad \nu_\varrho[\mathbf P_{Z_0^\tau(\eta)}^{\lim}[Y_\cdot^{\lim} \not \in K]] < \varepsilon \, .
\end{equ}
Then, we apply Lemma~\ref{lem:ApproxCyl} (let us write $G(y_\cdot) := g(y_{t_1}(\varphi_1), ..., y_{t_n}(\varphi_n))$ for the corresponding space-time cylinder functional) and deduce, for every $y_\cdot \in K$,
\begin{equ} \label{e:SpaceTimeCylinderApprox}
|F(y_\cdot) - G(y_{\cdot})| < \varepsilon \, .
\end{equ}
Then, by gathering~\eqref{e:CompactTightness} and~\eqref{e:SpaceTimeCylinderApprox} (and recalling that $\|G\|_\infty \leq \|F\|_\infty$), we immediately deduce
\begin{equs}
\int_\Omega \mathrm{d} \nu_\varrho(\eta) \, \big|\mathbf E_{\eta}[F(Y_\cdot^\tau)] &- \mathbf E_{Z_0^\tau(\eta)}[F(Y_\cdot^{\lim})]\big| \\
&\leq 4 \|F\|_\infty \, \varepsilon + 2 \varepsilon + \int_\Omega \mathrm{d} \nu_\varrho(\eta) \, \big|\mathbf E_{\eta}[G(Y_\cdot^\tau)] - \mathbf E_{Z_0^\tau(\eta)}^{\lim}[G(Y_\cdot^{\lim})]\big| \\
&\leq 4 \|F\|_\infty \, \varepsilon + 3 \varepsilon \, ,
\end{equs}
where the last line holds for sufficiently large $\tau$ because of the convergence~\eqref{e:CVfindimQuenched}. Since $\varepsilon$ can be taken arbitrarily small, we deduce the desired statement~\eqref{e:CLTFunctionalQuenched} and conclude the proof.

\label{lem:ApproxCyl}
Let $F \colon D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2)) \to \mathbb{R}$ be a bounded continuous function, $K \subset D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ be a compact subset, and $\varepsilon > 0$. Then, there exist $n \geq 1$, $0 \leq t_1 \leq ... \leq t_n$, $\varphi_1, ..., \varphi_n \in \mathcal{S}(\mathbb{R}^2)$, and a continuous function $g \colon \mathbb{R}^n \to \mathbb{R}$ bounded by $\|F\|_\infty$ such that, for every $y_\cdot \in K$,
\begin{equ} \label{e:ApproxCyl}
|F(y_\cdot) - g(y_{t_1}(\varphi_1), ..., y_{t_n}(\varphi_n))| < \varepsilon \, .
\end{equ}

For any $n \geq 1$ and any path $x = (x_t)_{t \geq 0}$ (taking values in either $\mathbb{R}$ or $\mathcal{S}'(\mathbb{R}^2)$), we define the dyadic piecewise constant path $x^{[n]} = (x_t^{[n]})_{t \geq 0}$ as follows
\begin{equ}
x_t^{[n]} \stackrel{\mbox{\tiny\rm def}}{=} \sum_{k=0}^{4^n-1} x_{k \, 2^{-n}} \, \1_{[k \, 2^{-n}, \, (k+1) \, 2^{-n})}(t) \, .
\end{equ}
We leave to the reader the proof of the following elementary fact about the Skorokhod topology. Let $d$ be a metric inducing the Skorokhod topology on $D(\mathbb{R}_+, \mathbb{R})$. For any $f \in D(\mathbb{R}_+, \mathbb{R})$ and $\delta > 0$, there exist $n_0 \geq 1$ and $\delta' > 0$ such that, for every $n \geq n_0$ and $g \in D(\mathbb{R}_+, \mathbb{R})$ such that $d(g, f) < \delta'$, we have $d(g^{[n]}, f) < \delta$.

Let $\varepsilon > 0$. Now, by combining the continuity of $F$ and the previous fact, we deduce the following property: for every $x_\cdot \in D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$ there exist $n_0 \geq 1$, $\delta > 0$ and a finite subset $\mathcal{T} \subset \mathcal{S}(\mathbb{R}^2)$ such that, for every $n \geq n_0$ and $y_\cdot \in U(x_\cdot, \mathcal{T}, \delta) := \{y_\cdot \in D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2)) \mbox{ such that } \forall \varphi \in \mathcal{T}, \, d(y_\cdot(\varphi), x_\cdot(\varphi)) < \delta\}$, we have $|F(y_\cdot) - F(x_\cdot)| < \varepsilon/2$ and $|F(y_\cdot^{[n]}) - F(x_\cdot)| < \varepsilon/2$. By compactness of $K$, we can consider a finite covering by such open subsets: let $K \subset \bigcup_{i=1}^m U(x_\cdot^{(i)}, \mathcal{T}^{(i)}, \delta^{(i)}) =: \bigcup_{i=1}^m U^{(i)}$. Thus, there exists $n \geq 1$ such that, for every $i \in \{1, ..., m\}$ and $y_\cdot \in U^{(i)}$, we have $|F(y_\cdot) - F(x_\cdot^{(i)})| < \varepsilon/2$ and $|F(y_\cdot^{[n]}) - F(x_\cdot^{(i)})| < \varepsilon/2$.

Finally, let $V \subset \mathcal{S}(\mathbb{R}^2)$ be the linear span of the elements of $\mathcal{T}^{(1)}, \dots, \mathcal{T}^{(m)}$, and let $\pi_V \colon \mathcal{S}'(\mathbb{R}^2) \to V (\subset \mathcal{S}'(\mathbb{R}^2))$ be the orthogonal projection onto $V$, that is $\pi_V(T) := \sum_{i=1}^M T(\varphi_i) \, \langle \varphi_i, \cdot \rangle_{L^2(\mathbb{R}^2)}$ where $(\varphi_1, \dots, \varphi_M)$ is an $L^2(\mathbb{R}^2)$-orthonormal basis of $V$. Recalling the definition of $U^{(i)} = U(x_\cdot^{(i)}, \mathcal{T}^{(i)}, \delta^{(i)})$, we deduce the following property: if $y_\cdot \in U^{(i)}$, then we also have $\pi_V(y_\cdot) \in U^{(i)}$, which in particular gives
\begin{equ}
|F(y_\cdot) - F(\pi_V(y_\cdot)^{[n]})| \leq |F(y_\cdot) - F(x_\cdot^{(i)})| + |F(\pi_V(y_\cdot)^{[n]}) - F(x_\cdot^{(i)})| < \varepsilon \, .
\end{equ}
In particular, we deduce that for any $y \in K$ it holds $|F(y) - F(\pi_V(y_\cdot)^{[n]})| < \varepsilon$. This concludes the proof after noticing that, for any $y_\cdot \in D(\mathbb{R}_+, \mathcal{S}'(\mathbb{R}^2))$, we have $F(\pi_V(y_\cdot)^{[n]}) = g((y_{k 2^{-n}}(\varphi_j))_{0 \leq k \leq 4^n - 1, \, 1 \leq j \leq M})$ where we have defined $g \colon \mathbb{R}^{4^n \times M} \to \mathbb{R}$ as follows
\begin{equ}
g((\alpha_{k,j})_{k, j}) := F\Big(\sum_{k,j} \alpha_{k, j} \, \varphi_j \, \1_{[k \, 2^{-n}, \, (k+1) \, 2^{-n})}(\cdot)\Big) \, ,
\end{equ}
the latter function being indeed continuous and bounded by $\|F\|_\infty$.

Let $\varphi_1, \varphi_2 \in \mathcal{S}(\mathbb{R}^2)$ such that $\varphi_1$ is even-symmetric and observe that, by translation invariance of the law $\mathbf{P}_{\nu_\varrho}$ and the formula~\eqref{e:2PointFunction}, it holds
\begin{equs}
\mathbf{E}_{\nu_\varrho}[Y_0^\tau(\varphi_1) &Y_1^\tau(\varphi_2)] = \det(\Sigma^\tau)^{-1} \sum_{x, y \in \mathbb{Z}^2} \varphi_1((\Sigma^\tau)^{-1} x) \, \varphi_2((\Sigma^\tau)^{-1}(y - \tau v)) \, \mathbf{E}_{\nu_\varrho}[\sigma_0(x) \, \sigma_\tau(y)] \\
&= \det(\Sigma^\tau)^{-1} \sum_{x, z \in \mathbb{Z}^2} \varphi_1((\Sigma^\tau)^{-1} x) \, \varphi_2((\Sigma^\tau)^{-1}(z - \tau v) + (\Sigma^\tau)^{-1} x) \, \mathbf{E}_{\nu_\varrho}[\sigma_0(0) \, \sigma_\tau(z)] \\
&= \mathbf{E}_{\nu_\varrho}^{\mathrm{II}}\big[(\varphi_1 *_\tau \varphi_2) \, ((\Sigma^\tau)^{-1}(X_\tau - \tau v))\big] \, , \label{e:Correspondence2ndClassFluctuation}
\end{equs}
where we have defined the discrete convolution $\varphi_1 *_\tau \varphi_2 \in \mathcal{S}(\mathbb{R}^2)$ as follows
\begin{equ}
\varphi_1 *_\tau \varphi_2 \, (\mathrm{z}) \stackrel{\mbox{\tiny\rm def}}{=} \det(\Sigma^\tau)^{-1} \sum_{x \in \mathbb{Z}^2} \varphi_1((\Sigma^\tau)^{-1} x) \, \varphi_2(\mathrm{z} - (\Sigma^\tau)^{-1} x) \, .
\end{equ}
Recognizing a Riemann sum, it is clear that $\varphi_1 *_\tau \varphi_2$ converges uniformly to $\varphi_1 * \varphi_2$ as $\tau \to \infty$. Consequently, as $\tau \to \infty$, it holds
\begin{equ}
\mathbf{E}_{\nu_\varrho}[Y_0^\tau(\varphi_1) Y_1^\tau(\varphi_2)] = \mathbf{E}_{\nu_\varrho}^{\mathrm{II}}\big[(\varphi_1 * \varphi_2) \, ((\Sigma^\tau)^{-1}(X_\tau - \tau v))\big] + o(1) \, .
\end{equ}

Therefore, we deduce from~\eqref{e:2ptCV} that, as $\tau \to \infty$,
\begin{equ} \label{e:preCVlaw2ndClass}
\mathbf{E}_{\nu_\varrho}^{\mathrm{II}}\big[(\varphi_1 * \varphi_2) \, ((\Sigma^\tau)^{-1}(X_\tau - \tau v))\big] \to \langle \varphi_1 * \varphi_2, g^{\lim} \rangle_{L^2(\mathbb{R}^2)} \, ,
\end{equ}
for any $\varphi_1, \varphi_2 \in \mathcal{S}(\mathbb{R}^2)$ such that $\varphi_1$ is even-symmetric. Then, since the span of the functions of the form $\varphi_1 * \varphi_2$ with such $\varphi_1$ and $\varphi_2$ is clearly dense in $\mathcal{C}_0(\mathbb{R}^2)$ (observe for instance that it contains every linear combination of Gaussian densities), we deduce that
\begin{equ} \label{e:CVlaw2ndClass}
\mathbf{E}_{\nu_\varrho}^{\mathrm{II}}\big[\varphi ((\Sigma^\tau)^{-1}(X_\tau - \tau v))\big] \to \langle \varphi, g^{\lim} \rangle_{L^2(\mathbb{R}^2)} \, ,
\end{equ}
for any $\varphi \in \mathcal{C}_0(\mathbb{R}^2)$. Finally, since $g^{\lim}$ is a probability distribution, we can extend the convergence~\eqref{e:CVlaw2ndClass} to any $\varphi \in \mathcal{C}_b(\mathbb{R}^2)$ and conclude the proof of Theorem~\ref{th:CLT2ndClass}.

Let $t \geq 1$, set $\mu := 1/t$ and fix $\varepsilon \in (0,1/6)$. Recall Definition~\ref{def:MI}. We write
\begin{equ} \label{e:DiffProof}
\int_0^t B_+ \mathcal{V}^\delta(\eta_s) \, \mathrm{d} s = M_t(\mathrm{Cor}_{\mu, \delta}^{B+}) - \mathrm{Cor}_{\mu, \delta}^{B+}(\eta_{t}) + \mathrm{Cor}_{\mu, \delta}^{B+}(\eta_0) + W_t(L \, \mathrm{Cor}_{\mu, \delta}^{B+} + B_+ \mathcal{V}^\delta) \, .
\end{equ}
The boundary terms can be easily bounded by using the $\nu_\varrho$-stationarity of the ASEP and~\eqref{e:AnsatzDiffL2ASEP},
\begin{equ} \label{e:DiffProof1}
\mathbf E_{\nu_\varrho}[\mathrm{Cor}_{\mu, \delta}^{B+}(\eta_t)^2] \vee \mathbf E_{\nu_\varrho}\big[\mathrm{Cor}_{\mu, \delta}^{B+}(\eta_0)^2\big] = \|\mathrm{Cor}_{\mu, \delta}^{B+}\|^2 \lesssim t \, .
\end{equ}
The last term in~\eqref{e:DiffProof} can be bounded by using the Itô trick bound~\eqref{e:IL2} together with~\eqref{e:AnsatzDiffGenASEP},
\begin{equ} \label{e:DiffProof2}
\limsup_{\delta \to 0} \mathbf E_{\nu_\varrho}[W_t(L \, \mathrm{Cor}_{\mu, \delta}^{B+} + B_+ \mathcal{V}^\delta)^2] \lesssim_\varepsilon t \log_*(t)^{1/3 + 2 \varepsilon} \, .
\end{equ}
Finally, by using the classical identity $\mathbf E_{\nu_\varrho}[M_t(f)^2] = 2 \, t \, \|(- S)^{1/2} f\|^2$ (see~\cite[Section 2.4]{KLO}) together with~\eqref{e:AnsatzDiffH1ASEP}, we obtain
\begin{equ} \label{e:DiffProof3}
\limsup_{\delta \to 0} \big|\mathbf E_{\nu_\varrho}[M_t(\mathrm{Cor}_{\mu, \delta}^{B+})^2] - d^{\lim} \, t \log_*(t)^{2/3}| \lesssim_\varepsilon t \log_*(t)^{1/3 + 2 \varepsilon} \, .
\end{equ}
By gathering~\eqref{e:DiffProof},~\eqref{e:DiffProof1},~\eqref{e:DiffProof2},~\eqref{e:DiffProof3}, we deduce
\begin{equ}
\limsup_{\delta \to 0} \Big|\frac{1}{t} \, \mathbf E_{\nu_\varrho}\Big[\Big(\int_0^t B_+ \mathcal{V}^\delta(\eta_s) \, \mathrm{d} s\Big)^2\Big] - d^{\lim} \log_*(t)^{2/3}\Big| \lesssim_\varepsilon \log_*(t)^{1/2 + \varepsilon} \, ,
\end{equ}
which, in view of Lemma~\ref{lem:GKneat}, establishes~\eqref{e:DiffStrong} and concludes the proof.

\label{lem:Diag}
We define, for any positive diagonal operator ${\mathfrak D}$ on $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ with kernel $(d_n)_{n \geq 0}$ and any $\phi, \psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$,
\begin{equs} \label{e:Diag}
\langle {\mathfrak D} {\mathfrak A}_+ \phi, {\mathfrak A}_+ \psi\rangle_{\mathrm{diag}} \stackrel{\mbox{\tiny\rm def}}{=} \sum_{n \geq 0} n! \, \int_{\mathbb{R}^{2n}} &\mathrm{d} k_{1:n} \, {\mathfrak F} \phi(k_{1:n}) \,  \overline{{\mathfrak F} \psi(k_{1:n})} \\
&\times \frac{1}{2} \sum_{i=1}^n (\mathfrak{e} \cdot k_i)^2 \ \frac{\lambda^2 \varrho(1-\varrho)}{\pi^2} \int_{\mathbb{R}^2} \mathrm{d} p \, \Pi_{p,k_i-p} \, d_{n+1}(p, k_i - p, k_{1:n \setminus i}) \, .
\end{equs}
We also define $\langle {\mathfrak D} {\mathfrak A}_+^{\bullet} \phi, {\mathfrak A}_+^{\bullet} \psi\rangle_{\mathrm{diag}}$ for $\bullet \in \{\sharp, \flat\}$ by adding a factor $\chi^{\bullet}(p, k_i - p ; k_{1:n})$ in the last integrand. Then, for any $\bullet \in \{\emptyset,\sharp, \flat\}$, it holds
\begin{equ}
\langle {\mathfrak D} {\mathfrak A}_+^{\bullet} \phi, {\mathfrak A}_+^{\bullet} \phi \rangle \lesssim \langle {\mathfrak N}^2 \, {\mathfrak D} \, {\mathfrak A}_+^{\bullet} \phi, {\mathfrak A}_+^{\bullet} \phi\rangle_{\mathrm{diag}} \, . \label{e:CSDiag}
\end{equ}
Moreover, when $\bullet = \sharp$, we have
\begin{equ}
\langle {\mathfrak D} {\mathfrak A}_+^{\sharp} \phi, {\mathfrak A}_+^{\sharp} \psi \rangle = \langle {\mathfrak D} {\mathfrak A}_+^{\sharp} \phi, {\mathfrak A}_+^{\sharp} \psi\rangle_{\mathrm{diag}} \, .\label{e:SharpDiag}
\end{equ}

It is clearly sufficient to prove the claims for $\phi = \psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}, n}
    \else
        \Gamma H^{}_{{\mathrm{rap}}, n}
    \fi
$ and any $n \geq 1$. Let $\bullet \in \{\emptyset, \sharp, \flat\}$ and write ${\mathfrak A}_+^\bullet \phi$ in the form $\sum_{1 \leq i < j \leq n+1} {\mathfrak A}_+^{\bullet,i,j} \, \phi$ as suggested by~\eqref{e:fA+} or~\eqref{e:fA+Sharp}. The key observation is the following computation (we use the convention $\chi^\emptyset \equiv 1$)
\begin{equs}
\ &\sum_{1 \leq i < j \leq n+1} \langle {\mathfrak D} {\mathfrak A}_+^{\bullet, i, j} \phi, {\mathfrak A}_+^{\bullet, i, j} \phi \rangle \quad \\
&= \sum_{1 \leq i < j \leq n+1} (n+1)! \, \frac{\varrho(1 - \varrho)}{\pi^2 (n+1)^2} \int_{\mathbb{R}^{2(n+1)}} \mathrm{d} k_{1:n+1} \, d_{n+1}(k_{1:n+1}) \, \chi^\bullet(k_i, k_j ; k_i + k_j, k_{1:n+1 \setminus i, j}) \, \Pi_{k_i, k_j} \, \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad  \qquad \qquad \qquad \qquad \times |\mathfrak{w} \cdot (k_i + k_j)|^2 \, |{\mathfrak F} \phi(k_i + k_j, k_{1:n+1 \setminus i, j})|^2 \\
&= \frac{n(n+1)}{2} \ (n+1)! \, \frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2 (n+1)^2} \int_{\mathbb{R}^{2n}} \mathrm{d} q_{1:n} \int_{\mathbb{R}^2} \mathrm{d} p \, d_{n+1}(p, q_1 - p, q_{2:n}) \, \chi^\bullet(p, q_1 - p ; q_{1:n}) \, \Pi_{p, q_1 - p} \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad  \qquad \qquad \qquad \qquad \times \, |\mathfrak{e} \cdot q_1|^2 \, |{\mathfrak F} \phi(q_{1:n})|^2 \\
&= \langle {\mathfrak D} {\mathfrak A}_+^\bullet \phi, {\mathfrak A}_+^\bullet \phi \rangle_{\mathrm{diag}} \, , 
\end{equs}
where in the second equality we made the change of variables $q_{1:n} = (k_i + k_j, k_{1:n \setminus i, j})$ and $p = k_i$, and in the last equality we noticed that the sum over $i$ in~\eqref{e:Diag} can be replaced by $n$ times the summand $i=1$ because $\phi$ is symmetric.
\smallskip

In particular, using the Cauchy-Schwarz inequality, we deduce
\begin{equs} \label{e:BracketDiag}
\langle {\mathfrak D} {\mathfrak A}_+^\bullet \phi, {\mathfrak A}_+^\bullet \phi \rangle = \Big\|{\mathfrak D}^{1/2} \sum_{1 \leq i < j \leq n+1} {\mathfrak A}_+^{\bullet, i, j} \phi\Big\|^2 &\leq n(n+1) \sum_{1 \leq i < j \leq n+1} \|{\mathfrak D}^{1/2} \, {\mathfrak A}_+^{\bullet, i, j} \phi\|^2 \\
&= n(n+1) \, \langle {\mathfrak D} {\mathfrak A}_+^\bullet \phi, {\mathfrak A}_+^\bullet \phi\rangle_{\mathrm{diag}} \, ,
\end{equs}
which shows~\eqref{e:CSDiag}.

As for the proof of~\eqref{e:SharpDiag}, we first write
\begin{equ}
\langle {\mathfrak D} {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi \rangle =  \sum_{i < j} \langle {\mathfrak D} {\mathfrak A}_+^{\sharp, i, j} \phi, {\mathfrak A}_+^{\sharp, i, j} \psi \rangle +  \sum_{i < j, \, i' < j', \, (i,j) \ne (i', j')} \langle {\mathfrak D} {\mathfrak A}_+^{\sharp, i, j} \phi, {\mathfrak A}_+^{\sharp, i', j'} \psi \rangle \, .
\end{equ}
By the previous computation, the first sum equals $\langle {\mathfrak D} {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi\rangle_{\mathrm{diag}}$. As for the second sum, observe that each term can be written as an integral over $k_{1:n+1} \in \mathbb{R}^{2(n+1)}$ whose integrand is proportional to
\begin{equ} \label{e:OffDiagCancellation}
\chi^\sharp(k_i, k_j ; k_{1:n+1 \setminus i,j}, k_i + k_j) \, \chi^\sharp(k_{i'}, k_{j'} ; k_{1:n+1 \setminus i',j'}, k_{i'} + k_{j'}) \, .
\end{equ}
But the first (resp. second) indicator imposes that $k_i$ and $k_j$ (resp. $k_i'$ and $k_j'$) have the two largest norms among $k_1, \dots k_{n+1}$. Therefore~\eqref{e:OffDiagCancellation} always vanishes if $\{i,j\} \ne \{i',j'\}$, which shows~\eqref{e:SharpDiag}.

\label{lem:ReplLemmaGeneral}
Let $f \colon \mathbb{R}_+ \to \mathbb{R}_+$ and $g \colon \mathbb{R}_+ \to \mathbb{R}_+$ be $C^1$ functions such that for some constants $C_f, C_g \geq 1$ and for every $x > 0$ it holds
\begin{equ} \label{e:AssReplLemma}
\frac{|f'(x)|}{1 + f(x)} \leq \frac{C_f}{x} \, , \quad \frac{g(x)}{1 + f(x)} \leq C_g \, , \quad \frac{|g'(x)|}{1 + f(x)} \leq \frac{C_g}{x} \, .
\end{equ}
Then, with the notations~\eqref{e:XiNotation}, for every $\bullet \in \{\emptyset, \sharp\}$, $k_{1:n} \in \mathbb{R}^{2n}$ ($n \geq 1$), $1 \leq i \leq n$, $\mu > 0$, we have
\begin{equs}
\label{e:FirstReplLemmaInt}
\Big|&\frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2} \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\chi^\bullet(...) \, \Pi_{p, k_i - p}}{\mu + \Xi +  f(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e}} - J(f) \, (\mathrm{Log}(\mu + |k_{1:n}|^2/2))\Big| \lesssim C_f  \, , \\
\label{e:SecondReplLemmaInt}
\Big|&\frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2} \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\chi^\bullet(...) \, \Pi_{p, k_i - p} \ g(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e}}{(\mu + \Xi + f(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e})^2} - J'(f;g) \, (\mathrm{Log}(\mu + |k_{1:n}|^2/2))\Big| \lesssim C_f \, C_g \, , \qquad \ \
\end{equs}
where the functions $J(f), \, J'(f; g) \colon \mathbb{R}_+ \to \mathbb{R}_+$ are given by (recall that $C_\Upsilon = \frac{\lambda^2 \varrho(1 - \varrho)}{\pi}$)
\begin{equ} \label{e:Jint}
J(f) \, (x) \stackrel{\mbox{\tiny\rm def}}{=} \int_0^x \frac{C_\Upsilon \, \mathrm{d} \ell}{(\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \, f(\ell))^{1/2}} \, , \quad J'(f;g) \, (x) \stackrel{\mbox{\tiny\rm def}}{=} \frac{1}{2} \int_0^x \frac{C_\Upsilon \, D_0[\mathfrak{f}, \mathfrak{f}] \, g(\ell) \, \mathrm{d} \ell}{(\det(D_0) + D_0[\mathfrak{f},\mathfrak{f}] \, f(\ell))^{3/2}} \, .
\end{equ}
In particular, we deduce, for any $\mu > 0$ and $\phi, \psi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$,
\begin{equs}
\label{e:FirstReplLemma}
\big|&\langle (\mu - {\mathfrak S} - {\mathfrak L}_0^\mathfrak{e}[f]_\mu)^{-1} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi \rangle - \langle - {\mathfrak L}_0^\mathfrak{e}[J(f)]_\mu \, \phi, \psi \rangle\big| \lesssim C_f \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \psi\| \, , \qquad \ \\
\label{e:SecondReplLemma}
\big|&\langle - {\mathfrak L}_0^\mathfrak{e}[g]_\mu \, (\mu - {\mathfrak S} - {\mathfrak L}_0^\mathfrak{e}[f]_\mu)^{-2} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi \rangle - \langle - {\mathfrak L}_0^\mathfrak{e} [J'(f;g)]_\mu \, \phi, \psi \rangle\big| \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \lesssim C_f \, C_g \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \,  \|((- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \psi\| \, .
\end{equs}
Finally, the assumptions~\eqref{e:AssReplLemma} are satisfied by the functions $(f, g) = (\Upsilon_\nu, \tilde \Upsilon_\nu^\theta)$, for any $\nu \geq 0$ and $\theta \in (0,1]$, with constants $C_f, C_g$ that only depend on $D_0$ and $\lambda$; and it holds
\begin{equ} \label{e:JJ'Ups}
J(\Upsilon_\nu) = \Upsilon_\nu - \nu \, , \quad J'(\Upsilon_\nu ; \tilde \Upsilon_\nu^\theta) = \frac{1}{2 \theta} \, \big(\tilde \Upsilon_\nu^\theta - (\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \nu)^\theta\big) \, .
\end{equ}

We emphasize that the two integrals appearing in~\eqref{e:FirstReplLemmaInt} and~\eqref{e:SecondReplLemmaInt} are tightly connected: more precisely, if we denote them by $I_1(f)$ and $I_2(f ; g)$, then it holds $I_2(f ; g) = - \mathchoice
              {\setbox1\hbox{${\displaystyle \frac{\partial}{\partial \delta}}_{\scriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\textstyle \frac{\partial}{\partial \delta}}_{\scriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\scriptstyle \frac{\partial}{\partial \delta}}_{\scriptscriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\scriptscriptstyle \frac{\partial}{\partial \delta}}_{\scriptscriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}} \, I_1(f + \delta g)$. Similarly, note that we have $J'(f;g) = - \mathchoice
              {\setbox1\hbox{${\displaystyle \frac{\partial}{\partial \delta}}_{\scriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\textstyle \frac{\partial}{\partial \delta}}_{\scriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\scriptstyle \frac{\partial}{\partial \delta}}_{\scriptscriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}}
              {\setbox1\hbox{${\scriptscriptstyle \frac{\partial}{\partial \delta}}_{\scriptscriptstyle \delta = 0}$}
              {\frac{\partial}{\partial \delta}\,\smash{\vrule height .8\ht1 depth .85\dp1}}_{\,\delta = 0}} \, J(f + \delta g)$. In particular, the factor $1/2$ in the definition of $J'(f;h)$ comes from the differentiation of the square root in the formula of $J(f)$. In fact, this factor $1/2$ is crucial: indeed, it reappears in~\eqref{e:ReplContraction} and gives a strict contraction estimate (provided $\theta > 1/2$).

\smallskip

First, by applying~\eqref{e:FirstReplLemma} with $f = \Upsilon_\nu$ and using~\eqref{e:JJ'Ups}, we deduce
\begin{equ}
|\langle (\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \psi \rangle - \langle - {\mathfrak L}_0^\mathfrak{e}[\Upsilon_\nu]_\mu \, \phi, \psi\rangle| \lesssim (1 + \nu) \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \phi\| \, \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \psi\| \, ,
\end{equ}
which gives the desired bound~\eqref{e:ReplFixPt}.
\smallskip

Second, by applying~\eqref{e:SecondReplLemma} with $(f, g) = (\Upsilon_\nu, \tilde \Upsilon_\nu^\theta)$ and using~\eqref{e:JJ'Ups}, we deduce
\begin{equs}
\langle - {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon_\nu^\theta\big]_\mu \, (\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-2} \, &{\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi \rangle \\
&\leq \frac{1}{2 \theta} \langle - {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon_\nu^\theta\big]_\mu \, \phi, \phi \rangle + \Big(C - \frac{(\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \nu)^\theta}{2 \theta}\Big) \langle - {\mathfrak L}_0^\mathfrak{e} \, \phi, \phi\rangle \, ,
\end{equs}
for some constant $C > 0$ (that only depends on $D_0$ and $\lambda$). Then, we deduce the desired bound~\eqref{e:ReplContraction} by assuming $\nu \geq \nu_1$ with $\nu_1$ sufficiently large to make the last term non-positive for every $\theta \in [0,1]$.

First, we prove the claim relative to the particular case $(f,g) = (\Upsilon_\nu, \tilde \Upsilon_\nu^\theta)$. From the formulas~\eqref{e:ODEexplicit} and~\eqref{e:Upstheta}, it is easily checked that the assumption~\eqref{e:AssReplLemma} holds with some constants $C_f$ and $C_g$ that depend only on $D_0$ and $\lambda$. Next, the identity $J(\Upsilon_\nu) = \Upsilon_\nu - \nu$ readily follows from the ODE~\eqref{e:ODE} solved by $\Upsilon_\nu$. Finally, by making the change of variables $y = \det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \Upsilon_\nu(\ell)$ (note that $\mathrm{d} y = \frac{C_\Upsilon \, D_0[\mathfrak{f}, \mathfrak{f}]}{\sqrt{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \Upsilon_\nu(\ell)}} \, \mathrm{d} \ell$ by the ODE~\eqref{e:ODE}), we obtain
\begin{equ}
J'(\Upsilon_\nu ; \tilde \Upsilon_\nu^\theta) \, (x) = \frac{1}{2} \int_{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \, \nu}^{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \, \Upsilon_\nu(x)} y^{\theta - 1} \, \mathrm{d} y = \frac{1}{2 \theta} \, \big[\tilde \Upsilon_\nu^\theta(x) - (\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \nu)^\theta\big] \, ,
\end{equ}
which concludes the proof of~\eqref{e:JJ'Ups}.
\smallskip

Now, we notice that the two statements~\eqref{e:FirstReplLemma} and~\eqref{e:SecondReplLemma} directly follow from the identity~\eqref{e:SharpDiag} and the integral estimates~\eqref{e:FirstReplLemmaInt} and~\eqref{e:SecondReplLemmaInt} (with $\bullet = \sharp$), used together with the identity~\eqref{e:SharpDiag}.
\smallskip

Hence, it only remains to show~\eqref{e:FirstReplLemmaInt} and~\eqref{e:SecondReplLemmaInt}. To do so, we divide~\eqref{e:FirstReplLemmaInt} into the following two claims
\begin{equ}
\Big|\int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\chi^\bullet(...) \, \Pi_{p, k_i - p}}{\mu + \Xi + f(\mathrm{Log}(\mu + \Xi_0)) \Xi_0^\mathfrak{e}} - \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1}}{|\sqrt{D_0} \, p|^2 + f(\mathrm{Log}(|p|^2)) \, |\mathfrak{e} \cdot p|^2} \Big| \lesssim C_f \, , \label{e:FirstReplLemmaTechnical}
\end{equ}
\begin{equ}
\frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2} \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1}}{|\sqrt{D_0} \, p|^2 + f(\mathrm{Log}(|p|^2)) |\mathfrak{e} \cdot p|^2} = J(f) \, (\mathrm{Log}(\mu + |k_{1:n}|^2/2)) \, , \label{e:FirstReplLemmaExact}
\end{equ}
and, similarly, we divide~\eqref{e:SecondReplLemmaInt} into the following two claims
\begin{equ}
\Big|\int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\chi^\bullet(...) \, \Pi_{p, k_i - p} \ g(\mathrm{Log}(\mu + \Xi_0)) \Xi_0^\mathfrak{e}}{(\mu + \Xi + f(\mathrm{Log}(\mu + \Xi_0)) \Xi_0^\mathfrak{e})^2} - \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} \ g(\mathrm{Log}(|p|^2)) |\mathfrak{e} \cdot p|^2}{(|\sqrt{D_0} \, p|^2 + f(\mathrm{Log}(|p|^2)) \, |\mathfrak{e} \cdot p|^2)^2} \Big| \lesssim C_f \, C_g \, , \label{e:SecondReplLemmaTechnical}
\end{equ}
\begin{equ}
\frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2} \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} \ g(\mathrm{Log}(|p|^2)) |\mathfrak{e} \cdot p|^2}{(|\sqrt{D_0} \, p|^2 + f(\mathrm{Log}(|p|^2)) \, |\mathfrak{e} \cdot p|^2)^2} = J'(f; g) \, (\mathrm{Log}(\mu + |k_{1:n}|^2/2)) \, . \label{e:SecondReplLemmaExact}
\end{equ}

We start with the proof of~\eqref{e:FirstReplLemmaExact}. We first change to polar coordinates (in particular, we denote $e_\theta := (\cos \theta, \sin \theta)^T$), then we use the identity
\relax{More generally, for any positive-definite symmetric $2 \times 2$ matrix $S$ we have $\int_0^{2 \pi} \frac{\mathrm{d} \theta}{e_\theta^T S e_\theta} = \frac{2 \pi}{\sqrt{\det(S)}}$, which can easily be seen by computing the Gaussian integral $\int_{\mathbb{R}^2} \exp(- p^T S p/2) \, \mathrm{d} p = \frac{2 \pi}{\sqrt{\det(S)}}$ in polar coordinates.}
$\int_0^{2 \pi} \frac{\mathrm{d} \theta}{e_\theta^T (D_0 + A \mathfrak{e} \mathfrak{e}^T) \, e_\theta} = \frac{2 \pi}{\sqrt{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] A}}$ for any $A \geq 0$, and finally we make the change of variables $\ell = \mathrm{Log}(r^2)$ (notice that formally $\mathrm{d} \ell = \frac{2 \, \mathrm{d} r}{r}$), which gives
\begin{equs}
\int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1}}{|\sqrt{D_0} \, p|^2 + f(\mathrm{Log}(|p|^2)) |\mathfrak{e} \cdot p|^2} &= \int_{\sqrt{\mu + |k_{1:n}|^2/2}}^1 r \, \mathrm{d} r \, \int_0^{2 \pi} \frac{\mathrm{d} \theta}{r^2 \ e_\theta^T \, (D_0 + f(\mathrm{Log}(r^2)) \, \mathfrak{e} \mathfrak{e}^T) \, e_\theta} \\
&= \int_{\sqrt{\mu + |k_{1:n}|^2/2}}^1 \frac{\mathrm{d} r}{r} \, \frac{2 \pi}{\sqrt{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \, f(\mathrm{Log}(r^2))}} \\
&= \pi \int_0^{\mathrm{Log}(\mu + |k_{1:n}|^2/2)} \frac{\mathrm{d} \ell}{\sqrt{\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] \, f(\ell)}} \, \, ,
\end{equs}
which leads to~\eqref{e:FirstReplLemmaExact} (multiplying both sides by $\frac{\lambda^2 \varrho(1 - \varrho)}{\pi^2}$).

The formula~\eqref{e:SecondReplLemmaExact} can be proved similarly: we pass to polar coordinates, use the identity $\int_0^{2 \pi} \frac{\mathrm{d} \theta \, e_\theta^T \mathfrak{e} \mathfrak{e}^T e_\theta}{(e_\theta^T (D_0 + A \mathfrak{e} \mathfrak{e}^T) \, e_\theta)^2} = \frac{D_0[\mathfrak{f}, \mathfrak{f}]}{2} \, \frac{2 \pi}{(\det(D_0) + D_0[\mathfrak{f}, \mathfrak{f}] A)^{3/2}}$ for any $A \geq 0$ (which can be derived by differentiating the previous identity with respect to $A$), and use the change of variables $\ell = \mathrm{Log}(r^2)$.
\smallskip

Thus we are left to prove the bounds~\eqref{e:FirstReplLemmaTechnical} and~\eqref{e:SecondReplLemmaTechnical}. In both cases, we want to show
\begin{equs} \label{e:ReplLemmaPhi}
\Big|\int_{\mathbb{R}^2} \mathrm{d} p \, \chi^\bullet(...) \, &\Pi_{p, k_i - p} \, \Phi(\mu + \Xi, \Xi_0^\mathfrak{e}, \mathrm{Log}(\mu + \Xi_0)) \\
&- \int_{\mathbb{R}^2} \mathrm{d} p \, \1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} \, \Phi(|D_0^{1/2} p|^2, |\mathfrak{e} \cdot p|^2, \mathrm{Log}(|p|^2))\Big| \lesssim C \, ,
\end{equs}
where $\Phi(x_1,x_2,x_3)$ and $C$ equal $\frac{1}{x_1 + f(x_3) \, x_2}$ and $C_f$ for~\eqref{e:FirstReplLemmaTechnical}, and equal $\frac{g(x_3) \, x_2}{(x_1 + f(x_3) \, x_2)^2}$ and  $C_f \, C_g$ for~\eqref{e:SecondReplLemmaTechnical} (we fix these notations for the rest of the proof). First, it is easily checked from the assumptions~\eqref{e:AssReplLemma} that, in both cases, $\Phi$ is $C^1$ on $(\mathbb{R}_+^*)^3$ and satisfies, for every $x_1, x_2, x_3 > 0$ and $\alpha \in \{1, 2, 3\}$,
\begin{equ} \label{e:AssumptionPhi}
|\Phi(x_1, x_2, x_3)| \lesssim C_* \, \frac{1 \vee \frac{x_2}{x_1}}{x_1} \, , \quad |\partial_\alpha \Phi(x_1, x_2, x_3)| \lesssim C_* \, \frac{1 \vee \frac{x_2}{x_1}}{x_1 \, x_\alpha} \, ,
\end{equ}
We mention that, in practice, we are only interested in $x_1, x_2, x_3$ such that $x_2 \lesssim x_1$ (roughly speaking, because of the trivial bound $|\mathfrak{e} \cdot q| \leq |q|$), for which we can bound the above numerators as $1 \vee \frac{x_2}{x_1} \lesssim 1$. To prove~\eqref{e:ReplLemmaPhi}, we distinguish the good region 
\begin{equ} \label{e:GoodRegion}
    G := \{p \in \mathbb{R}^2 \colon |\mathfrak{e} \cdot p| > 10 \, \sqrt{\mu + |k_{1:n}|^2} \mbox{ and } |p| < 1/10\}
\end{equ}
and the bad region $B = \mathbb{R}^2 - G$. The idea is the following: on the one hand, the two integrands will be easier to compare on $G$ ; on the other hand, both integrands will give a negligible contribution on $B$. 

Indeed, we can bound the two contributions on the bad region as follows, by using in particular~\eqref{e:AssumptionPhi} and~\eqref{e:Triangular}, 
\begin{equs}
\int_B \mathrm{d} p \, \chi^\bullet(...) \, \Pi_{p, k_i -p} \, |\Phi(\mu + \Xi, \Xi_0^\mathfrak{e}, &\mathrm{Log}(\mu + \Xi))| \vee \int_B \mathrm{d} p \, \1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} \, |\Phi(|D_0^{1/2} p|^2, |\mathfrak{e} \cdot p|^2, \mathrm{Log}(|p|^2))| \\
\lesssim C_* \int_B \mathrm{d} p \, \frac{\1_{|p| \leq 1}}{\mu + |k_{1:n}|^2 + |p|^2} &\leq C_* \int_{\mathbb{R}^2} \frac{\1_{|\mathfrak{e} \cdot p| \leq 10 (\mu + |k_{1:n}|^2)^{1/2}} \, \mathrm{d} p}{\mu + |k_{1:n}|^2 + |p|^2} + C_* \int_{\mathbb{R}^2} \frac{\1_{1/10 \leq |p| \leq 1} \, \mathrm{d} p}{|p|^2} \\
&= C_* \int_{\mathbb{R}^2} \frac{\1_{|\mathfrak{e} \cdot q| \leq 10} \, \mathrm{d} q}{1 + |q|^2} + C_* \int_{\mathbb{R}^2} \frac{\1_{1/10 \leq |p| \leq 1} \, \mathrm{d} p}{|p|^2} \lesssim C_* \, , \label{e:BadRegionBound}
\end{equs}
where we used the change of variable $q = \frac{p}{\sqrt{\mu + |k_{1:n}|^2}}$ in the last line.

Now, we compare the two integrands on $G$. For the rest of this proof, let $p \in G$ so that
\begin{equ} \label{e:GoodRegionBis}
10 \, \sqrt{\mu + |k_{1:n}|^2} < |\mathfrak{e} \cdot p| \leq |p| < 1/10 \, .
\end{equ}
In particular, it is easily checked that
\begin{equ} \label{e:ComparisonGammaBrutal}
\mu + \Xi_0 \asymp \mu + \Xi \asymp |p|^2 \, , \quad \Xi_0^\mathfrak{e} \asymp |\mathfrak{e} \cdot p|^2 \, , \quad |p|^2  \vee (\mu + \Xi_0) \leq e^{-1} \, , \quad \mathrm{Log}(|p|^2) \wedge \mathrm{Log}(\mu + \Xi_0) \geq 1 \, .
\end{equ}
Now we want to finely compare $(\mu + \Xi, \Xi_0^\mathfrak{e}, \mathrm{Log}(\mu + \Xi_0))$ to $(|D_0^{1/2} p|^2, |\mathfrak{e} \cdot p|^2, \mathrm{Log}(|p|^2))$. First, by writing $\Xi_0$ as $\frac{1}{2}(|p|^2 + |p|^2 - 2 \langle k_i, p \rangle + |k_i|^2 + |k_{1:n \setminus i}|^2)$, we deduce
\begin{equ} \label{e:ComparisonGamma0Fine}
|\mu + \Xi_0 - |p|^2| \leq \mu + |k_{1:n}|^2 + 2 |k_i| |p| \lesssim \sqrt{\mu + |k_{1:n}|^2} \, |p| \, ,
\end{equ}
where the last bound comes from~\eqref{e:GoodRegionBis}. Similarly, we have
\begin{equs}
|\mu + \Xi - |D_0^{1/2} p|^2| &\leq \mu + |D_0^{1/2} k_{1:n}|^2 + 2 |D_0^{1/2} k_i| |D_0^{1/2} p| \lesssim \sqrt{\mu + |k_{1:n}|^2} \, |p| \, , \label{e:ComparisonGammaFine} \\
|\Xi_0^\mathfrak{e} - |\mathfrak{e} \cdot p|^2| &\leq \mu + |\mathfrak{e} \cdot k_{1:n}|^2 + 2 |\mathfrak{e} \cdot k_i| |\mathfrak{e} \cdot p| \lesssim \sqrt{\mu + |k_{1:n}|^2} \, |\mathfrak{e} \cdot p| \, . \label{e:ComparisonGammafeFine} 
\end{equs}
Finally, by using the mean value theorem, the fact that $|\mathrm{Log}'(x)| = 1/x$ for $x \in (0, 1)$, and the estimates~\eqref{e:ComparisonGammaBrutal} and~\eqref{e:ComparisonGamma0Fine}, we deduce
\begin{equ} \label{e:ComparisonLGamma0Fine} 
|\mathrm{Log}(\mu + \Xi_0) - \mathrm{Log}(|p|^2)| \lesssim \frac{|\mu + \Xi_0 - |p|^2|}{|p|^2} \lesssim \frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|} \, .
\end{equ}
Now, we replace successively the arguments of $\Phi$ by using the mean value theorem and the estimates~\eqref{e:AssumptionPhi} and~\eqref{e:ComparisonGammaBrutal}, which gives
\begin{equs}
|\Phi(\mu + \Xi, \Xi_0^\mathfrak{e}, \mathrm{Log}(\mu + \Xi_0)) &- \Phi(|D_0^{1/2} p|^2, |\mathfrak{e} \cdot p|^2, \mathrm{Log}(|p|^2))| \\
&\lesssim C_* \Big(\frac{|\mu + \Xi - |D_0^{1/2} p|^2|}{|p|^4} + \frac{|\Xi_0^\mathfrak{e} - |p|^2|}{|p|^2 \, |\mathfrak{e} \cdot p|^2} + \frac{|\mathrm{Log}(\mu + \Xi_0) - \mathrm{Log}(|p|^2)|}{|p|^2}\Big) \\
&\lesssim C_* \Big(\frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^3} + \frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^2 \, |\mathfrak{e} \cdot p|} + \frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^3}\Big) \\
&\lesssim C_* \Big(\frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^2 \, |\mathfrak{e} \cdot p|}\Big) \, ,
\end{equs}
where in the second to last line we used~\eqref{e:ComparisonGammaFine},~\eqref{e:ComparisonGammafeFine} and~\eqref{e:ComparisonLGamma0Fine}. In addition, we notice that we can deduce from~\eqref{e:GoodRegionBis} the following basic estimates
\begin{equ}
|p| > 10 |k_{1:n}| \, , \quad |k_i - p| > 9 |k_{1:n}| \, , \quad |k_{1:n}| < \frac{1}{100} \, , \quad |k_i - p| < \frac{11}{100} \, ,
\end{equ}
which gives $\chi^\sharp(...) = 1$, $\Pi_{p,k_i-p} = 1$, and $\1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} = 1$. Therefore, we deduce
\begin{equs}
\Big|\int_{G} \mathrm{d} p \, \chi^\bullet(...) \, \Pi_{p, k_i - p} \, \Phi(\mu + \Xi, \Xi_0^\mathfrak{e}, &\mathrm{Log}(\mu + \Xi_0)) - \int_{G} \mathrm{d} p \, \1_{\mu + |k_{1:n}|^2/2 < |p|^2 < 1} \, \Phi(|D_0^{1/2} p|^2, |\mathfrak{e} \cdot p|^2, \mathrm{Log}(|p|^2))\Big| \\
\lesssim C_* \int_{G} \mathrm{d} p \, \frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^2 |\mathfrak{e} \cdot p|} &\leq C_* \int_{\mathbb{R}^2} \mathrm{d} p \, \1_{|\mathfrak{e} \cdot p| \geq 10 \sqrt{\mu + |k_{1:n}|^2}} \, \frac{\sqrt{\mu + |k_{1:n}|^2}}{|p|^2 |\mathfrak{e} \cdot p|} \\
&= C_* \int_{\mathbb{R}^2} \mathrm{d} q \, \1_{|\mathfrak{e} \cdot q| \geq 10} \, \frac{1}{|q|^2 |\mathfrak{e} \cdot q|} \lesssim C_* \, ,
\label{e:GoodRegionBound}
\end{equs}
where we used the change of variable $q = p / \sqrt{\mu + |k_{1:n}|^2}$ in the last line, and where the finiteness of the last integral follows from the computation
\begin{equ}
\int_{\mathbb{R}^2} \mathrm{d} q \, \1_{|\mathfrak{e} \cdot q| \geq 10} \, \frac{1}{|q|^2 |\mathfrak{e} \cdot q|} = \int_{\mathbb{R}} \mathrm{d} x \, \1_{|x| \geq 10} \int_{\mathbb{R}} \mathrm{d} y \, \frac{1}{(x^2 + y^2) \, |x|} = \int_{\mathbb{R}} \1_{|x| \geq 10} \, \frac{\pi}{|x|^{3/2}} < +\infty \, .
\end{equ}

By gathering~\eqref{e:GoodRegionBound} and~\eqref{e:BadRegionBound}, we deduce~\eqref{e:ReplLemmaPhi} and conclude the proof.

\label{lem:GA+Contraction}
There exists $\nu_2 \geq 0$ (only depending on $D_0$ and $\lambda$), such that for every $\nu \geq \nu_2$, $\mu > 0$, and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, it holds
\begin{equ} \label{e:GA+Contraction}
\|(\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-1} \, {\mathfrak A}_+^\sharp \phi\| \leq \frac{1}{10} \, \|\phi\| \, .
\end{equ}

By orthogonality of chaoses, it is sufficient to prove the bound for any $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$ and $n \geq 1$. Then, using~\eqref{e:SharpDiag} and the notations~\eqref{e:XiNotation}, we deduce
\begin{equs}
\|(\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-1} \, {\mathfrak A}_+^\sharp \phi\|^2 &= \langle (\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-2} \, {\mathfrak A}_+^\sharp \phi, {\mathfrak A}_+^\sharp \phi \rangle_{\mathrm{diag}} \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{\mathrm{d} p}{(\mu + \Xi + \Upsilon_\nu(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e})^2} \, \\
&\lesssim n! \int_{\mathbb{R}^{2n}} \mathrm{d} k_{1:n} \, |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \int_{\mathbb{R}^2} \frac{\mathrm{d} p}{(|k_{1:n}|^2 + |p|^2 + \nu |\mathfrak{e} \cdot p|^2)^2} \, ,
\end{equs}
where in the last line we used~\eqref{e:Triangular} and the trivial lower bound $\Upsilon_\nu \geq \nu$. A simple change of variables shows that the last integral equals $\frac{C}{(1+\nu)^{1/2} \, |k_{1:n}|^2}$ for some constant $C > 0$. Thus we deduce
\begin{equ}
\|(\mu - {\mathfrak L}_{\mu, \nu}^\mathrm{eff})^{-1} \, {\mathfrak A}_+^\sharp \phi\|^2 \lesssim \frac{1}{(1 + \nu)^{1/2}} \, \|\phi\|^2 \, ,
\end{equ}
which concludes the proof by assuming $\nu \geq \nu_2$ and taking $\nu_2$ sufficiently large.

We show that, for any $\mu > 0$, $a, b \geq 0$, $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{m}
    \else
        \Gamma_0 h^{}_{m}
    \fi
$ ($m \geq 0$) and $n \geq 1$, we have
\begin{equ} \label{e:SummabilityAnsatzPrecise}
\|{\mathfrak N}_*^a \, (1 - {\mathfrak L}_0)^b \, \big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp\big)^n \phi\| \leq 10^{-n} \, (m+n)_*^a \, (1 + 3 \pi^2)^b \, \|\phi\| \, ,
\end{equ}
from which Lemma~\ref{lem:SummabilityAnsatz} easily follows.

First, we deduce by iterating~\eqref{e:GA+Contraction} that
\begin{equ}
\|\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp\big)^n \phi\| \lesssim 10^{-n} \|\phi\| \, .
\end{equ}
It only remains to handle the extra factors ${\mathfrak N}_*^a$ and $(1 - {\mathfrak L}_0)^b$ appearing on the left hand side of~\eqref{e:SummabilityAnsatzPrecise}. First, we observe that $\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp\big)^n \phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{m+n}
    \else
        \Gamma H^{}_{m+n}
    \fi
$, so that the extra factor ${\mathfrak N}_*^a$ in~\eqref{e:SummabilityAnsatzPrecise} contributes as a factor $(m+n)_*
^a$. Second, we observe that, if for some vectors $p, q, k_{1:N} \in \mathbb{R}^2$ it holds
\begin{equ}
\chi^\sharp(p,q ; k_{1:N}) \, \Pi_{p,q} \ne 0 \, ,
\end{equ}
then we must have $|k_{1:N}| \leq |p| \vee |q| \leq \sqrt{2} \, \pi$, which leads to $|p|^2 + |q|^2 + |k_{1:N}|^2 \leq 6 \pi^2$. This shows that, if $\psi \in {\mathfrak A}_+^\sharp(
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
)$, then its Fourier transform is supported on $\{k_{1:N'} \colon |k_{1:N'}|^2 \leq 6 \pi^2, \, N' \geq 0\}$; and the same holds if $\psi \in (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak A}_+^\sharp(
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
)$ since $(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}$ is a diagonal operator. In particular, we deduce that the extra factor $(1 - {\mathfrak L}_0)^b$ in~\eqref{e:SummabilityAnsatzPrecise} can be bounded by $(1 + 3 \pi^2)^b$. This concludes the proof of~\eqref{e:SummabilityAnsatzPrecise}.

First, by iterating~\eqref{e:GA+Contraction}, we deduce that, for every $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$, we have
\begin{equs}
\|\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \phi\| \leq 10^{-n} \, \|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \phi\| \, .
\end{equs}
Now, notice that the operator $\big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}$ maps $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0}
    \fi
$ into $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}, n_0 + n}
    \else
        \Gamma H^{}_{{\mathrm{rap}}, n_0 + n}
    \fi
$ for any $n_0 \geq 0$. Then, by using orthogonality of chaoses and the bound $(n_0 + n)_*^\kappa \, \alpha^{n_0 + n} \leq n_*^\kappa \alpha^n \, (n_0)_*^\kappa \alpha^{n_0}$, we deduce that, for any $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$ and $n \geq 0$, it holds
\begin{equ}
\|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, \big((\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big)^n \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1}  \bm \varphi\| \leq \frac{n_*^\kappa \alpha^n}{10^n} \, \|{\mathfrak N}_{*}^\kappa \alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\| \, .
\end{equ}
By using~\eqref{e:TrueAnsatz}, the triangle inequality, and summing the above bound over $n \geq 0$ (note that $\sum_{n \geq 0} \frac{n_*^\kappa \alpha^n}{10^n} < +\infty$ because $\alpha \leq \sqrt{2}$), we deduce~\eqref{e:AnsatzL2} and conclude the proof.

\label{lem:GenAnsatz}
For every $\mu > 0$ and $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equs} \label{e:GenAnsatz}
(\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_{\mu}(\bm \varphi) &=  \bm \varphi - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi \\
&\ \ + ({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_\mu - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp) \, \mathfrak{Ans}_{\mu}(\bm \varphi) - \bar {\mathfrak A}^\flat \, \mathfrak{Ans}_{\mu}(\bm \varphi) \, .
\end{equs}

To shorten notations, we denote $\mathfrak{s} := \mathfrak{Ans}_{\mu}(\bm \varphi)$ throughout this proof. We write
\begin{equ} \label{e:GenAnsatzComputation}
(\mu - \bar {\mathfrak L}) \, \mathfrak{s} = (\mu - {\mathfrak L}_{\mu}^\mathrm{eff}) \, \mathfrak{s} + {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_{\mu} \, \mathfrak{s} - {\mathfrak A}_+^\sharp \, \mathfrak{s} - {\mathfrak A}_-^\sharp \mathfrak{s} - \bar {\mathfrak A}^\flat \mathfrak{s} \, .
\end{equ}
By using the identity~\eqref{e:AnsatzIdentity} twice, we have
\begin{equs}
(&\mu - {\mathfrak L}_{\mu}^\mathrm{eff}) \, \mathfrak{s} = {\mathfrak A}_+^\sharp \, \mathfrak{s} + \bm \varphi \, , \\
-&{\mathfrak A}_-^\sharp \, \mathfrak{s} = - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp \, \mathfrak{s} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi \, .
\end{equs}
Plugging these two equalities in~\eqref{e:GenAnsatzComputation}, we end up with
\begin{equ} \label{e:GenAnsatzBis}
(\mu - \bar {\mathfrak L}) \, \mathfrak{s} = \bm \varphi + {\mathfrak L}_0^\mathfrak{e}[\Upsilon]_{\mu} \, \mathfrak{s} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp \, \mathfrak{s} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi - \bar {\mathfrak A}^\flat \, \mathfrak{s} \, ,
\end{equ}
which concludes the proof.

\label{lem:Aflat}
For every $\mu > 0$ and $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$, we have
\begin{equ} \label{e:Aflat}
\|(- {\mathfrak L}_0)^{-1/2} \, {\mathfrak A}_+^\flat \phi\| \vee \|(- {\mathfrak L}_0)^{-1/2} \, {\mathfrak A}_-^\flat \phi\| \lesssim \|{\mathfrak N} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, .
\end{equ}

First, by an easy duality argument (and by letting $\mu \searrow 0$), it is sufficient to show for any $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$ and $\mu > 0$
\begin{equ} \label{e:AflatProof}
\langle (\mu - {\mathfrak L}_0)^{-1} \, {\mathfrak A}_+^\flat \phi, {\mathfrak A}_+^\flat \phi \rangle \lesssim \langle {\mathfrak N}^2 (\mu - {\mathfrak L}_0^\mathfrak{e}) \, \phi, \phi \rangle \, , \quad \langle (\mu - {\mathfrak L}_0^\mathfrak{e})^{-1} \, {\mathfrak A}_+^\flat \phi, {\mathfrak A}_+^\flat \phi \rangle \lesssim \langle {\mathfrak N}^2 (\mu - {\mathfrak L}_0) \, \phi, \phi\rangle \, .
\end{equ}
Further, by orthogonality of chaoses, it is sufficient to show the bound for any $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n}
    \fi
$ and $n \geq 1$.
\smallskip

We start with the first bound. Using~\eqref{e:CSDiag} and the notations~\eqref{e:XiNotation}, we obtain
\begin{equs}
\langle (\mu - {\mathfrak L}_0)^{-1} \, {\mathfrak A}_+^\flat \phi, {\mathfrak A}_+^\flat \phi \rangle &\lesssim n^2 \, n! \, \int_{\mathbb{R}^{2n}} \mathrm{d} {k_{1:n}} |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \, \int_{\mathbb{R}^2} \frac{\chi^\flat(p, k_i - p ; k_{1:n}) \, \mathrm{d} p}{\mu + \Xi} \\
&\lesssim n^2 \, n! \, \int_{\mathbb{R}^{2n}} \mathrm{d} {k_{1:n}} |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \, \int_{\mathbb{R}^2} \frac{1_{|p| \leq 4 |k_{1:n}|} \, \mathrm{d} p}{|k_{1:n}|^2} \\
&\lesssim n^2 \, \langle (- {\mathfrak L}_0^\mathfrak{e}) \, \phi, \phi \rangle \, ,
\end{equs}
where in the second line we used~\eqref{e:Triangular} and observed that, if $\chi^\flat(p, k_i - p ; k_{1:n}) = 1$, then either $|p| \leq 3 |k_{1:n}|$ or $|k_i - p| \leq 3 |k_{1:n}|$, so that in both cases it holds $|p| \leq 4 |k_{1:n}|$.

We can prove similarly the second bound. Indeed, by using~\eqref{e:CSDiag} and the notations~\eqref{e:XiNotation}, we obtain
\begin{equs}
\langle (\mu - {\mathfrak L}_0^\mathfrak{e})^{-1} \, {\mathfrak A}_+^\flat \phi, {\mathfrak A}_+^\flat \phi \rangle &\lesssim n^2 \, n! \, \int_{\mathbb{R}^{2n}} \mathrm{d} {k_{1:n}} |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \, \int_{\mathbb{R}^2} \frac{\chi^\flat(p, k_i - p ; k_{1:n}) \, \mathrm{d} p}{\mu + \Xi_0^\mathfrak{e}} \\
&\lesssim n^2 \, n! \, \int_{\mathbb{R}^{2n}} \mathrm{d} {k_{1:n}} |{\mathfrak F} \phi(k_{1:n})|^2 \sum_{i=1}^n |\mathfrak{e} \cdot k_i|^2 \, \int_{\mathbb{R}^2} \frac{1_{|p| \leq 4 |k_{1:n}|} \, \mathrm{d} p}{|\mathfrak{e} \cdot k_{1:n}|^2} \\
&\lesssim n^2 \langle (- {\mathfrak L}_0) \, \phi, \phi\rangle \, .
\end{equs}
This concludes the proof.

First, by~\eqref{e:GenAnsatz} and the triangle inequality, we have
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \, &\big((\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_{\mu}(\bm \varphi) - \bm \varphi + {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi\big)\| \\
&\leq \|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \big({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_{\mu} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big) \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \\
&\quad + \|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \, \bar {\mathfrak A}^\flat \, \mathfrak{Ans}_{\mu}(\bm \varphi)\| \, , \label{e:AnsatzGenComputation}
\end{equs}
Now, observe that we immediately deduce, respectively from~\eqref{e:ReplFixPt} and~\eqref{e:Aflat}, that for any $\phi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
$
\begin{equs}
\|{\mathfrak N}_{*}^{\kappa} \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \big({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_{\mu} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak A}_+^\sharp\big) \, \phi\| &\lesssim_{\kappa, \alpha} \|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, , \\
\|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \, \bar {\mathfrak A}^\flat \, \phi\| &\lesssim_{\kappa, \alpha} \|{\mathfrak N}_{*}^{\kappa + 1} \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \phi\| \, .
\end{equs}
By taking $\phi = \mathfrak{Ans}_{\mu}(\bm \varphi)$ and using~\eqref{e:AnsatzH1fe}, we deduce
\begin{equs}
\|{\mathfrak N}_{*}^\kappa \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0)^{-1/2} \, [(\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_{\mu}(\bm \varphi) &- \bm \varphi + {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi]\| \\
&\lesssim_{\kappa, \alpha} \|{\mathfrak N}_{*}^{\kappa + 1} \alpha^{{\mathfrak N}} \, (- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\| \, ,
\end{equs}
which readily shows~\eqref{e:AnsatzGen}.

Let $\bar {\mathfrak L}^\sharp := {\mathfrak S} + \bar {\mathfrak A}^\sharp = \bar {\mathfrak L} - \bar {\mathfrak A}^\flat$. We observe that the symmetric part of $\bar {\mathfrak L}^\sharp$ is given by ${\mathfrak S}$ (on $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}}}
    \else
        \Gamma H^{}_{{\mathrm{rap}}}
    \fi
 \subset 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{}
    \else
        \Gamma H^{}_{}
    \fi
$), so that we deduce
\begin{equs}
\|(\mu - {\mathfrak S})^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\|^2 &= \langle (\mu - \bar {\mathfrak L}^\sharp) \, \mathfrak{Ans}_{\mu}(\bm \varphi), \mathfrak{Ans}_{\mu}(\bm{\varphi}) \rangle \, , \\
&= \langle \bm \varphi, \mathfrak{Ans}_{\mu}(\bm \varphi) \rangle \\
&\quad + \langle - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi, \mathfrak{Ans}_{\mu}(\bm \varphi) \rangle \\
&\quad + \langle ({\mathfrak L}_0^\mathfrak{e}[\Upsilon]_{\mu} - {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak A}_+^\sharp) \, \mathfrak{Ans}_{\mu}(\bm \varphi), \mathfrak{Ans}_{\mu}(\bm \varphi) \rangle \, , \\
&=: \mathrm{(I)} + \mathrm{(II)} + \mathrm{(III)}
\end{equs}
where we used Lemma~\ref{lem:GenAnsatz} in the second line. We recall that we assume $\bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{{\mathrm{rap}},n_0}
    \else
        \Gamma H^{}_{{\mathrm{rap}},n_0}
    \fi
$ for some $n_0 \geq 0$; in particular, the summand of index $n$ in the definition~\eqref{e:TrueAnsatz} of the Ansatz belongs to $
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n_0 + n}
    \else
        \Gamma H^{}_{n_0 + n}
    \fi
$. On the one hand, we deduce that only the summand $n=0$ contributes in $\mathrm{(I)}$ so that
\begin{equ}
\mathrm{(I)} = \langle \bm \varphi, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \bm \varphi \rangle = \|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1/2} \bm \varphi\|^2 \, .
\end{equ}
On the other hand, we deduce that $\mathrm{(II)} = 0$ because $- {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{n_0 - 1}
    \else
        \Gamma H^{}_{n_0 - 1}
    \fi
$. Finally, we can bound $\mathrm{(III)}$ by using the first replacement lemma~\eqref{e:ReplFixPt}, as follows
\begin{equ}
|\mathrm{(III)}| \lesssim \|(- {\mathfrak L}_0^\mathfrak{e})^{1/2} \, \mathfrak{Ans}_{\mu}(\bm \varphi)\|^2 \lesssim \|(-{\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} \bm \varphi\|^2 \, ,
\end{equ}
where in the last bound we used~\eqref{e:AnsatzH1fe}. Gathering the previous results, we deduce~\eqref{e:AnsatzH1precise} and conclude the proof.

\label{lem:InputB+}
For every $\mu \geq 0$, $\delta \in (0,1]$, $\theta \in (0,1]$, $\gamma \in (0,1]$, it holds
\begin{equs}
\sqrt{\mu} \, \|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\| &\lesssim 1 \, , \label{e:InputB+L2} \\
\|(- {\mathfrak L}_0^\mathfrak{e}\big[\tilde \Upsilon^\theta\big]_\mu)^{1/2} (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\| &\lesssim_{\theta} \log_{*}(1/\mu)^{\theta / 3} \, , \label{e:InputB+H1e}\\
\|(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\| &\lesssim_\gamma 1 \, , \label{e:InputB+H1gamma} \\
\limsup_{\delta \to 0} \Big|\|(\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1/2} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 - \frac{d^{\lim}}{2} \log_{*}(&1/\mu)^{2/3}\Big| \lesssim 1 \, , \label{e:InputB+H1} \\
\|{\mathfrak A}_0 \mathcal{V}^\delta\| \xrightarrow[\delta \to 0]{} 0 \, ,  \quad \|{\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak B}_+ &\mathcal{V}^\delta\| \xrightarrow[\delta \to 0]{} 0 \, , \label{e:InputB+A-A0}
\end{equs}

In this proof, we repeatedly use the following fact: for any positive diagonal operator ${\mathfrak D}$ with kernel $d(\cdot)$ it holds
\begin{equs}
\|{\mathfrak D}^{1/2} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 &= \langle {\mathfrak D} \, {\mathfrak B}_+ \mathcal{V}^\delta, {\mathfrak B}_+ \mathcal{V}^\delta\rangle \\
&= \frac{\lambda^2 \varrho (1-\varrho)}{2 \pi^2} \int_{\mathbb{R}^2} \mathrm{d} k \, |{\mathfrak F} \mathcal{V}^\delta(k)|^2 \, \int_{\mathbb{R}^2} \mathrm{d} p \, \Pi_{p, k-p} \, d(p,k-p) \, \label{e:B+Diag} \\
&\lesssim \sup_{k \in B(0, \delta)} \, \int_{\mathbb{R}^2} \mathrm{d} p \, \Pi_{p, k-p} \, d(p,k-p) \, , \label{e:B+DiagBound}
\end{equs}
where in the last line we used that $\|\mathcal{V}^\delta\|_{L^2(\mathbb{R}^2)} = 1$ and $\mathrm{Supp}({\mathfrak F} \mathcal{V}^\delta) \subset B(0, \delta)$ (recall Definition~\ref{def:V}).
\smallskip

We start with~\eqref{e:InputB+L2}. By using the trivial bound $- {\mathfrak L}_{\mu}^\mathrm{eff} \geq - \|D_0^{-1}\|^{-1} {\mathfrak L}_0$ and~\eqref{e:B+DiagBound}, we deduce
\begin{equ}
\|(\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\|^2 \lesssim \|(\mu - {\mathfrak L}_0)^{-1} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 \lesssim \int_{\mathbb{R}^2} \frac{\mathrm{d} p}{\mu + |p|^2} \lesssim \mu^{-1} \, .
\end{equ}

We turn to~\eqref{e:InputB+H1e}. By using~\eqref{e:B+DiagBound}, the notations~\eqref{e:XiNotation} (with $k_{1:n} = k$),~\eqref{e:SecondReplLemmaInt} with $(f,g) = (\Upsilon, \tilde \Upsilon^\theta)$ and~\eqref{e:JJ'Ups}, we deduce
\begin{equs}
\|(- {\mathfrak L}_0^\mathfrak{e}[\tilde \Upsilon^\theta]_\mu)^{1/2} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 &\lesssim \sup_{k \in B(0, \delta)} \int_{\mathbb{R}^2} \mathrm{d} p \, \frac{\Pi_{p,k-p} \, \tilde \Upsilon^\theta(\mathrm{Log}(\mu + \Xi_0))}{(\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \Xi_0^\mathfrak{e})^2} \\
&\lesssim_\theta \sup_{k \in B(0, \delta)} \tilde \Upsilon^\theta(\mathrm{Log}(\mu + |k|^2/2)) + 1 \, , \\
&\lesssim \log_{*}(1/\mu)^{2 \theta / 3} \, .
\end{equs}

We continue with~\eqref{e:InputB+H1gamma}. By using the trivial bound $- {\mathfrak L}_{\mu}^\mathrm{eff} \geq - \|D_0^{-1}\|^{-1} {\mathfrak L}_0$,~\eqref{e:B+DiagBound}, and recalling that $\gamma \in (0,1]$, we deduce
\begin{equ}
\|(\mu - {\mathfrak L}_0)^{(1+\gamma)/2} \, (\mu - {\mathfrak L}_{\mu}^\mathrm{eff})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\|^2 \lesssim \|(\mu - {\mathfrak L}_0)^{(-1+\gamma)/2} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 \lesssim \int_{\mathbb{R}^2} \frac{\1_{|p|_\infty \leq \pi} \, \mathrm{d} p}{ |p|^{2 - 4 \gamma}} \lesssim_\gamma 1 \, .
\end{equ}

We tackle~\eqref{e:InputB+H1}. By using~\eqref{e:B+Diag} and the notations~\eqref{e:XiNotation} (with $k_{1:n} = k$), we can write
\begin{equ} \label{e:InputB+H1detail}
\|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1/2} {\mathfrak B}_+ \mathcal{V}^\delta\|^2 = \int_{\mathbb{R}^2} \mathrm{d} k \, |{\mathfrak F} \mathcal{V}^\delta(k)|^2 \, \frac{\lambda^2 \varrho (1-\varrho)}{2 \pi^2} \int_{\mathbb{R}^2} \frac{\mathrm{d} p \, \Pi_{p, k - p}}{\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e}} \, .
\end{equ}
Then, we evaluate the last integral by using~\eqref{e:SecondReplLemmaInt} with $f = \Upsilon$ and~\eqref{e:JJ'Ups}, which leads to
\begin{equ}
\Big|\frac{\lambda^2 \varrho(1-\varrho)}{2 \pi^2} \int_{\mathbb{R}^2} \frac{\mathrm{d} p \, \Pi_{p, k - p}}{\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e}} - \frac{1}{2} \, \Upsilon(\mathrm{Log}(\mu + |k|^2/2))\Big| \lesssim 1 \, .
\end{equ}
Then, by using~\eqref{e:AsymptoticUps} and the trivial fact $\Upsilon(\mathrm{Log}(\mu + |k|^2/2)) \to \Upsilon(L(\mu))$ as $k \to 0$, we deduce
\begin{equ}
\limsup_{\delta \to 0} \sup_{k \in B(0, \delta)} \Big|\frac{\lambda^2 \varrho(1-\varrho)}{2 \pi^2} \int_{\mathbb{R}^2} \frac{\mathrm{d} p \, \Pi_{p, k - p}}{\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e}} - \frac{d^{\lim}}{2} \log_{*}(1/\mu)^{2/3} \Big| \lesssim 1 \, .
\end{equ}
By plugging this estimate in~\eqref{e:InputB+H1detail} and recalling that $\|\mathcal{V}^\delta\|_{L^2(\mathbb{R}^2)} = 1$ and $\mathrm{Supp}(\mathcal{F} \mathcal{V}^\delta) \subset B(0, \delta)$, we deduce the desired estimate~\eqref{e:InputB+H1}.
\smallskip

Finally, we turn to~\eqref{e:InputB+A-A0}. First, we readily deduce from~\eqref{e:fA0} and Definition~\ref{def:V} (in particular,~\eqref{e:SqrtDirac}) that it holds
\begin{equ}
\|{\mathfrak A}_0 \mathcal{V}^\delta\|^2 \lesssim \int_{\mathbb{R}^2} |\mathfrak{e} \cdot k|^2 \, |{\mathfrak F} \mathcal{V}^\delta(k)|^2 \, \mathrm{d} k \lesssim \delta^2 \, ,
\end{equ}
which shows the first statement of~\eqref{e:InputB+A-A0} by taking the limit as $\delta \to 0$. Second, by definition of ${\mathfrak A}_-^\sharp$ and by using the notations~\eqref{e:XiNotation} (with $k_{1:n} = k$), it holds
\begin{equs}
\|{\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} &{\mathfrak B}_+ \mathcal{V}^\delta\|^2 \\
&= \frac{\lambda^4 \varrho^2 (1-\varrho)^2}{\pi^4} \int_{\mathbb{R}^2} \mathrm{d} k \, |\mathfrak{e} \cdot k|^2 \, |{\mathfrak F} \mathcal{V}^\delta(k)|^2 \, \int_{\mathbb{R}^2} \frac{\mathrm{d} p \, \Pi_{p,k-p} \, \chi^\sharp(p, k - p ; k)}{(\mu + \Xi + \Upsilon(\mathrm{Log}(\mu + \Xi_0)) \, \Xi_0^\mathfrak{e})^2} \\
&\lesssim \mu^{-2} \int_{\mathbb{R}^2} \mathrm{d} k \, |\mathfrak{e} \cdot k|^2 \, |{\mathfrak F} \mathcal{V}^\delta(k)|^2 \\
&\lesssim \mu^{-2} \, \delta^2 \, ,
\end{equs}
which shows the second statement of~\eqref{e:InputB+A-A0} by taking the limit as $\delta \to 0$ (even though the estimate deteriorates significantly as $\mu \to 0$). This concludes the proof.

First, we highlight that the estimates~\eqref{e:InputB+L2},~\eqref{e:InputB+H1e},~\eqref{e:InputB+H1gamma} in Lemma~\ref{lem:InputB+} trivially hold if we add a factor $\alpha^{\mathfrak N}$ on the left hand side, up to multiplying the hidden constant in $\lesssim$ by $\alpha^2$, simply because ${\mathfrak B}_+ \mathcal{V}^\delta \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{2}
    \else
        \Gamma H^{}_{2}
    \fi
$. Now, we want to apply Proposition~\ref{p:GenericAnsatz} with $\bm \varphi = {\mathfrak B}_+ \mathcal{V}^\delta$ and $\theta = 1/2 + 3 \varepsilon$; we can bound the constants appearing in~\eqref{e:AnsatzConstantK} by using Lemma~\ref{lem:InputB+} (more precisely, by using~\eqref{e:InputB+L2},~\eqref{e:InputB+H1e},~\eqref{e:InputB+H1gamma} respectively), as follows
\begin{equs}
\, \sqrt{\mu} \, K_{\alpha, 0}^0({\mathfrak B}_+ \mathcal{V}^\delta) &\lesssim_\alpha 1 \, , \label{e:InputB+K0} \\
K_{\alpha, 0}^{1/2, \mathfrak{e}, 1/2 + 3 \varepsilon}({\mathfrak B}_+ \mathcal{V}^\delta) &\lesssim_{\alpha, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} , \qquad \ \label{e:InputB+K1/2fe} \\
K_{\alpha, 0}^{(1+\gamma)/2}({\mathfrak B}_+ \mathcal{V}^\delta) &\lesssim_{\alpha, \gamma} 1 \, . \label{e:InputB+K1/2gamma}
\end{equs}
We then readily deduce the desired estimates~\eqref{e:AnsatzDiffL2},~\eqref{e:AnsatzDiffH1fe} and~\eqref{e:AnsatzDiffH1+gamma} from~\eqref{e:AnsatzL2},~\eqref{e:AnsatzH1fe} and~\eqref{e:AnsatzH1+gamma} respectively.

Now, we show~\eqref{e:AnsatzDiffGen}; first, by the triangle inequality, we have
\begin{equs}
\|\alpha^{\mathfrak N} \, &(\mu - {\mathfrak L}_0)^{-1/2} \, \big({\mathfrak L} \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta) + {\mathfrak B}_+ \mathcal{V}^\delta\big)\| \\
&\leq \|\alpha^{\mathfrak N} \, (- {\mathfrak L}_0)^{-1/2} \, \big((\mu - \bar {\mathfrak L}) \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta) - {\mathfrak B}_+ \mathcal{V}^\delta + {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta \big)\| \\
&\quad + \|\alpha^{\mathfrak N} \, \mu^{-1/2} \, \mu \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\| \\
&\quad + \|\alpha^{\mathfrak N} \, \mu^{-1/2} \, {\mathfrak A}_0 \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\| + \|\alpha \, \mu^{-1/2} \, {\mathfrak A}_-^\sharp (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ \mathcal{V}^\delta\| \, . \label{e:AnsatzDiffGenProof} 
\end{equs}
Then, we bound the first summand by using~\eqref{e:AnsatzGen} and~\eqref{e:InputB+K1/2fe}, the second summand by using~\eqref{e:InputB+L2}, and we notice that the two lasts summands vanish as $\delta \to 0$ because of~\eqref{e:InputB+A-A0}. We give more details for the second-to-last summand: first we observe that ${\mathfrak A}_0$ commutes with $\mathfrak{Ans}_{\mu}$ and ${\mathfrak B}_+$ (cf. Remark~\ref{rmk:fA0}); we deduce, by using also~\eqref{e:AnsatzL2} and the trivial bound $\|{\mathfrak B}_+ \cdot\| \lesssim \|\cdot\|$,
\begin{equ}
\|\alpha^{\mathfrak N} \, {\mathfrak A}_0 \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\| = \|\alpha^{\mathfrak N} \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ {\mathfrak A}_0 \mathcal{V}^\delta)\| \lesssim_\alpha \|\alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1} {\mathfrak B}_+ {\mathfrak A}_0 \mathcal{V}^\delta\| \lesssim \alpha^2 \mu^{-1} \|{\mathfrak A}_0 \mathcal{V}^\delta\| \, ,
\end{equ}
which indeed vanishes as $\delta \to 0$ by~\eqref{e:InputB+A-A0}. Coming back to the bounds of the summands in~\eqref{e:AnsatzDiffGenProof}, we deduce
\begin{equ}
\limsup_{\delta \to 0} \|\alpha^{\mathfrak N} \, (\mu - {\mathfrak L}_0)^{-1/2} \, \big({\mathfrak L} \, \mathfrak{Ans}_{\mu, \delta}^{{\mathfrak B}+} + {\mathfrak B}_+ \mathcal{V}^\delta\big)\| \lesssim_{\alpha, \varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} + 1 + 0 + 0 \lesssim \log_{*}(1/\mu)^{1/6 + \varepsilon} \, ,
\end{equ}
which shows~\eqref{e:AnsatzDiffGen}.
\smallskip

Finally, we tackle~\eqref{e:AnsatzDiffH1}; first, by the triangle inequality, we have
\begin{equs}
\big|\|(- {\mathfrak S})^{1/2} \, &\mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 - \tfrac{1}{2} \, d^{\lim} \log_{*}(1/\mu)^{2/3}\big| \\
&\leq \big|\|(\mu - {\mathfrak S})^{1/2} \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 - \|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1/2} {\mathfrak B}_+ \mathcal{V}^\delta\|^2\big| \\
&\quad + \mu \, \|\mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 + \big|\|(\mu - {\mathfrak L}_{\mu}^{\mathrm{eff}})^{-1/2} \, {\mathfrak B}_+ \mathcal{V}^\delta\|^2 - \tfrac{1}{2} \, d^{\lim} \log_{*}(1/\mu)^{2/3}\big| \, .
\end{equs}
Then, we can bound each summand by using, respectively,~\eqref{e:AnsatzH1precise} together with~\eqref{e:InputB+K1/2fe},~\eqref{e:AnsatzDiffL2},~\eqref{e:InputB+H1detail}; we end up with
\begin{equ}
\limsup_{\delta \to 0} \big|\|(- {\mathfrak S})^{1/2} \, \mathfrak{Ans}_{\mu}({\mathfrak B}_+ \mathcal{V}^\delta)\|^2 - \tfrac{1}{2} \, d^{\lim} \log_{*}(1/\mu)^{2/3}\big| \lesssim_{\varepsilon} \log_{*}(1/\mu)^{1/6 + \varepsilon} + 1 + 1 \lesssim \log_{*}(1/\mu)^{1/6 + \varepsilon} \, ,
\end{equ}
which proves~\eqref{e:AnsatzDiffH1} and concludes the proof.

By orthogonality of chaoses, it is sufficient to prove the bound for any $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
$ and $n \geq 1$. Let us define, for any $d \geq 1$, the function $\varrho_d(g) \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{d}
    \else
        \Gamma_0 h^{}_{d}
    \fi
$ given by
\begin{equ}
\varrho_d(g) \, (x_{1:d}) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{x_{d+1:n} \in \mathbb{Z}^{2(n-d)}} g(x_{1:n})^2 \, .
\end{equ}
We first notice that
\begin{equs}
\|\1_{\mathcal{Z}_{\geq 1}(l)} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 &\leq n^2 \, \|\1_{|x_1 - x_2|_\infty \leq l} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 = n^2 \, \|\1_{|x_1 - x_2|_\infty \leq l} \, \sqrt{\varrho_2(g)}\|_{\ell^2(\mathbb{Z}^{4})}^2 \\
\|\1_{\mathcal{Z}_{\geq 2}(l)} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 &\leq n^3 \, \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_3|_\infty \leq l} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 + n^4 \, \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_4|_\infty \leq l} \, g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \\
&= n^3 \, \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_3|_\infty \leq \ell} \sqrt{\varrho_3(g)}\|_{\ell^2(\mathbb{Z}^{6})}^2 + n^4 \, \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_4|_\infty \leq l} \sqrt{\varrho_4(g)}\|_{\ell^2(\mathbb{Z}^{8})}^2 \, .
\end{equs}
Now we extend the functions $\sqrt{\varrho_d(g)}$ to the diagonal $DI$ as follows: we define $G_d \in 
    \def#2{}
    \ifx#2\empty
        \Gamma L^2_{d}
    \else
        \Gamma H^{}_{d}
    \fi
$ as
\begin{equ}
G_d(x_{1:d}) \stackrel{\mbox{\tiny\rm def}}{=} \frac{1}{\# N_d(x_{1:d})} \sum_{y_{1:d} \in N_d(x_{1:d})} \sqrt{\varrho_d(g)} \, (y_{1:d}) \, ,
\end{equ}
where $N_d(x_{1:d}) := \{x_{1:d}\}$ if $x_{1:d} \in HC$ and $N_d(x_{1:d}) := HC \cap B_\infty(x_{1:d}, d)$ else (we choose the $\ell^\infty$-ball of radius $d$ in order to guarantee that $N_d(x_{1:d})$ is never empty). Since the function $G_d$ extends $\sqrt{\varrho_d(g)}$, we deduce in particular that
\begin{equs}
\|\1_{|x_1 - x_2|_\infty \leq l} \sqrt{\varrho_2(g)}\|_{\ell^2(\mathbb{Z}^4)}^2 \leq \|&\1_{|x_1 - x_2|_\infty \leq \ell} \, G_2\|_{\ell^2(\mathbb{Z}^6)}^2 \lesssim l^2 \, \log_{*}(1/\mu) \, \|(\mu - \mathcal{S})^{1/2} \, G_2\|_{\ell^2(\mathbb{Z}^4)}^2 \, , \\
\|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_3|_\infty \leq l} \sqrt{\varrho_3(g)}\|_{\ell^2(\mathbb{Z}^6)}^2 &\leq \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_3|_\infty \leq l} \, G_3\|_{\ell^2(\mathbb{Z}^6)}^2 \lesssim l^4 \, \|(- \mathcal{S})^{1/2} \, G_3\|_{\ell^2(\mathbb{Z}^6)}^2 \, , \\
\|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_4|_\infty \leq l} \sqrt{\varrho_4(g)}\|_{\ell^2(\mathbb{Z}^8)}^2 &\leq \|\1_{|x_1 - x_3|_\infty \vee |x_2 - x_4|_\infty \leq l} \, G_4\|_{\ell^2(\mathbb{Z}^8)}^2 \lesssim l^4 \, \|(- \mathcal{S})^{1/2} \, G_4\|_{\ell^2(\mathbb{Z}^8)}^2 \, ,
\end{equs}
where we used~\eqref{e:ZiBoundReductionBis} in the last bound of each line. Therefore, it only remains to show that, for every $d \geq 1$ and $\mu \geq 0$, it holds
\begin{equ} \label{ZiBoundHCclaim}
\|(\mu - \mathcal{S})^{1/2} \, G_d\|_{\ell^2(\mathbb{Z}^{2d})}^2 \lesssim_d \|(\mu - S)^{1/2} \, g\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, .
\end{equ}
First, we recall that we equipped $\mathbb{Z}^{2d}$ with a graph structure in the preamble. It is easily checked that, for any given $R \geq 1$, there exists a collection of paths $\Gamma(x_{1:d}, y_{1:d})$, for every $x_{1:d}, y_{1:d}$ in $\mathbb{Z}^{2d} \cap HC$ satisfying $|x_{1:d} - y_{1:d}|_\infty \leq R$, such that: $\Gamma(x_{1:d}, y_{1:d})$ connects $x_{1:d}$ to $y_{1:d}$ and only passes through vertices in $HC$; the length of $\Gamma(x_{1:d}, y_{1:d})$ is bounded by a constant $C = C(d, R)$. In particular, each edge of $\mathbb{Z}^{2d}$ is crossed by at most $C' = C'(d, R)$ distinct paths (because if $\Gamma(x_{1:d}, y_{1:d})$ passes through an edge $e$ then both $x_{1:d}$ and $y_{1:d}$ must be at graph distance smaller than $C$ from $e$). Then, we take $R := l_0 + 2 d$ and deduce by an easy application of the Cauchy-Schwarz inequality (in the spirit of the canonical path method used in Dirichlet form comparisons) that
\begin{equ}
\|(\mu - \mathcal{S})^{1/2} \, G_d\|_{\ell^2(\mathbb{Z}^{2d})}^2 \lesssim_d \|(\mu - S)^{1/2} \sqrt{\varrho_d(g)}\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, .
\end{equ}
Besides, another easy application of the Cauchy-Schwarz inequality (more precisely, the upper bound $\big(\big(\sum a_j^2\big)^{1/2} - \big(\sum b_j^2\big)^{1/2}\big)^2 \leq \sum (a_j - b_j)^2$) shows that
\begin{equ}
\|(\mu - S)^{1/2} \sqrt{\varrho_d(g)}\|_{\ell^2(\mathbb{Z}^d)}^2 \leq \, \|(\mu - S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2d})}^2 \, ,
\end{equ}
which concludes the proof.

Let $g \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
$. We recall that we introduced a graph structure on $\mathbb{Z}^{2n}$ in the preamble. We start by writing 
\begin{equs}
\|(- \mathcal{S})^{1/2} \, \mathsf{Q} g\|_{\ell^2(\mathbb{Z}^{2n})}^2 &\asymp \sum_{x_{1:n} \sim \, y_{1:n} \in \mathbb{Z}^{2n}} \big(\mathsf{Q} g(y_{1:n}) - \mathsf{Q} g(x_{1:n})\big)^2 \\
&= \sum_{0 \leq i, j \leq 2} \sum_{x_{1:n} \sim \, y_{1:n} \in \mathbb{Z}^{2n}} \1_{\mathcal{E}_i}(x_{1:n}) \, \1_{\mathcal{E}_j}(y_{1:n}) \, \big(\mathsf{Q} g(y_{1:n}) - \mathsf{Q} g(x_{1:n})\big)^2 \, ,
\end{equs}
where we have denoted $\mathcal{E}_0 := HC$, $\mathcal{E}_1 := DI \cap \mathcal{Z}_{1}$ and $\mathcal{E}_2 := DI \cap \mathcal{Z}_{\geq 2}$ (we recall that $\mathcal{Z}_\cdot = \mathcal{Z}_\cdot(2 l_0 + 1)$). We denote by $\Phi_{i,j}$ the summand relative to indices $i,j$ (note that $\Phi_{i,j} = \Phi_{j,i}$).
\smallskip

First, recalling that $Q g \equiv g$ on $\mathcal{E}_0 = HC$, we immediately deduce
\begin{equ}
\Phi_{0,0} \lesssim \|(- \mathcal{S})^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, .
\end{equ}

Next, observe that $\Phi_{2,0} + \Phi_{2,1} + \Phi_{2,2}$ equals
\begin{equs}
\sum_{x_{1:n} \in \mathcal{E}_2, y_{1:n} \in \mathbb{Z}^{2n} \colon x_{1:n} \sim y_{1:n}} \mathsf{Q} g(y_{1:n})^2 &\lesssim n \, \sum_{y_{1:n} \in \mathcal{Z}_{\geq 2}(3 l_0 + 1)} \mathsf{Q} g(y_{1:n})^2 \lesssim n \, \|1_{\mathcal{Z}_{\geq 2}(4 l_0 + 1)} \, g\|^2 \, ,
\end{equs}
where in the first bound we used the simple fact that any $y_{1:n} \in \mathbb{Z}^{2n}$ has at most $\# \mathrm{Supp}(s) \times n$ neighbours, while in the second bound we applied~\eqref{e:BoundL2QProof} together with the observation that $\mathsf{Q} g$ and $\mathsf{Q}(1_{\mathcal{Z}_{\geq 2}(4 l_0 + 1)} \, g)$ coincide on $\mathcal{Z}_{\geq 2}(3 l_0 + 1)$. Then, by using~\eqref{e:Z2BoundHC}, we deduce
\begin{equ}
\Phi_{2,0} + \Phi_{2,1} + \Phi_{2,2} \lesssim n^5 \, \|(- S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, .
\end{equ}

Now, we turn to $\Phi_{1,1}$. Observe that, if $x_{1:n} \sim y_{1:n}$ with $x_{1:n}, y_{1:n} \in \mathcal{E}_1$, then there exist distinct indices $a, b, c$ such that $x_a = x_b$, $y_c - x_c \in \mathrm{Supp}(s)$ and $y_d = x_d$ for every $d \ne c$. Hence, we deduce
\begin{equ}
\Phi_{1,1} \leq n^3 \sum_{z \in \mathrm{Supp}(s)} \sum_{x_{1:n} \in \mathcal{E}_1 \, : \, x_1 = x_2} \big(\mathsf{Q} g(x_1, x_1, x_3 + z, x_{4:n}) -  \mathsf{Q} g(x_1, x_1, x_3, x_{4:n})\big)^2 \, .
\end{equ}
Then, using the definition~\eqref{e:defQ} of $\mathsf{Q} f$ and the Cauchy-Schwarz inequality we deduce
\begin{equ}
\Phi_{1,1} \lesssim n^3 \sum_{z \in \mathrm{Supp}(s)} \sum_{x_{1:n} \in \mathcal{E}_1 \, : \, x_1 = x_2} \big(g(x_1 + z_0, x_1, x_3 + z, x_{4:n}) -  g(x_1 + z_0, x_1, x_3, x_{4:n})\big)^2 \, .
\end{equ}
Now, because $x_{1:n} \in \mathcal{E}_1 = DI \cap \mathcal{Z}_1(2 l_0 + 1)$ with $x_1 = x_2$, we deduce that $(x_1 + z_0, x_1, x_3 + z, x_{4:n})$ and $(x_1 + z_0, x_1, x_3, x_{4:n})$ belong to $HC$ (and are neighbours). Thus, the last sum over $x_{1:n}$ is bounded, up to a multiplicative constant, by $\|(- S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2$; we end up with
\begin{equ}
\Phi_{1,1} \lesssim n^3 \, \|(-S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2 \, .
\end{equ}

Finally, we tackle $\Phi_{1,0}$. Observe that, if $x_{1:n} \sim y_{1:n}$ with $x_{1:n} \in \mathcal{E}_1$ and $y_{1:n} \in \mathcal{E}_0$, then there exist distinct indices $a \ne b$ such that $x_a = x_b$, $y_a - x_a \in \mathrm{Supp}(s)$ and $y_c = x_c$ for every $c \ne a$. Recalling the definition~\eqref{e:defQ} of $\mathsf{Q}$, we deduce
\begin{equs}
\Phi_{1,0} &\leq n^2 \sum_{z \in \mathrm{Supp}(s)} \sum_{x_{1:n} \in \mathcal{E}_1 \colon x_1 = x_2} \big(g(x_1 + z_0, x_{2:n}) - g(x_1 + z, x_{2:n})\big)^2 \, .
\end{equs}
Now, we make the following observation\relax{Here is a proof: we distinguish the cases $z \ne -z'$ and $z = -z'$. In the first case, we can take the path $z \to z + z' \to z'$. In the second case, let $z'' \in \mathrm{Supp}(s) \setminus \mathbb{R} z$ (it exists because $D_0$ is not degenerate), then we use the previous case to first connect $z$ to $z''$ and then $z''$ to $z'$.}: for any $z, z'$ in $\mathrm{Supp}(s)$, there exists a path $\Gamma(z,z')$ of length at most $4$ that connects $z$ to $z'$ in $(\mathbb{Z}^2 \setminus \{0\}) \cap B_\infty(0, 2 l_0)$. Then, by using the Cauchy-Schwarz inequality we deduce
\begin{equ}
\Phi_{1,0} \lesssim n^2 \sum_{z \in \mathrm{Supp}(s)} \sum_{(v, v') \in \Gamma(z,z_0)} \sum_{x_{1:n} \in \mathcal{E}_1 \colon x_1 = x_2}\, \big(g(x_1 + v', x_{2:n}) - g(x_1 + v, x_{2:n})\big)^2 \, .
\end{equ}
Now, because $x_{1:n} \in \mathcal{E}_1 = DI \cap \mathcal{Z}_1(2 l_0 + 1)$ with $x_1 = x_2$ and because $\Gamma(z,z')$ takes values in $B_\infty(0, 2 l_0) \setminus \{0\}$, we deduce that $(x_1 + v', x_{2:n})$ and $(x_1 + v, x_{2:n})$ belong to $HC$ (and are neighbours). Thus the last sum over $x_{1:n}$ is bounded, up to a multiplicative constant, by $\|(-S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2$ ; we end up with
\begin{equ}
\Phi_{1,0} \lesssim n^2 \, \|(-S)^{1/2} g\|_{\ell^2(\mathbb{Z}^{2n})}^2.
\end{equ}

Collecting all the previous bounds, we end up with
\begin{equ}
\|(-\mathcal{S})^{1/2} \mathsf{Q} g\|^2 \lesssim n^5 \, \|(- S)^{1/2} g\|^2 \, ,
\end{equ}
which concludes the proof of~\eqref{e:BoundQ}.

\label{lem:Interpolation}
Let $\mathscr S$ be a bounded positive definite self-adjoint operator acting on a Hilbert space $(H, \|\cdot\|)$, and let $B \colon H \times H \to V$ be a continuous bilinear map taking values in a normed vector space $(V, \|\cdot\|_V)$. We assume that $\mathscr S$ is bounded by $C > 0$, and that there exist $\alpha, \beta \geq 0$ such that for every $f, g \in H$
\begin{equ} \label{e:AssumptionInterpolation}
\|B(f,g)\|_V \lesssim \begin{cases}
\|\mathscr S^\alpha f\| \, \|\mathscr S^\beta g\| \\
\|\mathscr S^\beta f\| \, \|\mathscr S^\alpha g\|
\end{cases}
\end{equ}
Then, for any $a, b \geq 0$ such that $\max\{a,b\} < \max\{\alpha, \beta\}$ and $a + b < \alpha + \beta$, we have for every $f, g \in H$
\begin{equ} \label{e:Interpolation}
\|B(f,g)\|_V \lesssim_{a, b, \alpha, \beta} C^{\alpha + \beta - a - b} \, \|\mathscr S^a f\| \, \|\mathscr S^b g\| \, .
\end{equ}

For every $p \geq 0$, we define the dyadic partition of $f$ and $g$ as follows (thanks to the spectral theorem)
\begin{equ}
f_p := \1_{2^{-p-1} C < \mathscr S \leq 2^{-p} C} \, f \, , \quad g_p := \1_{2^{-p-1} C < \mathscr S \leq 2^{-p} C} \, g \, .
\end{equ}
By bilinearity and continuity of $B$, we see that $B(f,g)$ is the limit of $\sum_{0 \leq p,q \leq M} B(f_p, g_q)$ as $M \to \infty$, and thus we deduce
\begin{equ}
\|B(f,g)\|_V \leq \sum_{p,q = 0}^\infty \|B(f_p, g_q)\|_V \, .
\end{equ}
But using~\eqref{e:AssumptionInterpolation} and the definition of $f_p$ and $g_q$, we obtain
\begin{equ}
\|B(f_p, g_q)\|_V \lesssim_{\alpha, \beta}
\begin{cases}
 C^{\alpha+\beta} \, 2^{- \alpha p - \beta q} \, \|f_p\| \|g_q\| \\
 C^{\alpha+\beta} \, 2^{- \beta p - \alpha q} \, \|f_p\| \|g_q\|
\end{cases}
\end{equ}
from which it follows, for any $\theta \in [0,1]$ and $\kappa_1, \kappa_2 \geq 0$,
\begin{equs}
\|B(f_p, g_q)\|_V &\lesssim_{\alpha, \beta} C^{\alpha + \beta} 2^{- (\theta \alpha + (1 - \theta) \beta) p - ((1 - \theta) \alpha + \theta \beta) q} \|f_p\| \|g_q\| \, \\
&\lesssim_{\alpha, \beta, \theta, \kappa_1, \kappa_2} C^{\kappa_1 + \kappa_2} \, 2^{- \kappa_1 p - \kappa_2 q} \, \|\mathscr S^{\theta \alpha + (1 - \theta) \beta - \kappa_1} f_p\| \|\mathscr S^{(1 - \theta) \alpha + \theta \beta - \kappa_2} g_q\| \, .
\end{equs}
Then, we assume $\kappa_1, \kappa_2 > 0$ and use the Cauchy-Schwarz inequality to deduce
\begin{equs}
\|B(f, g)\|_V &\lesssim_{\alpha, \beta, \theta, \kappa_1, \kappa_2} C^{\kappa_1 + \kappa_2} \, \Big(\sum_{p \geq 0} 2^{- \kappa_1 p} \, \|\mathscr S^{\theta \alpha + (1 - \theta) \beta - \kappa_1} f_p\|\Big) \, \Big(\sum_{q \geq 0} 2^{- \kappa_2 q} \, \|\mathscr S^{(1 - \theta) \alpha + \theta \beta - \kappa_2} g_q\|\Big) \\
&\lesssim_{\kappa_1, \kappa_2} C^{\kappa_1 + \kappa_2} \, \|\mathscr S^{\theta \alpha + (1 - \theta) \beta - \kappa_1} f\| \, \|\mathscr S^{(1 - \theta) \alpha + \theta \beta - \kappa_2} g\| \,
\end{equs}
Finally, because of the assumptions on $a$ and $b$, it can be checked that there exist $\theta \in [0,1]$ and $\kappa_1, \kappa_2 > 0$ such that $a = \theta \alpha + (1 - \theta) \beta - \kappa_1$ and $b = (1-\theta) \alpha + \theta \beta - \kappa_2$, which concludes the proof of~\eqref{e:Interpolation}.

\label{lem:UltimateHypercontractivity}

There exists a family of constants $(\alpha(p))_{p > 2}$ (that depends on $\varrho$) satisfying $\alpha(p) \to 1$ as $p \to 2$, such that the following statement holds. For any $\phi \in L^2(\nu_\varrho)$ and local functional\relax{In this section, we often restrict ourselves to local functionals in order to avoid any unnecessary technical difficulties. But, of course, it is possible to extend the upcoming estimates to much larger classes of functionals, simply by using standard approximation arguments.} $\psi \colon \Omega \to \mathbb{R}$, we have
\begin{equs}
\nu_\varrho(|\phi|^p) &\leq \|\alpha(p)^N \phi\|^p \, , \label{e:UltHyper} \\
\nu_\varrho(|\Gamma_2 \psi|^{p/2}) &\lesssim_p \|\alpha(p)^N (- S)^{1/2} \psi\|^p \, , \label{e:UltHyperGamma2} \\
\nu_\varrho(\Gamma_{p} \psi) &\lesssim_p \|\alpha(p)^N \psi\|^{p-2}  \, \|\alpha(p)^N (-S)^{1/2} \psi\|^2 \, . \label{e:UltHyperGammap}
\end{equs}

\label{lem:HypercontractivityL1}
There exists a family of constants $(\beta_1(r))_{r \geq 1}$ (depending on $\varrho$) satisfying $\beta_1(r) \to 1$ as $r \to 1$, such that the following statement holds. For any $r \geq 1$, $n \geq 0$, and local functional $f \colon \Omega \to \mathbb{R}$ belonging to $\bigoplus_{k=0}^n 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{k}
    \else
        \Gamma_0 h^{}_{k}
    \fi
$, we have
\begin{equ} \label{e:HypercontractivityL1}
    \|f\|_{L^r(\nu_\varrho)} \leq \beta_1(r)^n \, \|f\|_{L^1(\nu_\varrho)} \, .
\end{equ}

First, we notice that for any $r \in (1,2]$ and $s \in [2,\infty)$, we have
\begin{equ} \label{e:HypercontractivityL2}
    \|f\|_{L^s(\nu_\varrho)} \leq \beta_2(s)^n \, \|f\|_{L^2(\nu_\varrho)} \, , \quad \|f\|_{L^2(\nu_\varrho)} \leq \beta_2(r)^n \, \|f\|_{L^r(\nu_\varrho)} \, .
\end{equ}
Indeed, this follows from~\eqref{e:Hypercontractivity} (applied respectively to $p = 2$, $q = s$, $f$ ; $p = r$, $q = 2$, $\beta_2(r)^{-N} f$), together with the trivial bounds $\|\beta^{N} f\|_{L^2(\nu_\varrho)} \leq \beta^{n} \, \|f\|_{L^2(\nu_\varrho)}$ and $\beta^{-n} \, \|f\|_{L^2(\nu_\varrho)} \leq \|\beta^{-N} f\|_{L^2(\nu_\varrho)}$ for any $\beta \geq 1$ (which follow from the orthogonality of the chaoses).
\smallskip

Now, we notice that if we prove~\eqref{e:HypercontractivityL1} for some $r_* \in (1, 2)$, say $r_* = 3/2$, then we deduce that~\eqref{e:HypercontractivityL1} also holds for any $r \geq 2$ by taking $\beta_1(r) := \beta_2(r) \, \beta_2(r_*) \, \beta_1(r_*)$ (to see this, bound the $L^r$-norm by the $L^{r_*}$-norm using~\eqref{e:HypercontractivityL2}). Hence, we can assume that $r \in (1, 2)$ without loss of generality. The key idea is the following: we first interpolate the $L^r$-norm between the $L^1$-norm and the $L^2$-norm (by Hölder's inequality) and then we apply~\eqref{e:HypercontractivityL2} to bound the $L^2$-norm by the $L^r$-norm, which can be reabsorbed. More precisely, we write
\begin{equ}
\|f\|_{L^r(\nu_\varrho)}^r \leq \|f\|_{L^1(\nu_\varrho)}^{2 - r} \, \|f\|_{L^2(\nu_\varrho)}^{2 r - 2} \leq \beta_2(r)^{(2r - 2) n} \, \|f\|_{L^1(\nu_\varrho)}^{2 - r} \, \|f\|_{L^r(\nu_\varrho)}^{2r - 2} \, ,
\end{equ}
and then we divide both sides by $\|f\|_{L^r(\nu_\varrho)}^{2 r - 2}$ and raise both sides to the power $1/(2-r)$, which gives
\begin{equ}
\|f\|_{L^r(\nu_\varrho)} \leq \beta_2(r)^{\frac{2 r - 2}{2 - r} \, n} \, \|f\|_{L^1(\nu_\varrho)} \, .
\end{equ}
Thus, we deduce that the estimate~\eqref{e:HypercontractivityL1} holds with $\beta_1(r) := \beta_2(r)^{\frac{2 r - 2}{2 - r}}$. Observe that, as $r \to 1$, we have $\beta_2(r) \to \infty$ and $\frac{2 r - 2}{2 - r} \to 0$, so we need to be careful to show that $\beta_1(r) \to 1$. But, recalling~\eqref{e:Hypercontractivity}, we have
\begin{equ}
\beta_1(r) = \exp\Big(\frac{1}{2 \, (2 - r) \, C_{LS}} \, (r - 1) \log\Big(\frac{1}{r-1}\Big)\Big) \, ,
\end{equ}
which indeed converges to $1$ as $r \to 1$. This concludes the proof.

We will show that the estimates~\eqref{e:UltHyper},~\eqref{e:UltHyperGamma2},~\eqref{e:UltHyperGammap} hold for any choice of $\alpha(p)$ such that
\begin{equ} \label{e:ChoiceAlpha(p)}
\alpha(p) \geq \beta_2(p) \mbox{ and } \alpha(p) > \beta_1(p/2) \, .
\end{equ}
Since $\beta_2(r) \to 1$ as $r \to 2$ (by the formula~\eqref{e:Hypercontractivity}) and $\beta_1(r) \to 1$ as $r \to 1$ (by Lemma~\ref{lem:HypercontractivityL1}), we can indeed find a family of constants $(\alpha(p))_{p > 2}$ satisfying~\eqref{e:ChoiceAlpha(p)} and such that $\alpha(p) \to 1$ as $p \to 2$.
\smallskip

First, by using~\eqref{e:Hypercontractivity} and that $\alpha(p) \geq \beta_2(p)$, we immediately deduce that the desired bound~\eqref{e:UltHyper} holds for any local functional $\phi$; but then an easy approximation argument allows us to extend the estimate to any $\phi \in L^2(\nu_\varrho)$.
\smallskip

Now we tackle the estimates~\eqref{e:UltHyperGamma2} and~\eqref{e:UltHyperGammap} relative to the ``puissance $q$ du champ''. We first point out two basic properties of this object. First, we can bound the ``puissance $q$ du champ'' by its symmetric counterpart, as follows: by using the trivial bound $r(z) \leq 2 \, s(z)$, we deduce $\Gamma_q \psi \leq 2 \, \Gamma_q^s \psi$ where $\Gamma_q^s \psi$ is given by
\begin{equ} \label{e:PuissanceDuChampSymmetric}
\Gamma_q^{s} \psi(\eta) \stackrel{\mbox{\tiny\rm def}}{=} \sum_{x, y \in \mathbb{Z}^2} s(y-x) \, \eta(x) (1 - \eta(y)) \, \big|\psi(\eta^{x,y}) - \psi(\eta)\big|^q = \frac{1}{2} \sum_{x, z \in \mathbb{Z}^2} s(z) \, \big|\psi(\eta^{x,x+z}) - \psi(\eta)\big|^q \, .
\end{equ}
Second, a standard computation shows that the expectation of the ``carré du champ'' is given by the Dirichlet form, as follows
\begin{equ} \label{e:MalliavinIPP}
\nu_\varrho(\Gamma_2 \psi) = 2 \, \|(- S)^{1/2} \, \psi\|^2 \ \, \big(= \nu_\varrho(\Gamma_2^s \psi)\big) \, .
\end{equ}

We turn to the proof of~\eqref{e:UltHyperGamma2}. We start from the bound $\Gamma_2 \psi \leq 2 \, \Gamma_2^s \psi$, then we write $\psi = \sum_{n \geq 0} \psi_n$ with $\psi_n \in 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{n}
    \else
        \Gamma_0 h^{}_{n}
    \fi
$, and we use twice the generic bound $\big(\sum_{n \geq 0} u_n\big)^\theta \lesssim_{\theta, \varepsilon} \sum_{n \geq 0} \, (1+n)^{\theta - 1 + \varepsilon} \, u_n^\theta$ for $\theta \geq 1$ and $\varepsilon > 0$ (use Hölder's inequality), which results in
\begin{equ}
|\Gamma_2 \psi|^{p/2} \lesssim_p |\Gamma_2^s \psi|^{p/2} \lesssim_{p, \varepsilon} \sum_{n \geq 0} (1+n)^{\frac{p}{2} (1 + \varepsilon) + \frac{p}{2} - 1 + \varepsilon} \, |\Gamma_2^s \psi_n|^{p/2} = \sum_{n \geq 0} (1+n)^{\frac{3 p}{2}} \, |\Gamma_2^s \psi_n|^{p/2} \, ,
\end{equ}
where for the last equality we decided to take $\varepsilon = 1$. Now, we notice that $\Gamma_2^s \psi_n \in \bigoplus_{0 \leq k \leq 2n} 
    \def#2{}
    \ifx#2\empty
        \Gamma_0 \ell^2_{k}
    \else
        \Gamma_0 h^{}_{k}
    \fi
$ and apply Lemma~\ref{lem:HypercontractivityL1} (with $2 n$ and $p/2$), which leads to
\begin{equ}
\nu_\varrho\big(|\Gamma_2^s \psi_n|^{p/2}\big) \leq \beta_1(p/2)^{p n} \, \nu_\varrho\big(\Gamma_2^s \psi_n\big)^{p/2} \lesssim_p \beta_1(p/2)^{p n} \, \|(- S)^{1/2} \, \psi_n\|^p \, ,
\end{equ}
where the last equality comes from~\eqref{e:MalliavinIPP}. Thus, we deduce by the orthogonality of chaoses (and the general bound $\sum_{n \geq 0} u_n^p \leq \big(\sum_{n \geq 0} u_n^2\big)^{p/2}$ for $p \geq 2$) that
\begin{equs}
\nu_\varrho\big(|\Gamma_2 \psi|^{p/2}\big) \lesssim_p \sum_{n \geq 0} (1 + n)^{\frac{3 p}{2}} \beta_1(p/2)^{p n} \|(- S)^{1/2} \psi_n\|^p
&\leq \|(1 + N)^{3/2} \beta_1(p/2)^{N} \, (- S)^{1/2} \psi\|^p \\
&\lesssim_{\alpha(p), p} \|\alpha(p)^N (- S)^{1/2} \psi\|^p \, , \label{e:BoundGamma2}
\end{equs}
where in the last bound we used that $\alpha(p) > \beta_1(p/2)$. This shows the desired bound~\eqref{e:UltHyperGamma2}.

We continue with the proof of~\eqref{e:UltHyperGammap}. We start from $\Gamma_p \psi \leq 2 \, \Gamma_p^s \psi$ and we apply~\eqref{e:Hypercontractivity}, which leads to (we use the notation $\nabla^{x,y} F(\eta) := F(\eta^{x,y}) - F(\eta)$ for conciseness; note that $\nabla^{x,y}$ commutes with $N$)
\begin{equ}
\nu_\varrho(\Gamma_p \psi) \leq 2 \, \nu_\varrho(\Gamma_p^s \psi) = \sum_{x, z \in \mathbb{Z}^2} s(z) \, \nu_\varrho(|\nabla^{x,x+z} \psi|^p) \leq \sum_{x, z \in \mathbb{Z}^2} s(z) \, \nu_\varrho(|\nabla^{x,x+z} \beta_2(p)^N \psi|^{2})^{p/2} \, .
\end{equ}
Now, we split the last $\nu_\varrho(...)^{p/2}$ as $\nu_\varrho(...)^{p/2 - 1} \times \nu_\varrho(...)$, then we bound the first factor by using the trivial bound $\|\nabla^{x,y} \cdot\| \leq 2 \, \|\cdot\|$, and finally we notice that the remaining sum equals $2 \, \nu_\varrho(\Gamma_2^s \beta_2(p/2)^N \psi)$ and use~\eqref{e:MalliavinIPP}. This results in
\begin{equs}
\nu_\varrho(\Gamma_p \psi) &\lesssim_p \|\beta_2(p)^N \psi\|^{p - 2} \sum_{x, z \in \mathbb{Z}^2} s(z) \, \nu_\varrho(|\nabla^{x,x+z} \beta_2(p)^{N} \psi|^{2}) \\
&\lesssim \|\beta_2(p)^N \psi\|^{p - 2} \, \|\beta_2(p)^{N} (- S)^{1/2} \psi\| \\
&\leq \|\alpha(p)^N \psi\|^{p - 2} \, \|\alpha(p)^{N} (- S)^{1/2} \psi\| \, , \label{e:BoundGammap}
\end{equs}
where in the third line we used that $\alpha(p) \geq \beta_2(p)$. This shows~\eqref{e:UltHyperGammap} and concludes the proof.

\label{lem:Subgaussian}
For every $\tau \geq 1$, $t_0, t \geq 0$, $\varphi \in \mathcal{S}(\mathbb{R}^2)$ and $\theta \in \mathbb{R}$ we have
\begin{equ} \label{e:Subgaussian}
\mathbb{E}[\exp(\theta \zeta(\varphi))] \vee \nu_\varrho[\exp(\theta Z_t^\tau(\varphi))] \vee \nu_\varrho[E^{\lim}_{Z_{t_0}^\tau(\eta)}[\exp(\theta Y_t^{\lim}(\varphi))]] \leq \exp(c \, \|\varphi\|_{L^2 L_{\mathrm{loc}}^\infty}^2 \, \theta^2/2) \, ,
\end{equ}
where the norm $\|\cdot\|_{L^2 L_{\mathrm{loc}}^\infty(\mathbb{R}^2)}$ on $\mathcal{S}(\mathbb{R}^2)$ is defined as
\begin{equ} \label{e:L2Linfty}
\|\varphi\|_{L^2 L_{\mathrm{loc}}^\infty(\mathbb{R}^2)} \stackrel{\mbox{\tiny\rm def}}{=} \Big(\int_{\mathbb{R}^2} \mathrm{d} x \, \sup_{y \in B(x, 10)} |\varphi(y)|^2\Big)^{1/2} \, .
\end{equ}

First, the subgaussian estimate for $\zeta$ is trivial since $\zeta(\varphi) \in \mathcal{N}(0,\|\varphi\|_{L^2(\mathbb{R}^2)}^2)$.

Next, we show the subgaussian estimates for $Z_t^\tau$ under the probability measure $\nu_\varrho$. Observe that
\begin{equ}
Z_t^\tau(\varphi) = \det(\Sigma^\tau)^{-1/2} \sum_{x \in \mathbb{Z}^2} \varphi\big((\Sigma^\tau)^{-1} (x - \tau t v)\big) \, \sigma(x) \, ,
\end{equ}
and that the random variables $(\sigma(x))_{x \in \mathbb{Z}^2}$ are iid and $c$-subgaussian for some $c = c(\varrho) \in (0,\infty)$. We deduce that $Y^\tau(\varphi)$ is subgaussian with parameter
\begin{equ}
c \, \det(\Sigma^\tau)^{-1} \sum_{x \in \mathbb{Z}^2} \varphi\big((\Sigma^\tau)^{-1} (x - \tau t v)\big)^2 \leq c \, \|\varphi\|_{L^2 L^\infty(\mathbb{R}^2)}^2 \, ,
\end{equ}
where the last bound comes from recognizing a Riemann sum (more precisely, we used that every cell of the affine lattice $(\Sigma^\tau)^{-1} (\mathbb{Z}^2 - \tau t v)$ has volume $\det(\Sigma^\tau)^{-1}$ and diameter less than $10$).
\smallskip

Finally, we show the subgaussian estimates for $Y_t^{\lim}$. By using~\eqref{e:YlimExplicit}, we can write, under the probability measure $\nu_\varrho \, \mathbf E^{\lim}_{Z_{t_0}^\tau}$,
\begin{equ}
Y_t^{\lim}(\varphi) = Z_{t_0}^\tau(K^{\lim}_t \varphi) + \int_0^t \vec{\xi}(\mathrm{d} s) \, [K_{t-s}^{\lim} \, \sqrt{D^{\lim}} \nabla \varphi] \, .
\end{equ}
Observe first that the two summands on the right hand side are independent. On the one hand, we just showed that the first summand is $c \, \|\varphi\|_{L^2 L^\infty(\mathbb{R}^2)}^2$-subgaussian (using in addition the general bound $\|k * \varphi\|_{L^2 L^{\infty}(\mathbb{R}^2)} \leq \|k\|_{L^1(\mathbb{R}^2)} \|\varphi\|_{L^2 L^{\infty}(\mathbb{R}^2)}$, with $k$ being the kernel of $K_t^{\lim}$). On the other hand, the second summand is a centred Gaussian random variable whose variance is bounded by $\int_0^\infty \mathrm{d} r \, \|K_r^{\lim} \sqrt{D^{\lim}} \nabla \varphi\|_{L^2(\mathbb{R}^2)}^2 = \|\varphi\|_{L^2(\mathbb{R}^2)}^2$. Therefore we deduce
\begin{equ}
\nu_\varrho[E^{\lim}_{Y^\tau}[\exp(\theta Y^{\lim}(\varphi))]] \leq \exp((c+1) \|\varphi\|_{L^2 L^\infty(\mathbb{R}^2)}^2/2) \, ,
\end{equ}
which concludes the proof.

{\noindent \it Step 1. Reduction to $F(w) = H_n(w(h), \|h\|_{L^2(\mathbb{R}^2)})$}

We first show that it is sufficient to prove Lemma~\ref{lem:CVchaos} for polynomial cylinder functionals $F$, that is to say of the form~\eqref{e:CylinderFunctional} but with a polynomial function $f$. Let $F$ be a cylinder functional of the form~\eqref{e:CylinderFunctional}. Since $f \in \mathcal{C}(\mathbb{R}^m, \mathbb{R})$ grows at most polynomially fast, it is classical that there exists a sequence of polynomial functions $(p_n)_{n \geq 1}$ such that, as $n \to \infty$,
\begin{equ}
\varepsilon_n := \sup_{y \in \mathbb{R}^m} |f(y) - p_n(y)| \exp(- (|y_1| + \dots + |y_m|)) \to 0 \, .
\end{equ}
We denote by $P_n$ the polynomial cylinder functional $P_n(w) := p_n(w(\varphi_1), \dots, w(\varphi_m))$. Then, by using Lemma~\ref{lem:Subgaussian} and the contractivity of $\mathsf{i}_t^\tau \colon L^2(\mathbb P) \to L^2(\nu_\varrho)$, we immediately deduce
\begin{equ}
\|F(Z_t^\tau) - P_n(Z_t^\tau)\|_{L^2(\nu_\varrho)} \lesssim \varepsilon_n \, , \quad \|\mathsf{i}_t^\tau (F(\zeta) - P_n(\zeta))\|_{L^2(\nu_\varrho)} \lesssim \varepsilon_n \, .
\end{equ}
Thus, if Lemma~\ref{lem:CVchaos} holds for each $P_n$ then we immediately deduce that it also holds for $F$. Consequently, it is sufficient to show Lemma~\ref{lem:CVchaos} for polynomial cylinder functionals.
\smallskip

Furthermore, by using a linearity and polarisation argument, we can reduce the proof of Lemma~\ref{lem:CVchaos} to polynomial cylinder functionals $F$ of the form $F(w) = H_n(w(h), \|h\|_{L^2(\mathbb{R}^2)})$ for $n \geq 0$ and $h \in \mathcal{S}(\mathbb{R}^2)$. Since $F(\zeta) = {\mathfrak I}(h^{\otimes n})$ by definition, we are left to show that
\begin{equ} \label{e:CVchaosGoal1}
\|H_n(Z_t^\tau(h), \|h\|_{L^2(\mathbb{R}^2)}) - \mathsf{i}_t^\tau h^{\otimes n}\|_{L^2(\nu_\varrho)} \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equ}

