\end{equ}

{\noindent \it Step 4. Conclusion}

First, we observe that, by using Hölder's inequality as follows
\begin{equ}
\|f_1 \dots f_m - g_1 \dots g_m\|_{L^2} \leq \sum_{i=1}^m \|f_1\|_{L^{2m}} \dots \|f_{i-1}\|_{L^{2m}} \|f_i - g_i\|_{L^{2m}} \|g_{i+1}\|_{L^{2m}} \dots \|g_{m}\|_{L^{2m}} \, ,
\end{equ}
we can reduce the proof of~\eqref{e:CVchaosGoal3} to the proof of the following estimate: for every $p \geq 1$, as $\tau \to \infty$, it holds
\begin{equ} \label{e:Sktau}
\|S_{t,\tau}^{(1)}\|_{L^p(\nu_\varrho)} = O(1) \, , \quad \|S_{t,\tau}^{(2)} - \|h\|_{L^2(\mathbb{R}^2)}^2\|_{L^p(\nu_\varrho)} \to 0 \, , \quad \|S_{t,\tau}^{(k)}\|_{L^p(\nu_\varrho)} \xrightarrow[]{} 0 \mbox{ if } k \geq 3 \, .
\end{equ}

We start with the following key observation: by using the definition of ${\mathfrak U}_t^\tau$ and recognizing a Riemann sum, it is easily checked that, for any $k \geq 1$,
\begin{equ} \label{e:RiemannLk}
    \sum_{x \in \mathbb{Z}^2} |h_t^\tau(x)|^k \underset{\tau \to \infty}{\sim} \det(\Sigma^\tau)^{1 - k/2} \, \|h\|_{L^k(\mathbb{R}^2)}^k \, .
\end{equ}
First, by using~\eqref{e:RiemannLk} and the boundedness of $\sigma$, we deduce that, for any $k \geq 3$,
\begin{equ}
    \|S_{t, \tau}^{(k)}\|_{L^\infty(\nu_\varrho)} \lesssim_k \sum_{x \in \mathbb{Z}^2} |h_t^\tau(x)|^k \xrightarrow[\tau \to \infty]{} 0 \, ,
\end{equ}
which shows the third statement of~\eqref{e:Sktau}. Second, by using classical subgaussian estimates for bounded centred iid random variables and~\eqref{e:RiemannLk}, we deduce 
\begin{equs}
    \Big\|\sum_{x \in \mathbb{Z}^2} h_t^\tau(x) \, \sigma(x)\Big\|_{L^p(\nu_\varrho)} &\lesssim_p \Big(\sum_{x \in \mathbb{Z}^2} h_t^\tau(x)^2\Big)^{1/2} \lesssim_h 1 \, , \\
    \Big\|\sum_{x \in \mathbb{Z}^2} h_t^\tau(x)^2 \, (\sigma(x)^2 - 1)\Big\|_{L^p(\nu_\varrho)} &\lesssim_p \Big(\sum_{x \in \mathbb{Z}^2} h_t^\tau(x)^4\Big)^{1/2} \xrightarrow[\tau \to \infty]{} 0 \, .
\end{equs}
By using also that $\sum_{x \in \mathbb{Z}^2} h_t^\tau(x)^2 \to \|h\|_{L^2(\mathbb{R}^2)}^2$ by~\eqref{e:RiemannLk}, we deduce the first two statements of~\eqref{e:Sktau}. This concludes the proof.
